SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------
-- Table structure for config_info
-- ----------------------------
DROP TABLE IF EXISTS `config_info`;
CREATE TABLE `config_info` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `data_id` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL COMMENT 'data_id',
  `group_id` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `content` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL COMMENT 'content',
  `md5` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT 'md5',
  `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  `src_user` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin COMMENT 'source user',
  `src_ip` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT 'source ip',
  `app_name` varchar(128) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `tenant_id` varchar(128) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT '' COMMENT '租户字段',
  `c_desc` varchar(256) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `c_use` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `effect` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `type` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `c_schema` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin,
  `encrypted_data_key` varchar(1024) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL DEFAULT '' COMMENT '秘钥',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_configinfo_datagrouptenant` (`data_id`,`group_id`,`tenant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=378 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin COMMENT='config_info';

-- ----------------------------
-- Records of config_info
-- ----------------------------
BEGIN;
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (190, 'application-dev.yml', 'DEFAULT_GROUP', '# 配置文件加密根密码\njasypt:\n  encryptor:\n    password: pigx\n    algorithm: PBEWithMD5AndDES\n    iv-generator-classname: org.jasypt.iv.NoIvGenerator\n\n\nspring:\n  data:\n    redis:\n      host: pigx-redis\n  servlet:\n    multipart:\n      max-file-size: 100MB\n      max-request-size: 100MB\n  cloud:\n    sentinel:\n      eager: true\n      transport:\n        dashboard: pigx-sentinel:5020\n    openfeign:\n      sentinel:\n        enabled: true\n      okhttp:\n        enabled: true\n      httpclient:\n        enabled: false\n        connection-timeout: 20000\n      compression:\n        request:\n          enabled: true\n        response:\n          enabled: true\n\n# 端点对外暴露\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \'*\'          \n  endpoint:\n    restart:\n      enabled: true\n    health:\n      show-details: ALWAYS\n\n#开启灰度\ngray:\n  rule:\n    enabled: true\n\n# mybatis-plus 配置\nmybatis-plus:\n  tenant-enable: ture\n  mapper-locations: classpath:/mapper/*Mapper.xml\n  global-config:\n    capitalMode: true\n    banner: false\n    db-config:\n      id-type: auto\n      select-strategy: not_empty\n      insert-strategy: not_empty\n      update-strategy: not_null\n  type-handlers-package:  com.pig4cloud.pigx.common.data.handler\n  configuration:\n    jdbc-type-for-null: \'null\'\n    call-setters-on-nulls: true\n    shrink-whitespaces-in-sql: true\nmybatis-plus-join:\n  banner: false #关闭连表查询组件banner', '90942d7d4856ccba068fe5847643737d', '2022-12-16 10:44:25', '2023-08-14 11:44:19', 'nacos', '127.0.0.1', '', '', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (191, 'pigx-auth-dev.yml', 'DEFAULT_GROUP', '# 数据源\nspring:\n  freemarker:\n    allow-request-override: false\n    allow-session-override: false\n    cache: true\n    charset: UTF-8\n    check-template-location: true\n    content-type: text/html\n    enabled: true\n    expose-request-attributes: false\n    expose-session-attributes: false\n    expose-spring-macro-helpers: true\n    prefer-file-system-access: true\n    suffix: .ftl\n    template-loader-path: classpath:/templates/\n\n# 前端登录验证码\nsecurity:\n  encodeKey: \'pigxpigxpigxpigx\'\n# 验证码相关配置参考： http://t.cn/A647jEdu\naj:\n  captcha:\n    cache-type: redis\n    water-mark: pig4cloud', 'bb6bd9b9e21afdec3d6c88636387df96', '2022-12-16 10:44:25', '2024-04-20 22:47:21', 'nacos', '0:0:0:0:0:0:0:1', '', '', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (192, 'pigx-codegen-dev.yml', 'DEFAULT_GROUP', '# 数据源\nspring:\n  datasource:\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      driver-class-name: com.mysql.cj.jdbc.Driver\n      username: ${MYSQL_USER:root}\n      password: ${MYSQL_PWD:root}\n      url: jdbc:mysql://${MYSQL_HOST:pigx-mysql}:${MYSQL_PORT:3306}/${MYSQL_DB:pigxx_codegen}?characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=false&useJDBCCompliantTimezoneShift=true&useLegacyDatetimeCode=false&serverTimezone=GMT%2B8&allowMultiQueries=true&allowPublicKeyRetrieval=true\n  resources:\n    static-locations: classpath:/static/,classpath:/views/\n', 'ed6de06e34e2634c28a24e8a1db99b06', '2022-12-16 10:44:25', '2024-02-22 15:08:09', 'nacos', '0:0:0:0:0:0:0:1', '', '', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (193, 'pigx-daemon-elastic-job-dev.yml', 'DEFAULT_GROUP', '# 数据源\nspring:\n  datasource:\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      driver-class-name: com.mysql.cj.jdbc.Driver\n      username: ${MYSQL_USER:root}\n      password: ${MYSQL_PWD:root}\n      url: jdbc:mysql://${MYSQL_HOST:pigx-mysql}:${MYSQL_PORT:3306}/${MYSQL_DB:pigxx_job}?characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=false&useJDBCCompliantTimezoneShift=true&useLegacyDatetimeCode=false&serverTimezone=GMT%2B8&allowMultiQueries=true&allowPublicKeyRetrieval=true', '09996f46e0b80d7b2aa320ef4cb31c82', '2022-12-16 10:44:25', '2023-04-07 14:14:50', 'nacos', '127.0.0.1', '', '', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (194, 'pigx-gateway-dev.yml', 'DEFAULT_GROUP', '# 固定路由转发配置 无修改\nspring:\n  cloud:\n    gateway:\n      routes:\n        - id: openapi\n          uri: lb://pigx-gateway\n          predicates:\n            - Path=/v3/api-docs/**\n          filters:\n            - RewritePath=/v3/api-docs/(?<path>.*), /$\\{path}/$\\{path}/v3/api-docs\n\n# gateway 刷新端点\nmanagement:\n  endpoint:\n    gateway:\n      enabled: true\n', 'd9454d877ff3d8bd3fd0d5be99810195', '2022-12-16 10:44:25', '2024-04-20 22:47:02', 'nacos', '0:0:0:0:0:0:0:1', '', '', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (195, 'pigx-monitor-dev.yml', 'DEFAULT_GROUP', 'spring:\n  # 安全配置\n  security:\n    user:\n      name: ENC(rZHA4LW5hHmhLAAzJoFNag==)     # pigx\n      password: ENC(bjeyh+Aeii3kHXkoo00ZUw==) # pigx\n  autoconfigure:\n    exclude: com.pig4cloud.pigx.common.core.config.JacksonConfiguration\n  boot:\n    admin:\n      ui:\n        title: \'pigx 服务状态监控\'\n        brand: \'pigx 服务状态监控\'\n        external-views:\n          - label: \"SQL监控\"\n            url: /druid/sql.html\n            order: 2000\n            iframe: true\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \'*\'\n  endpoint:\n    health:\n      show-details: ALWAYS  #显示详细信息\n\n\n# druid 监控的服务\nmonitor:\n  applications:\n    - pigx-upms-biz\n', '2bb39e4dee3f90d4186d1e42aa666d2a', '2022-12-16 10:44:25', '2023-04-07 14:12:09', 'nacos', '127.0.0.1', '', '', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (196, 'pigx-upms-biz-dev.yml', 'DEFAULT_GROUP', '## spring security 配置\nsecurity:\n  oauth2:\n    client:\n      ignore-urls:\n        - /druid/**\n\n# 数据源\nspring:\n  autoconfigure:\n    exclude: org.springframework.cloud.gateway.config.GatewayAutoConfiguration,org.springframework.cloud.gateway.config.GatewayClassPathWarningAutoConfiguration\n  datasource:\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      driver-class-name: com.mysql.cj.jdbc.Driver\n      username: ${MYSQL_USER:root}\n      password: ${MYSQL_PWD:root}\n      url: jdbc:mysql://${MYSQL_HOST:pigx-mysql}:${MYSQL_PORT:3306}/${MYSQL_DB:pigxx}?characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=false&useJDBCCompliantTimezoneShift=true&useLegacyDatetimeCode=false&serverTimezone=GMT%2B8&allowMultiQueries=true&allowPublicKeyRetrieval=true\n      stat-view-servlet:\n        enabled: true\n        allow: \"\"\n        url-pattern: /druid/*\n        #login-username: admin\n        #login-password: admin\n      filter:\n        stat:\n          enabled: true\n          log-slow-sql: true\n          slow-sql-millis: 10000\n          merge-sql: false\n        wall:\n          config:\n            multi-statement-allow: true\n\n# 本地文件系统\nfile:\n  local:\n    enable: true\n    basePath: /Users/lengleng/Downloads/files', '28f2305c1cfb413dcc45a3d432ef7098', '2022-12-16 10:44:25', '2024-02-22 15:08:36', 'nacos', '0:0:0:0:0:0:0:1', '', '', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (197, 'pigx-daemon-quartz-dev.yml', 'DEFAULT_GROUP', '# 数据源\nspring:\n  datasource:\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      driver-class-name: com.mysql.cj.jdbc.Driver\n      username: ${MYSQL_USER:root}\n      password: ${MYSQL_PWD:root}\n      url: jdbc:mysql://${MYSQL_HOST:pigx-mysql}:${MYSQL_PORT:3306}/${MYSQL_DB:pigxx_job}?characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=false&useJDBCCompliantTimezoneShift=true&useLegacyDatetimeCode=false&serverTimezone=GMT%2B8&allowMultiQueries=true&allowPublicKeyRetrieval=true\n  resources:\n    static-locations: classpath:/static/,classpath:/views/', '79619124a30cdb6e8bc1046aaa18d91c', '2022-12-16 10:44:25', '2024-04-19 21:49:00', 'nacos', '0:0:0:0:0:0:0:1', '', '', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (198, 'pigx-pay-platform-dev.yml', 'DEFAULT_GROUP', '# 数据源\nspring:\n  datasource:\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      driver-class-name: com.mysql.cj.jdbc.Driver\n      username: ${MYSQL_USER:root}\n      password: ${MYSQL_PWD:root}\n      url: jdbc:mysql://${MYSQL_HOST:pigx-mysql}:${MYSQL_PORT:3306}/${MYSQL_DB:pigxx_pay}?characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=false&useJDBCCompliantTimezoneShift=true&useLegacyDatetimeCode=false&serverTimezone=GMT%2B8&allowMultiQueries=true&allowPublicKeyRetrieval=true\n  freemarker:\n    allow-request-override: false\n    allow-session-override: false\n    cache: true\n    charset: UTF-8\n    check-template-location: true\n    content-type: text/html\n    enabled: true\n    expose-request-attributes: false\n    expose-session-attributes: false\n    expose-spring-macro-helpers: true\n    prefer-file-system-access: true\n    suffix: .ftl\n    template-loader-path: classpath:/templates/\n# 租户表维护\npigx:\n  pay:\n    test: lengleng\n    aliPayConfig:\n      expire-time: 30\n      return-url: http://pig4cloud.com\n      notify-url: http://payx.yunjihuitong.com/pay/notify/ali/callbak\n    wxPayConfig:\n      notify-url: https://admin.pig4cloud.com/pay/notify/wx/callbak\n    mergePayConfig:\n      return-url: http://pig4cloud.com\n      notify-url: http://wechat.pigx.top/pay/notify/merge/callbak\n  xsequence:    #发号器相关配置\n    db:\n      retry-times: 3\n      table-name: pay_sequence', 'f4e5734a99f3c1f059071deac081b33d', '2022-12-16 10:44:25', '2024-02-22 15:09:08', 'nacos', '0:0:0:0:0:0:0:1', '', '', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (199, 'pigx-mp-platform-dev.yml', 'DEFAULT_GROUP', '# 数据源\nspring:\n  datasource:\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      driver-class-name: com.mysql.cj.jdbc.Driver\n      username: ${MYSQL_USER:root}\n      password: ${MYSQL_PWD:root}\n      url: jdbc:mysql://${MYSQL_HOST:pigx-mysql}:${MYSQL_PORT:3306}/${MYSQL_DB:pigxx_mp}?characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=false&useJDBCCompliantTimezoneShift=true&useLegacyDatetimeCode=false&serverTimezone=GMT%2B8&allowMultiQueries=true&allowPublicKeyRetrieval=true\n  resources:\n    static-locations: classpath:/static/,classpath:/views/', 'd5936e0c352fb1fbe1d05f054f14c98a', '2022-12-16 10:44:25', '2024-02-22 15:09:20', 'nacos', '0:0:0:0:0:0:0:1', '', '', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (200, 'pigx-xxl-job-admin-dev.yml', 'DEFAULT_GROUP', '# xxl\nxxl:\n  job:\n    i18n: zh_CN\n    logretentiondays: 30\n    triggerpool:\n      fast.max: 200\n      slow.max: 200\n\n# mybatis\nmybatis:\n  mapper-locations: classpath:/mybatis-mapper/*Mapper.xml\n\n# spring\nspring:\n  datasource:\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      driver-class-name: com.mysql.cj.jdbc.Driver\n      username: ${MYSQL_USER:root}\n      password: ${MYSQL_PWD:root}\n      url: jdbc:mysql://${MYSQL_HOST:pigx-mysql}:${MYSQL_PORT:3306}/${MYSQL_DB:pigxx_job}?characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=false&useJDBCCompliantTimezoneShift=true&useLegacyDatetimeCode=false&serverTimezone=GMT%2B8&allowMultiQueries=true&allowPublicKeyRetrieval=true\n  mvc:\n    static-path-pattern: /static/**\n  freemarker:\n    suffix: .ftl\n    request-context-attribute: request\n    settings:\n      number_format: 0.##########\n  mail:\n    host: smtp.mxhichina.com\n    port: 465\n    from: xxxx@gitee.wang\n    username: xxxx@gitee.wang\n    password: xxxx\n    properties:\n      mail:\n        smtp:\n          auth: true\n          ssl.enable: true\n          starttls.enable: false\n          required: false\n\nmanagement:\n  health:\n    mail:\n      enabled: false\n  endpoints:\n    web:\n      exposure:\n        include: \'*\'\n  endpoint:\n    health:\n      show-details: ALWAYS', '6d70dce1f3ee48f261dce29bcfa99cbb', '2022-12-16 10:44:25', '2023-01-04 18:22:48', 'nacos', '127.0.0.1', '', '', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (201, 'pigx-report-platform-dev.yml', 'DEFAULT_GROUP', 'spring:\n  datasource:\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      driver-class-name: com.mysql.cj.jdbc.Driver\n      username: ${MYSQL_USER:root}\n      password: ${MYSQL_PWD:root}\n      url: jdbc:mysql://${MYSQL_HOST:pigx-mysql}:${MYSQL_PORT:3306}/${MYSQL_DB:pigxx_report}?characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=false&useJDBCCompliantTimezoneShift=true&useLegacyDatetimeCode=false&serverTimezone=GMT%2B8&allowMultiQueries=true&allowPublicKeyRetrieval=true\n  jpa:\n    database-platform: org.hibernate.dialect.MySQL8Dialect\n\nsecurity:\n  oauth2:\n    client:\n      ignore-urls:\n        - /\n        - /api/project/getData\n        - /static/**\n        - /api/project/get-file/*\n\n# 文件上传路径\ngv:\n  img-path: /Users/lengleng/Downloads/img/\n', 'ce3fde4b4592cdd61feb2e443b2ddfe5', '2022-12-16 10:44:25', '2023-04-07 12:56:57', 'nacos', '127.0.0.1', '', '', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (202, 'pigx-jimu-platform-dev.yml', 'DEFAULT_GROUP', 'spring:\n  #配置静态资源\n  mvc:\n    static-path-pattern: /**\n  resource:\n    static-locations: classpath:/static/\n  #配置数据库\n  datasource:\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      driver-class-name: com.mysql.cj.jdbc.Driver\n      username: ${MYSQL_USER:root}\n      password: ${MYSQL_PWD:root}\n      url: jdbc:mysql://${MYSQL_HOST:pigx-mysql}:${MYSQL_PORT:3306}/${MYSQL_DB:pigxx_bi}?characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=false&useJDBCCompliantTimezoneShift=true&useLegacyDatetimeCode=false&serverTimezone=GMT%2B8&allowMultiQueries=true&allowPublicKeyRetrieval=true\n   \n#JimuReport[minidao配置]\nminidao :\n  base-package: org.jeecg.modules.jmreport.desreport.dao*\n  db-type: mysql\n#JimuReport[上传配置]\njeecg :\n  jmreport:\n    customPrePath: /api/jimu\n    # 自动保存\n    autoSave: true\n    # 单位毫秒 默认5*60*1000 \n    interval: 10000\n  # local|minio|alioss\n  uploadType: local\n  # local\n  path :\n    #文件路径A\n    upload: ~/jimu/data\n  # alioss\n  oss:\n    endpoint: oss-cn-beijing.aliyuncs.com\n    accessKey: ??\n    secretKey: ??\n    staticDomain: ??\n    bucketName: ??\n  # minio\n  minio:\n    minio_url: http://minio.jeecg.com\n    minio_name: ??\n    minio_pass: ??\n    bucketName: ??\n#输出sql日志\nlogging:\n  level:\n    org.jeecg.modules.jmreport : debug', '66319da04963c4c7217f807bf1bd5f2d', '2022-12-16 10:44:25', '2024-01-30 20:44:36', 'nacos', '0:0:0:0:0:0:0:1', '', '', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (203, 'pigx-app-server-biz-dev.yml', 'DEFAULT_GROUP', '# 数据源\nspring:\n  datasource:\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      driver-class-name: com.mysql.cj.jdbc.Driver\n      username: ${MYSQL_USER:root}\n      password: ${MYSQL_PWD:root}\n      url: jdbc:mysql://${MYSQL_HOST:pigx-mysql}:${MYSQL_PORT:3306}/${MYSQL_DB:pigxx_app}?characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=false&useJDBCCompliantTimezoneShift=true&useLegacyDatetimeCode=false&serverTimezone=GMT%2B8&allowMultiQueries=true&allowPublicKeyRetrieval=true', 'e4668a1854e92a5a666e83479ef7d26a', '2022-12-19 10:30:07', '2024-02-22 15:09:50', 'nacos', '0:0:0:0:0:0:0:1', '', '', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (204, 'pigx-flow-engine-biz-dev.yml', 'DEFAULT_GROUP', '# 数据源\nspring:\n  datasource:\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      driver-class-name: com.mysql.cj.jdbc.Driver\n      username: ${MYSQL_USER:root}\n      password: ${MYSQL_PWD:root}\n      url: jdbc:mysql://${MYSQL_HOST:pigx-mysql}:${MYSQL_PORT:3306}/${MYSQL_DB:pigxx_flow}?characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=false&useJDBCCompliantTimezoneShift=true&useLegacyDatetimeCode=false&serverTimezone=GMT%2B8&allowMultiQueries=true&nullCatalogMeansCurrent=true', '233121e20445609e1ba378c3686ea7d5', '2023-07-28 13:41:32', '2023-07-28 13:43:36', 'nacos', '0:0:0:0:0:0:0:1', '', '', 'flowable 工作引擎', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (205, 'pigx-flow-task-biz-dev.yml', 'DEFAULT_GROUP', '# 数据源\nspring:\n  datasource:\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      driver-class-name: com.mysql.cj.jdbc.Driver\n      username: ${MYSQL_USER:root}\n      password: ${MYSQL_PWD:root}\n      url: jdbc:mysql://${MYSQL_HOST:pigx-mysql}:${MYSQL_PORT:3306}/${MYSQL_DB:pigxx_flow}?characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=false&useJDBCCompliantTimezoneShift=true&useLegacyDatetimeCode=false&serverTimezone=GMT%2B8&allowMultiQueries=true&nullCatalogMeansCurrent=true', '233121e20445609e1ba378c3686ea7d5', '2023-07-28 13:44:25', '2024-02-22 15:09:34', 'nacos', '0:0:0:0:0:0:0:1', '', '', 'flowable 业务', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (242, 'application-dev.yml', 'DEFAULT_GROUP', '# 配置文件加密根密码\njasypt:\n  encryptor:\n    password: pigx\n    algorithm: PBEWithMD5AndDES\n    iv-generator-classname: org.jasypt.iv.NoIvGenerator\n\n\nspring:\n  data:\n    redis:\n      host: pigx-redis\n  servlet:\n    multipart:\n      max-file-size: 100MB\n      max-request-size: 100MB\n  cloud:\n    sentinel:\n      eager: true\n      transport:\n        dashboard: pigx-sentinel:5020\n    openfeign:\n      sentinel:\n        enabled: true\n      okhttp:\n        enabled: true\n      httpclient:\n        enabled: false\n        connection-timeout: 20000\n      compression:\n        request:\n          enabled: true\n        response:\n          enabled: true\n\n# 端点对外暴露\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \'*\'          \n  endpoint:\n    restart:\n      enabled: true\n    health:\n      show-details: ALWAYS\n\n#开启灰度\ngray:\n  rule:\n    enabled: true\n\n# mybatis-plus 配置\nmybatis-plus:\n  tenant-enable: ture\n  mapper-locations: classpath:/mapper/*Mapper.xml\n  global-config:\n    capitalMode: true\n    banner: false\n    db-config:\n      id-type: auto\n      select-strategy: not_empty\n      insert-strategy: not_empty\n      update-strategy: not_null\n  type-handlers-package:  com.pig4cloud.pigx.common.data.handler\n  configuration:\n    jdbc-type-for-null: \'null\'\n    call-setters-on-nulls: true\n    shrink-whitespaces-in-sql: true\nmybatis-plus-join:\n  banner: false #关闭连表查询组件banner', '90942d7d4856ccba068fe5847643737d', '2025-05-14 08:29:05', '2025-05-14 08:29:05', 'nacos_namespace_migrate', '127.0.0.1', '', 'public', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (243, 'pigx-auth-dev.yml', 'DEFAULT_GROUP', '# 数据源\nspring:\n  freemarker:\n    allow-request-override: false\n    allow-session-override: false\n    cache: true\n    charset: UTF-8\n    check-template-location: true\n    content-type: text/html\n    enabled: true\n    expose-request-attributes: false\n    expose-session-attributes: false\n    expose-spring-macro-helpers: true\n    prefer-file-system-access: true\n    suffix: .ftl\n    template-loader-path: classpath:/templates/\n\n# 前端登录验证码\nsecurity:\n  encodeKey: \'pigxpigxpigxpigx\'\n# 验证码相关配置参考： http://t.cn/A647jEdu\naj:\n  captcha:\n    cache-type: redis\n    water-mark: pig4cloud', 'bb6bd9b9e21afdec3d6c88636387df96', '2025-05-14 08:29:05', '2025-05-14 08:29:05', 'nacos_namespace_migrate', '0:0:0:0:0:0:0:1', '', 'public', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (244, 'pigx-codegen-dev.yml', 'DEFAULT_GROUP', '# 数据源\nspring:\n  datasource:\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      driver-class-name: com.mysql.cj.jdbc.Driver\n      username: ${MYSQL_USER:root}\n      password: ${MYSQL_PWD:root}\n      url: jdbc:mysql://${MYSQL_HOST:pigx-mysql}:${MYSQL_PORT:3306}/${MYSQL_DB:pigxx_codegen}?characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=false&useJDBCCompliantTimezoneShift=true&useLegacyDatetimeCode=false&serverTimezone=GMT%2B8&allowMultiQueries=true&allowPublicKeyRetrieval=true\n  resources:\n    static-locations: classpath:/static/,classpath:/views/\n', 'ed6de06e34e2634c28a24e8a1db99b06', '2025-05-14 08:29:05', '2025-05-14 08:29:05', 'nacos_namespace_migrate', '0:0:0:0:0:0:0:1', '', 'public', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (245, 'pigx-daemon-elastic-job-dev.yml', 'DEFAULT_GROUP', '# 数据源\nspring:\n  datasource:\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      driver-class-name: com.mysql.cj.jdbc.Driver\n      username: ${MYSQL_USER:root}\n      password: ${MYSQL_PWD:root}\n      url: jdbc:mysql://${MYSQL_HOST:pigx-mysql}:${MYSQL_PORT:3306}/${MYSQL_DB:pigxx_job}?characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=false&useJDBCCompliantTimezoneShift=true&useLegacyDatetimeCode=false&serverTimezone=GMT%2B8&allowMultiQueries=true&allowPublicKeyRetrieval=true', '09996f46e0b80d7b2aa320ef4cb31c82', '2025-05-14 08:29:05', '2025-05-14 08:29:05', 'nacos_namespace_migrate', '127.0.0.1', '', 'public', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (246, 'pigx-gateway-dev.yml', 'DEFAULT_GROUP', '# 固定路由转发配置 无修改\nspring:\n  cloud:\n    gateway:\n      routes:\n        - id: openapi\n          uri: lb://pigx-gateway\n          predicates:\n            - Path=/v3/api-docs/**\n          filters:\n            - RewritePath=/v3/api-docs/(?<path>.*), /$\\{path}/$\\{path}/v3/api-docs\n\n# gateway 刷新端点\nmanagement:\n  endpoint:\n    gateway:\n      enabled: true\n', 'd9454d877ff3d8bd3fd0d5be99810195', '2025-05-14 08:29:05', '2025-05-14 08:29:05', 'nacos_namespace_migrate', '0:0:0:0:0:0:0:1', '', 'public', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (247, 'pigx-monitor-dev.yml', 'DEFAULT_GROUP', 'spring:\n  # 安全配置\n  security:\n    user:\n      name: ENC(rZHA4LW5hHmhLAAzJoFNag==)     # pigx\n      password: ENC(bjeyh+Aeii3kHXkoo00ZUw==) # pigx\n  autoconfigure:\n    exclude: com.pig4cloud.pigx.common.core.config.JacksonConfiguration\n  boot:\n    admin:\n      ui:\n        title: \'pigx 服务状态监控\'\n        brand: \'pigx 服务状态监控\'\n        external-views:\n          - label: \"SQL监控\"\n            url: /druid/sql.html\n            order: 2000\n            iframe: true\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \'*\'\n  endpoint:\n    health:\n      show-details: ALWAYS  #显示详细信息\n\n\n# druid 监控的服务\nmonitor:\n  applications:\n    - pigx-upms-biz\n', '2bb39e4dee3f90d4186d1e42aa666d2a', '2025-05-14 08:29:05', '2025-05-14 08:29:05', 'nacos_namespace_migrate', '127.0.0.1', '', 'public', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (248, 'pigx-upms-biz-dev.yml', 'DEFAULT_GROUP', '## spring security 配置\nsecurity:\n  oauth2:\n    client:\n      ignore-urls:\n        - /druid/**\n\n# 数据源\nspring:\n  autoconfigure:\n    exclude: org.springframework.cloud.gateway.config.GatewayAutoConfiguration,org.springframework.cloud.gateway.config.GatewayClassPathWarningAutoConfiguration\n  datasource:\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      driver-class-name: com.mysql.cj.jdbc.Driver\n      username: ${MYSQL_USER:root}\n      password: ${MYSQL_PWD:root}\n      url: jdbc:mysql://${MYSQL_HOST:pigx-mysql}:${MYSQL_PORT:3306}/${MYSQL_DB:pigxx}?characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=false&useJDBCCompliantTimezoneShift=true&useLegacyDatetimeCode=false&serverTimezone=GMT%2B8&allowMultiQueries=true&allowPublicKeyRetrieval=true\n      stat-view-servlet:\n        enabled: true\n        allow: \"\"\n        url-pattern: /druid/*\n        #login-username: admin\n        #login-password: admin\n      filter:\n        stat:\n          enabled: true\n          log-slow-sql: true\n          slow-sql-millis: 10000\n          merge-sql: false\n        wall:\n          config:\n            multi-statement-allow: true\n\n# 本地文件系统\nfile:\n  local:\n    enable: true\n    basePath: /Users/lengleng/Downloads/files', '28f2305c1cfb413dcc45a3d432ef7098', '2025-05-14 08:29:05', '2025-05-14 08:29:05', 'nacos_namespace_migrate', '0:0:0:0:0:0:0:1', '', 'public', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (249, 'pigx-daemon-quartz-dev.yml', 'DEFAULT_GROUP', '# 数据源\nspring:\n  datasource:\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      driver-class-name: com.mysql.cj.jdbc.Driver\n      username: ${MYSQL_USER:root}\n      password: ${MYSQL_PWD:root}\n      url: jdbc:mysql://${MYSQL_HOST:pigx-mysql}:${MYSQL_PORT:3306}/${MYSQL_DB:pigxx_job}?characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=false&useJDBCCompliantTimezoneShift=true&useLegacyDatetimeCode=false&serverTimezone=GMT%2B8&allowMultiQueries=true&allowPublicKeyRetrieval=true\n  resources:\n    static-locations: classpath:/static/,classpath:/views/', '79619124a30cdb6e8bc1046aaa18d91c', '2025-05-14 08:29:05', '2025-05-14 08:29:05', 'nacos_namespace_migrate', '0:0:0:0:0:0:0:1', '', 'public', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (250, 'pigx-pay-platform-dev.yml', 'DEFAULT_GROUP', '# 数据源\nspring:\n  datasource:\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      driver-class-name: com.mysql.cj.jdbc.Driver\n      username: ${MYSQL_USER:root}\n      password: ${MYSQL_PWD:root}\n      url: jdbc:mysql://${MYSQL_HOST:pigx-mysql}:${MYSQL_PORT:3306}/${MYSQL_DB:pigxx_pay}?characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=false&useJDBCCompliantTimezoneShift=true&useLegacyDatetimeCode=false&serverTimezone=GMT%2B8&allowMultiQueries=true&allowPublicKeyRetrieval=true\n  freemarker:\n    allow-request-override: false\n    allow-session-override: false\n    cache: true\n    charset: UTF-8\n    check-template-location: true\n    content-type: text/html\n    enabled: true\n    expose-request-attributes: false\n    expose-session-attributes: false\n    expose-spring-macro-helpers: true\n    prefer-file-system-access: true\n    suffix: .ftl\n    template-loader-path: classpath:/templates/\n# 租户表维护\npigx:\n  pay:\n    test: lengleng\n    aliPayConfig:\n      expire-time: 30\n      return-url: http://pig4cloud.com\n      notify-url: http://payx.yunjihuitong.com/pay/notify/ali/callbak\n    wxPayConfig:\n      notify-url: https://admin.pig4cloud.com/pay/notify/wx/callbak\n    mergePayConfig:\n      return-url: http://pig4cloud.com\n      notify-url: http://wechat.pigx.top/pay/notify/merge/callbak\n  xsequence:    #发号器相关配置\n    db:\n      retry-times: 3\n      table-name: pay_sequence', 'f4e5734a99f3c1f059071deac081b33d', '2025-05-14 08:29:05', '2025-05-14 08:29:05', 'nacos_namespace_migrate', '0:0:0:0:0:0:0:1', '', 'public', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (251, 'pigx-mp-platform-dev.yml', 'DEFAULT_GROUP', '# 数据源\nspring:\n  datasource:\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      driver-class-name: com.mysql.cj.jdbc.Driver\n      username: ${MYSQL_USER:root}\n      password: ${MYSQL_PWD:root}\n      url: jdbc:mysql://${MYSQL_HOST:pigx-mysql}:${MYSQL_PORT:3306}/${MYSQL_DB:pigxx_mp}?characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=false&useJDBCCompliantTimezoneShift=true&useLegacyDatetimeCode=false&serverTimezone=GMT%2B8&allowMultiQueries=true&allowPublicKeyRetrieval=true\n  resources:\n    static-locations: classpath:/static/,classpath:/views/', 'd5936e0c352fb1fbe1d05f054f14c98a', '2025-05-14 08:29:05', '2025-05-14 08:29:05', 'nacos_namespace_migrate', '0:0:0:0:0:0:0:1', '', 'public', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (252, 'pigx-xxl-job-admin-dev.yml', 'DEFAULT_GROUP', '# xxl\nxxl:\n  job:\n    i18n: zh_CN\n    logretentiondays: 30\n    triggerpool:\n      fast.max: 200\n      slow.max: 200\n\n# mybatis\nmybatis:\n  mapper-locations: classpath:/mybatis-mapper/*Mapper.xml\n\n# spring\nspring:\n  datasource:\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      driver-class-name: com.mysql.cj.jdbc.Driver\n      username: ${MYSQL_USER:root}\n      password: ${MYSQL_PWD:root}\n      url: jdbc:mysql://${MYSQL_HOST:pigx-mysql}:${MYSQL_PORT:3306}/${MYSQL_DB:pigxx_job}?characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=false&useJDBCCompliantTimezoneShift=true&useLegacyDatetimeCode=false&serverTimezone=GMT%2B8&allowMultiQueries=true&allowPublicKeyRetrieval=true\n  mvc:\n    static-path-pattern: /static/**\n  freemarker:\n    suffix: .ftl\n    request-context-attribute: request\n    settings:\n      number_format: 0.##########\n  mail:\n    host: smtp.mxhichina.com\n    port: 465\n    from: xxxx@gitee.wang\n    username: xxxx@gitee.wang\n    password: xxxx\n    properties:\n      mail:\n        smtp:\n          auth: true\n          ssl.enable: true\n          starttls.enable: false\n          required: false\n\nmanagement:\n  health:\n    mail:\n      enabled: false\n  endpoints:\n    web:\n      exposure:\n        include: \'*\'\n  endpoint:\n    health:\n      show-details: ALWAYS', '6d70dce1f3ee48f261dce29bcfa99cbb', '2025-05-14 08:29:05', '2025-05-14 08:29:05', 'nacos_namespace_migrate', '127.0.0.1', '', 'public', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (253, 'pigx-report-platform-dev.yml', 'DEFAULT_GROUP', 'spring:\n  datasource:\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      driver-class-name: com.mysql.cj.jdbc.Driver\n      username: ${MYSQL_USER:root}\n      password: ${MYSQL_PWD:root}\n      url: jdbc:mysql://${MYSQL_HOST:pigx-mysql}:${MYSQL_PORT:3306}/${MYSQL_DB:pigxx_report}?characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=false&useJDBCCompliantTimezoneShift=true&useLegacyDatetimeCode=false&serverTimezone=GMT%2B8&allowMultiQueries=true&allowPublicKeyRetrieval=true\n  jpa:\n    database-platform: org.hibernate.dialect.MySQL8Dialect\n\nsecurity:\n  oauth2:\n    client:\n      ignore-urls:\n        - /\n        - /api/project/getData\n        - /static/**\n        - /api/project/get-file/*\n\n# 文件上传路径\ngv:\n  img-path: /Users/lengleng/Downloads/img/\n', 'ce3fde4b4592cdd61feb2e443b2ddfe5', '2025-05-14 08:29:05', '2025-05-14 08:29:05', 'nacos_namespace_migrate', '127.0.0.1', '', 'public', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (254, 'pigx-jimu-platform-dev.yml', 'DEFAULT_GROUP', 'spring:\n  #配置静态资源\n  mvc:\n    static-path-pattern: /**\n  resource:\n    static-locations: classpath:/static/\n  #配置数据库\n  datasource:\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      driver-class-name: com.mysql.cj.jdbc.Driver\n      username: ${MYSQL_USER:root}\n      password: ${MYSQL_PWD:root}\n      url: jdbc:mysql://${MYSQL_HOST:pigx-mysql}:${MYSQL_PORT:3306}/${MYSQL_DB:pigxx_bi}?characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=false&useJDBCCompliantTimezoneShift=true&useLegacyDatetimeCode=false&serverTimezone=GMT%2B8&allowMultiQueries=true&allowPublicKeyRetrieval=true\n   \n#JimuReport[minidao配置]\nminidao :\n  base-package: org.jeecg.modules.jmreport.desreport.dao*\n  db-type: mysql\n#JimuReport[上传配置]\njeecg :\n  jmreport:\n    customPrePath: /api/jimu\n    # 自动保存\n    autoSave: true\n    # 单位毫秒 默认5*60*1000 \n    interval: 10000\n  # local|minio|alioss\n  uploadType: local\n  # local\n  path :\n    #文件路径A\n    upload: ~/jimu/data\n  # alioss\n  oss:\n    endpoint: oss-cn-beijing.aliyuncs.com\n    accessKey: ??\n    secretKey: ??\n    staticDomain: ??\n    bucketName: ??\n  # minio\n  minio:\n    minio_url: http://minio.jeecg.com\n    minio_name: ??\n    minio_pass: ??\n    bucketName: ??\n#输出sql日志\nlogging:\n  level:\n    org.jeecg.modules.jmreport : debug', '66319da04963c4c7217f807bf1bd5f2d', '2025-05-14 08:29:05', '2025-05-14 08:29:05', 'nacos_namespace_migrate', '0:0:0:0:0:0:0:1', '', 'public', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (255, 'pigx-app-server-biz-dev.yml', 'DEFAULT_GROUP', '# 数据源\nspring:\n  datasource:\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      driver-class-name: com.mysql.cj.jdbc.Driver\n      username: ${MYSQL_USER:root}\n      password: ${MYSQL_PWD:root}\n      url: jdbc:mysql://${MYSQL_HOST:pigx-mysql}:${MYSQL_PORT:3306}/${MYSQL_DB:pigxx_app}?characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=false&useJDBCCompliantTimezoneShift=true&useLegacyDatetimeCode=false&serverTimezone=GMT%2B8&allowMultiQueries=true&allowPublicKeyRetrieval=true', 'e4668a1854e92a5a666e83479ef7d26a', '2025-05-14 08:29:05', '2025-05-14 08:29:05', 'nacos_namespace_migrate', '0:0:0:0:0:0:0:1', '', 'public', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (256, 'pigx-flow-engine-biz-dev.yml', 'DEFAULT_GROUP', '# 数据源\nspring:\n  datasource:\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      driver-class-name: com.mysql.cj.jdbc.Driver\n      username: ${MYSQL_USER:root}\n      password: ${MYSQL_PWD:root}\n      url: jdbc:mysql://${MYSQL_HOST:pigx-mysql}:${MYSQL_PORT:3306}/${MYSQL_DB:pigxx_flow}?characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=false&useJDBCCompliantTimezoneShift=true&useLegacyDatetimeCode=false&serverTimezone=GMT%2B8&allowMultiQueries=true&nullCatalogMeansCurrent=true', '233121e20445609e1ba378c3686ea7d5', '2025-05-14 08:29:05', '2025-05-14 08:29:05', 'nacos_namespace_migrate', '0:0:0:0:0:0:0:1', '', 'public', 'flowable 工作引擎', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (257, 'pigx-flow-task-biz-dev.yml', 'DEFAULT_GROUP', '# 数据源\nspring:\n  datasource:\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      driver-class-name: com.mysql.cj.jdbc.Driver\n      username: ${MYSQL_USER:root}\n      password: ${MYSQL_PWD:root}\n      url: jdbc:mysql://${MYSQL_HOST:pigx-mysql}:${MYSQL_PORT:3306}/${MYSQL_DB:pigxx_flow}?characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=false&useJDBCCompliantTimezoneShift=true&useLegacyDatetimeCode=false&serverTimezone=GMT%2B8&allowMultiQueries=true&nullCatalogMeansCurrent=true', '233121e20445609e1ba378c3686ea7d5', '2025-05-14 08:29:05', '2025-05-14 08:29:05', 'nacos_namespace_migrate', '0:0:0:0:0:0:0:1', '', 'public', 'flowable 业务', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (341, 'in-common.yml', 'DEV_GROUP', 'jasypt:\n  encryptor:\n    password: ${JASYPT_PASSWORD:ingot}\n\nserver:\n  forward-headers-strategy: framework\n  tomcat:\n    uri-encoding: UTF-8\n    remote-ip-header: x-forwarded-for\n    threads:\n      max: ${TOMCAT_THREADS_MAX:200}           # 最大线程数\n      min-spare: ${TOMCAT_THREADS_MIN:10}      # 最小空闲线程数\n    max-connections: ${TOMCAT_MAX_CONNECTIONS:8000}  # 最大连接数\n    accept-count: ${TOMCAT_ACCEPT_COUNT:100}   # 等待队列长度\n    connection-timeout: ${TOMCAT_CONNECTION_TIMEOUT:20000}  # 连接超时时间(ms)\n    max-http-form-post-size: ${TOMCAT_MAX_POST_SIZE:104857600}  # 100MB\n  shutdown: graceful  # 优雅关闭\n\n# Spring应用生命周期配置\nspring:\n  lifecycle:\n    timeout-per-shutdown-phase: ${SHUTDOWN_TIMEOUT:30s}\n  web:\n    forwarding:\n      enabled: true\n      strategy: framework\n  webflux:\n    forwarding:\n      enabled: true\n      strategy: framework\n  servlet:\n    multipart:\n      max-file-size: ${MAX_FILE_SIZE:100MB}\n      max-request-size: ${MAX_REQUEST_SIZE:100MB}\n      enabled: true\n      resolve-lazily: true  # 延迟解析，提高性能\n  jackson:\n    date-format: yyyy-MM-dd HH:mm:ss\n    time-zone: GMT+8\n    default-property-inclusion: non_null\n    serialization:\n      write-dates-as-timestamps: false\n      fail-on-empty-beans: false\n  data:\n    redis:\n      database: ${REDIS_DATABASE:0}\n      host: ${REDIS_HOST:localhost}\n      port: ${REDIS_PORT:6379}\n      timeout: ${REDIS_TIMEOUT:3000}\n      ssl:\n        enabled: ${REDIS_SSL_ENABLED:false}\n      lettuce:\n        pool:\n          max-active: ${REDIS_POOL_MAX_ACTIVE:100}    # 最大连接数\n          max-idle: ${REDIS_POOL_MAX_IDLE:20}        # 最大空闲连接\n          min-idle: ${REDIS_POOL_MIN_IDLE:5}         # 最小空闲连接\n          max-wait: ${REDIS_POOL_MAX_WAIT:3000}      # 最大等待时间(ms)\n          time-between-eviction-runs: 60000          # 空闲连接检测周期\n        shutdown-timeout: 5000\n        cluster:\n          refresh:\n            adaptive: true  # 自适应拓扑刷新\n  cloud:\n    sentinel:\n      eager: true\n      log:\n        dir: ${SENTINEL_LOG_DIR:/ingot-data/sentinel/}\n        switch-pid: true\n\n\n# 端点对外暴露\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        # 仅暴露必要端点，生产环境需要通过网关或防火墙限制访问\n        include: ${MANAGEMENT_ENDPOINTS:health,info,metrics}\n      base-path: /actuator\n  endpoint:\n    health:\n      access: unrestricted\n      show-details: ${HEALTH_SHOW_DETAILS:ALWAYS}\n      probes:\n        enabled: true  # 启用K8s健康检查\n    info:\n      access: unrestricted\n  health:\n    redis:\n      enabled: true\n    db:\n      enabled: true\n    diskspace:\n      enabled: true\n      threshold: ${HEALTH_DISK_THRESHOLD:10GB}\n\n\n# Feign配置优化\nfeign:\n  sentinel:\n    enabled: ${FEIGN_SENTINEL_ENABLED:true}\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: false\n    max-connections: ${FEIGN_MAX_CONNECTIONS:400}\n    max-connections-per-route: ${FEIGN_MAX_CONNECTIONS_PER_ROUTE:50}\n    time-to-live: 900\n    connection-timer-repeat: 3000\n  client:\n    config:\n      default:\n        connectTimeout: ${FEIGN_CONNECT_TIMEOUT:5000}\n        readTimeout: ${FEIGN_READ_TIMEOUT:10000}\n        loggerLevel: ${FEIGN_LOGGER_LEVEL:BASIC}  # NONE, BASIC, HEADERS, FULL\n  compression:\n    request:\n      enabled: true\n      mime-types: text/xml,application/xml,application/json\n      min-request-size: 2048\n    response:\n      enabled: true\n      useGzipDecoder: true\n  circuitbreaker:\n    enabled: true\n    alphanumeric-ids:\n      enabled: true\n\n', 'e5ca8786baf49a700858a5e2a2727853', '2026-07-18 06:44:08', '2026-08-08 07:33:58', 'nacos', '192.168.65.1', '', 'ingot', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (342, 'in-database.yml', 'DEV_GROUP', 'spring:\n  datasource:\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      initial-size: ${DB_POOL_INITIAL_SIZE:5}           # 初始化连接数\n      min-idle: ${DB_POOL_MIN_IDLE:5}                   # 最小空闲连接\n      max-active: ${DB_POOL_MAX_ACTIVE:50}              # 最大活跃连接（单服务）\n      max-wait: ${DB_POOL_MAX_WAIT:5000}                # 获取连接最大等待时间(ms)\n      \n      # 连接保活和回收配置\n      test-on-borrow: false                              # 申请连接时不检测（影响性能）\n      test-on-return: false                              # 归还连接时不检测\n      test-while-idle: true                              # 空闲时检测\n      validation-query: SELECT 1                         # 检测SQL\n      validation-query-timeout: 3                        # 检测超时时间(s)\n      time-between-eviction-runs-millis: 60000          # 检测间隔(ms)\n      min-evictable-idle-time-millis: 300000            # 最小空闲时间(ms)\n      max-evictable-idle-time-millis: 900000            # 最大空闲时间(ms)\n      \n      # 连接泄露检测\n      remove-abandoned: ${DB_REMOVE_ABANDONED:true}      # 开启泄露检测\n      remove-abandoned-timeout: ${DB_REMOVE_ABANDONED_TIMEOUT:300}  # 泄露超时时间(s)\n      log-abandoned: ${DB_LOG_ABANDONED:true}            # 记录泄露日志\n      \n      # 连接属性配置\n      connection-properties: druid.stat.mergeSql=true;druid.stat.slowSqlMillis=${DB_SLOW_SQL_MILLIS:2000}\n      connection-init-sqls:\n        - SET NAMES utf8mb4\n        - SET SESSION sql_mode=\'STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION\'\n      \n      # SQL监控配置\n      filters: ${DB_FILTERS:stat,wall}  # 生产环境可移除log4j filter\n      \n      # StatFilter配置\n      stat-view-servlet:\n        enabled: ${DRUID_STAT_VIEW_ENABLED:true}\n        url-pattern: /druid/*\n        reset-enable: false                              # 禁止重置统计数据\n        login-username: ${DRUID_USERNAME:admin}\n        login-password: ${DRUID_PASSWORD:DruidAdmin@2025}\n        allow: ${DRUID_ALLOW:127.0.0.1}                 # IP白名单（生产环境严格控制）\n        deny: ${DRUID_DENY:}                            # IP黑名单\n      \n      # WebStatFilter配置\n      web-stat-filter:\n        enabled: ${DRUID_WEB_STAT_ENABLED:true}\n        url-pattern: /*\n        exclusions: \'*.js,*.gif,*.jpg,*.png,*.css,*.ico,/druid/*,/actuator/*\'\n        session-stat-enable: true\n        session-stat-max-count: 1000\n        principal-session-name: user\n        principal-cookie-name: user\n      \n      # SQL防火墙配置\n      wall:\n        enabled: true\n        config:\n          multi-statement-allow: true                   # 允许多条SQL\n          none-base-statement-allow: true\n          comment-allow: true                            # 允许注释\n          select-allow: true\n          select-into-allow: false                       # 禁止SELECT INTO\n          update-allow: true\n          insert-allow: true\n          delete-allow: true\n          create-table-allow: ${DB_WALL_CREATE_TABLE:false}  # 生产环境禁止\n          drop-table-allow: ${DB_WALL_DROP_TABLE:false}      # 生产环境禁止\n          alter-table-allow: ${DB_WALL_ALTER_TABLE:false}    # 生产环境禁止\n          truncate-allow: ${DB_WALL_TRUNCATE:false}          # 生产环境禁止\n      \n      # 监控统计异步化\n      use-global-data-source-stat: true\n      \n      # 超时配置\n      query-timeout: ${DB_QUERY_TIMEOUT:30}              # 查询超时时间(s)\n      transaction-query-timeout: ${DB_TX_QUERY_TIMEOUT:60}  # 事务查询超时(s)\n      \n      # Keep Alive配置（防止连接被中间件断开）\n      keep-alive: ${DB_KEEP_ALIVE:true}\n      keep-alive-between-time-millis: 120000            # Keep Alive间隔(ms)\n      \n      # 异步初始化\n      async-init: true\n\n# MyBatis配置优化\nmybatis:\n  configuration:\n    map-underscore-to-camel-case: true\n    cache-enabled: ${MYBATIS_CACHE_ENABLED:true}        # 二级缓存\n    lazy-loading-enabled: ${MYBATIS_LAZY_LOADING:true}  # 延迟加载\n    aggressive-lazy-loading: false                       # 关闭积极加载\n    multiple-result-sets-enabled: true\n    use-column-label: true\n    use-generated-keys: true\n    auto-mapping-behavior: partial\n    default-executor-type: reuse                        # 复用执行器\n    default-statement-timeout: ${MYBATIS_STATEMENT_TIMEOUT:30}  # 语句超时(s)\n    log-impl: org.apache.ibatis.logging.slf4j.Slf4jImpl\n\n# MyBatis-Plus配置优化\nmybatis-plus:\n  mapper-locations: classpath:/mapper/*Mapper.xml,classpath*:/mapper/*Mapper.xml,classpath*:sdk/mapper/*.xml\n  configuration:\n    default-enum-type-handler: com.baomidou.mybatisplus.core.handlers.CompositeEnumTypeHandler\n    # 关闭MyBatis-Plus自带日志（使用SLF4J）\n    log-impl: org.apache.ibatis.logging.slf4j.Slf4jImpl\n  global-config:\n    banner: false\n    enable-sql-runner: false\n    db-config:\n      # 主键策略\n      id-type: ${MYBATIS_PLUS_ID_TYPE:ASSIGN_ID}\n      # 逻辑删除配置\n      logic-delete-value: now()                         # 逻辑已删除值\n      logic-not-delete-value: \"null\"                    # 逻辑未删除值\n      # 字段策略\n      insert-strategy: not_null\n      update-strategy: not_null\n\n', '31a08b2a47919732b99fd5973866d969', '2026-07-18 06:46:13', '2026-08-07 08:48:50', 'nacos', '172.88.0.1', '', 'ingot', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (343, 'in-service-pms.yml', 'DEV_GROUP', 'spring:\n  datasource:\n    # 数据库连接URL配置\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_core}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\n# Ingot业务配置\ningot:\n  security:\n    account:\n      # local 或 remote\n      mode: local\n      lockout:\n        # 是否启用自动锁定账号\n        enabled: ${ACCOUNT_LOCKOUT_ENABLED:true}\n        # 失败次数阈值\n        maxAttempts: 5\n        # 锁定时长（分钟），0=永久锁定\n        lockDurationMinutes: 30\n        # 失败计数窗口期（分钟）\n        attemptWindowMinutes: 15\n        # 从第几次失败开始给出\"还剩几次将锁定\"的详细提示， 之前的失败一律返回通用\"账号或密码错误\"，避免暴露用户存在性。\n        # 例：maxAttempts=5，hintAfterAttempts=3 时：\n        # 第 1/2 次：通用提示\n        # 第 3 次：剩余 2 次\n        # 第 4 次：剩余 1 次\n        # 第 5 次：触发自动锁定，下次登录命中锁定分支\n        hintAfterAttempts: 3\n    event:\n      # 总开关。false：SecurityEventPublisher 不投递任何事件；true：由 target 决定落点。\n      enabled: true\n      # 主投递目标。\n      # local  = 写入本服务库 security_event（须 classpath 有 Store，通常配 primary-store: mysql）\n      # center = 经 Feign/Transport 上报 ingot-security 中心 admission\n      target: local\n      # target=local 且 classpath 存在多个 SecurityEventStore 时的主 Store id。\n      # 可选值：mysql（MySqlSecurityEventStore）、log（LogSecurityEventStore）。\n      # 仅有一个 Store Bean 时可省略，自动选中。\n      primary-store: mysql\n      # 次要投递目标（迁移 shadow 双写用）。稳定态留空 []。\n      # 元素取值：local | center；与主 target 去重后额外投递一份，shadow 失败不影响主链路 ack。\n      shadow-targets: []\n      # 上报方模块标识，写入 security_event.source_module。\n      # PMS 填 PMS，Member 填 MEMBER。\n      source-module: PMS\n      # 按事件大类过滤是否上报（enabled=true 时生效）；false 则该类别事件在 Publisher 层被丢弃。\n      categories:\n        # AUTH：登录成功/失败等认证类事件\n        auth: true\n        # ACCOUNT：锁定/解锁/创建/删除等账号类事件\n        account: true\n        # CREDENTIAL：改密/重置/强制改密等凭证类事件\n        credential: true\n        # ACCESS：网关封禁/限流违规等访问防护类；PMS/Member 通常不产生，可保持 true\n        access: true\n      # delivery / mysql 在 in-security-policy.yml（本服务已 import）。\n      # canonical security_event 过期物理删除（PurgeCanonicalSecurityEventTask，cron 0 30 3 * * ?）。\n      retention:\n        # 是否启用定时清理；false 等同永久保留。\n        enabled: true\n        # 保留天数；早于 now-days 的记录被删除；0 表示永久保留。\n        days: 30\n        # 单批 DELETE LIMIT 条数，避免长事务与大锁。\n        batch-size: 500\n        # 单次定时任务最多连续执行的批次数。\n        max-rounds: 100\n        # 单次 retention 任务最大执行时长（秒），超时停止本轮。\n        max-duration-seconds: 30\n        # memory/spool 队列使用率超过该百分比时，retention 让步暂停删除。\n        yield-queue-usage-percent: 50\n      # 按 eventType 覆盖默认优先级（BEST_EFFORT | DURABLE），支持 Nacos 热刷新。\n      # 未配置时使用 DefaultPriorityClassifier 内置默认表；示例：\n      # LOGIN_FAILURE: DURABLE\n      priority-overrides: {}\n  oss:\n    minio:\n      url: ${MINIO_URL:http://ingot-cloud:9090}\n      accessKey: ${MINIO_ACCESS_KEY:2NPpKzxFQjyeMTQFEXA1}\n      secretKey: ${MINIO_SECRET_KEY:8SGAp7DhqZCQrYnU9Poyu888pQOB6w4SP2ILHbVU}\n    rustfs:\n      url: ${RUSTFS_URL:http://ingot-cloud:19000}\n      accessKey: ${RUSTFS_ACCESS_KEY:7eYdiTxLbcpsfaNoKSQ0}\n      secretKey: ${RUSTFS_SECRET_KEY:PgXcoiT9bmYBrIUj6S7QHltf0w8KDzWaC5FMqLsx}\n  social:\n    wechat:\n      miniProgramAppId: wx18dc0ea8c6ca1d7d\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:true}  # 生产环境关闭\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.pms.mapper\n\n# 开发环境日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}\n', '373491346b40d541bd9c1c9567fc0176', '2026-07-18 06:47:23', '2026-08-25 08:51:20', 'nacos', '172.88.0.1', '', 'ingot', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (344, 'in-service-gateway.yml', 'DEV_GROUP', 'spring:\n  cloud:\n    gateway:\n      server:\n        webflux:\n          routes:\n            - id: openapi\n              uri: lb://in-service-gateway\n              predicates:\n                - Path=/v3/api-docs/**\n              filters:\n                - RewritePath=/v3/api-docs/(?<path>.*), /$\\{path}/$\\{path}/v3/api-docs\n            - id: in-service-iam\n              uri: lb://in-service-iam\n              predicates:\n                - Path=/iam/**\n              filters:\n                - StripPrefix=1\n            - id: in-service-member\n              uri: lb://in-service-member\n              predicates:\n                - Path=/member/**\n              filters:\n                - StripPrefix=1\n            - id: in-service-security\n              uri: lb://in-service-security\n              predicates:\n                - Path=/security/**\n              filters:\n                - StripPrefix=1\n            - id: in-crypto-pubkey\n              uri: lb://in-service-bff\n              predicates:\n                - Path=/crypto/public-keys\n            - id: in-service-bff\n              uri: lb://in-service-bff\n              predicates:\n                - Path=/bff/**\n            - id: in-service-auth\n              uri: lb://in-service-auth\n              predicates:\n                - Path=/auth/client/**\n              filters:\n                - StripPrefix=1\n\ningot:\n  vc:\n    verifyUrls: []\n    image:\n      opsLimitGetPerMinute: 20\n      opsLimitCheckPerMinute: 40\n  security:\n    account:\n      gateway:\n        # 是否启用账号锁定 AccountLockFilter，默认开启\n        enabled: true\n        # 不检查锁定状态的路径 Ant 模式。\n        excludePathPatterns:\n          - /actuator/**\n          - /bff/auth/**\n    policy:\n      # GatewayRuleClientProperties\n      client:\n        # 跨节点失效订阅开关\n        invalidation-enabled: true\n        # 是否启用 remote → LKG → Nacos 地板 弹性降级链\n        resilience-enabled: true\n        # remote 不可用且 LKG 为空时，是否回落到 Nacos 地板配置\n        local-floor-enabled: true\n        # 共享快照的分层缓存参数。\n        cache:\n          # 1级缓存存活时间\n          l1-ttl: 5m\n          # 2级缓存存活时间\n          l2-ttl: 30m\n    # 限流域：编译为 Sentinel GatewayFlowRule；未配置的路径默认不限流（白名单式）\n    ratelimit:\n      enabled: true\n      policy:\n        mode: local\n    # 黑白名单：静态名单 + Redis 临时封禁（限流违规升级）\n    blacklist:\n      enabled: false\n      policy:\n        mode: local\n    # 限流违规升级：滑动窗口计数\n    violation-escalation:\n      enabled: true\n      policy:\n        mode: local\n    # 挑战验证开关与来源；groups/policies 地板在 in-security-gateway.yml\n    challenge:\n      enabled: true\n      policy:\n        mode: local\n    # 事件配置\n    event:\n      # 总开关；Gateway 仅在上报 ACCESS 类事件时依赖此项。\n      enabled: true\n      # center：经 Feign 上报 ingot-security admission；不写网关本地 security_event 表。\n      target: center\n      # Gateway 稳定态不需要 shadow；留空 []。\n      shadow-targets: []\n      # 写入中心 security_event.source_module。\n      source-module: GATEWAY\n      # Gateway 通常只产生 ACCESS 类事件；其余类别关闭可减少无效配置。\n      categories:\n        auth: false\n        account: false\n        credential: false\n        access: true\n      # target=center 时 BEST_EFFORT 仍走 memory 缓冲后再 Feign 批量上报。\n      delivery:\n        memory:\n          queue-capacity: 2048\n          batch-size: 32\n          poll-timeout-ms: 100\n          shutdown-timeout-ms: 5000\n        # DURABLE 事件（如 BLACKLIST_BLOCK）仍需要 spool；未显式配置时使用下方 Java 默认值：\n        # spool.directory=./logs/security-recording/spool, max-bytes=1GB, ...\n      # Gateway 不写本地 canonical 表，通常不需要 retention；中心库由 in-service-security 清理。\n      retention:\n        enabled: false\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n\n# 开发环境日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}', '9f2ab6c7eeae4bb1505cfcb640c9dcdf', '2026-07-18 06:47:41', '2026-09-16 03:11:53', 'nacos', '172.88.0.1', '', 'ingot', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (345, 'in-service-auth.yml', 'DEV_GROUP', 'spring:\n  mvc:\n    static-path-pattern: /static/**\n  thymeleaf:\n    cache: false\n    prefix: classpath:/templates/\n    suffix: .html\n    encoding: UTF-8\n    servlet:\n      content-type: text/html\n  datasource:\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_auth}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\ningot:\n  security:\n    oauth2:\n      auth:\n        loginFormUrl: https://login.ingotcloud.top/oauth2/challenge\n        issuer: http://${SERVICE_AUTH_HOST:localhost:5100}\n      resource:\n        publicUrls:\n          - /favicon.ico,GET\n          - /static/**,GET\n          - /logout,*\n          - /error,*\n    jwk:\n      key-lifetime: 90d\n      key-grace-period: 2h\n      max-active-keys: 3\n      cache-refresh-interval: 5m\n      master-key: ${AUTH_JWK_MASTER_KEY:a7A7FJ9KdQutfjbQh8sZSt2kcNtl/JUkmEI73aCR080=}\n      enable-encryption: true\n    access:\n      mode: local\n      loginFailure:\n        ip:\n          enabled: true\n          # 50次命中\n          maxAttempts: 50\n          # 时间窗口\n          windowMinutes: 1\n          # 锁定时间，秒\n          blockTtlSec: 3600\n          blockKeyType: \"IP\"\n        device:\n          enabled: false\n        client:\n          enabled: false\n        accountIp:\n          enabled: false\n    session:\n      # 会话存储不可用宽限期；超期一律拒绝，会话键不存在不在宽限范围内\n      store-unavailable-grace: 30s\n      # local：并发策略只读下面的 concurrency 段，不依赖安全中心（A9 场景）\n      mode: local\n      concurrency:\n        # 关闭后登录路径退回「只认 Client 的 UNIQUE / STANDARD」，紧急回退开关\n        enabled: true\n        # 0 = 不限并发；此时 Client 配置为 UNIQUE 仍按单会话处理\n        max-sessions: 0\n        # 会话数统计维度\n        dimension: USER_CLIENT\n        # 超限处置方式\n        overflow: KICK_OLDEST\n        # 管理用户（UserTypeEnum.ADMIN）是否强制单会话\n        admin-forbid-concurrent: false\n    event:\n      # 安全事件总开关；false 时不做任何上报\n      enabled: true\n      # center：会话撤销等 AUTH 事件 Feign 上报安全中心，Auth 本库不落 security_event\n      target: center\n      shadow-targets: []\n      # 写入 security_event.source_module\n      sourceModule: AUTH\n      # 安全事件大类上报开关\n      categories:\n        auth: true\n        account: false\n        credential: false\n        access: false\n      retention:\n        enabled: false\n\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:true}  # 生产环境关闭\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.auth.mapper\n\n# 日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}', '77a584c164aa7bbdf8b47f52c08b5b6c', '2026-07-18 06:47:57', '2026-09-01 07:18:37', 'nacos', '172.88.0.1', '', 'ingot', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (346, 'in-service-member.yml', 'DEV_GROUP', 'spring:\n  datasource:\n    # 数据库连接URL配置\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_member}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\n# Ingot业务配置\ningot:\n  security:\n    account:\n      # local 或 remote\n      mode: local\n      lockout:\n        # 是否启用自动锁定账号\n        enabled: ${ACCOUNT_LOCKOUT_ENABLED:true}\n        # 失败次数阈值\n        maxAttempts: 5\n        # 锁定时长（分钟），0=永久锁定\n        lockDurationMinutes: 30\n        # 失败计数窗口期（分钟）\n        attemptWindowMinutes: 15\n        # 从第几次失败开始给出\"还剩几次将锁定\"的详细提示， 之前的失败一律返回通用\"账号或密码错误\"，避免暴露用户存在性。\n        # 例：maxAttempts=5，hintAfterAttempts=3 时：\n        # 第 1/2 次：通用提示\n        # 第 3 次：剩余 2 次\n        # 第 4 次：剩余 1 次\n        # 第 5 次：触发自动锁定，下次登录命中锁定分支\n        hintAfterAttempts: 3\n    event:\n      # 总开关。false：SecurityEventPublisher 不投递任何事件；true：由 target 决定落点。\n      enabled: true\n      # 主投递目标。\n      # local  = 写入本服务库 security_event（须 classpath 有 Store，通常配 primary-store: mysql）\n      # center = 经 Feign/Transport 上报 ingot-security 中心 admission\n      target: local\n      # target=local 且 classpath 存在多个 SecurityEventStore 时的主 Store id。\n      # 可选值：mysql（MySqlSecurityEventStore）、log（LogSecurityEventStore）。\n      # 仅有一个 Store Bean 时可省略，自动选中。\n      primary-store: mysql\n      # 次要投递目标（迁移 shadow 双写用）。稳定态留空 []。\n      # 元素取值：local | center；与主 target 去重后额外投递一份，shadow 失败不影响主链路 ack。\n      shadow-targets: []\n      # 上报方模块标识，写入 security_event.source_module。\n      # PMS 填 PMS，Member 填 MEMBER。\n      source-module: MEMBER\n      # 按事件大类过滤是否上报（enabled=true 时生效）；false 则该类别事件在 Publisher 层被丢弃。\n      categories:\n        # AUTH：登录成功/失败等认证类事件\n        auth: true\n        # ACCOUNT：锁定/解锁/创建/删除等账号类事件\n        account: true\n        # CREDENTIAL：改密/重置/强制改密等凭证类事件\n        credential: true\n        # ACCESS：网关封禁/限流违规等访问防护类；PMS/Member 通常不产生，可保持 true\n        access: true\n      # delivery / mysql 在 in-security-policy.yml（本服务已 import）。\n      # canonical security_event 过期物理删除（PurgeCanonicalSecurityEventTask，cron 0 30 3 * * ?）。\n      retention:\n        # 是否启用定时清理；false 等同永久保留。\n        enabled: true\n        # 保留天数；早于 now-days 的记录被删除；0 表示永久保留。\n        days: 30\n        # 单批 DELETE LIMIT 条数，避免长事务与大锁。\n        batch-size: 500\n        # 单次定时任务最多连续执行的批次数。\n        max-rounds: 100\n        # 单次 retention 任务最大执行时长（秒），超时停止本轮。\n        max-duration-seconds: 30\n        # memory/spool 队列使用率超过该百分比时，retention 让步暂停删除。\n        yield-queue-usage-percent: 50\n      # 按 eventType 覆盖默认优先级（BEST_EFFORT | DURABLE），支持 Nacos 热刷新。\n      # 未配置时使用 DefaultPriorityClassifier 内置默认表；示例：\n      # LOGIN_FAILURE: DURABLE\n      priority-overrides: {}\n  oss:\n    minio:\n      url: ${MINIO_URL:http://ingot-cloud:9090}\n      accessKey: ${MINIO_ACCESS_KEY:2NPpKzxFQjyeMTQFEXA1}\n      secretKey: ${MINIO_SECRET_KEY:8SGAp7DhqZCQrYnU9Poyu888pQOB6w4SP2ILHbVU}\n  social:\n    wechat:\n      miniProgramAppId: wx18dc0ea8c6ca1d7d\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:true}  # 生产环境关闭\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.member.mapper\n\n# 开发环境日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}\n', '9cbb3f1ed99837f8fcc1691c5e046325', '2026-07-18 06:51:29', '2026-08-25 08:49:52', 'nacos', '172.88.0.1', '', 'ingot', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (347, 'in-service-security.yml', 'DEV_GROUP', 'spring:\n  datasource:\n    # 数据库连接URL配置\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_security}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\n# Ingot业务配置\ningot:\n  security:\n    event:\n      # 中心 admission 接收的事件异步入库；false 则 admission 入队被禁用。\n      enabled: true\n      # 中心将事件写入本库 ingot_security.security_event。\n      target: local\n      primary-store: mysql\n      shadow-targets: []\n      source-module: SECURITY\n      categories:\n        auth: true\n        account: true\n        credential: true\n        access: true\n      # 中心库数据量大，retention.days 可按合规要求拉长（如 90～180）。\n      # delivery / mysql 在 in-security-policy.yml（本服务已 import）。\n      retention:\n        enabled: true\n        days: 90\n        batch-size: 500\n        max-rounds: 100\n        max-duration-seconds: 30\n        yield-queue-usage-percent: 50\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:true}  # 生产环境关闭\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.security.mapper\n\n# 开发环境日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}\n', 'ab8fbef1d1d6f02eb8ae590e763085ab', '2026-07-18 06:51:55', '2026-08-25 08:52:17', 'nacos', '172.88.0.1', '', 'ingot', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (348, 'in-service-bff.yml', 'DEV_GROUP', 'ingot:\n  security:\n    oauth2:\n      resource:\n        public-urls:\n          - /crypto/public-keys,GET\n    # 账号锁定 BFF 登录短路：解密后查 Redis name key；默认拦截不调 Auth\n    account:\n      bff:\n        # 是否在登录解密后检查 Redis name key，默认开启。\n        enabled: true\n        # BFF 拦截时是否仍调 Auth 以产生 LOGIN_FAILURE；默认关闭。\n        emit-login-failure-on-bff-block: false\n  bff:\n    # 管理用户:0, C端用户:1\n    user-type: \"0\"\n    session-ttl: 7200\n    transaction-ttl: 600\n    ticket-ttl: 60\n    security:\n      # 客户端指纹校验，防止 Cookie 盗用\n      fingerprint-enabled: ${BFF_FINGERPRINT_ENABLED:true}\n      # 指纹模式: device（前端设备指纹，推荐）/ ip_ua（服务端 IP+UA，降级方案）\n      fingerprint-mode: ${BFF_FINGERPRINT_MODE:device}\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n\n# 开发环境日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}', '7598dcd268a69f34a8ed639cf22cdc60', '2026-07-18 06:52:14', '2026-09-17 03:00:01', 'nacos', '192.168.65.1', '', 'ingot', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (349, 'in-security-crypto.yml', 'DEV_GROUP', 'ingot:\n  security:\n    crypto:\n      hybrid:\n        response-wrap: DATA_ONLY          # DATA_ONLY:只加密 R.data, FULL:加密所有\n        active-kid: k-2026-08             # 当前激活 kid，响应头 In-Crypto-Kv 会回这个值\n        public-key-endpoint-enabled: true # 仅公钥下发服务开 true，其它服务可 false\n        replay-namespace: crypto\n        key-pairs:\n          k-2026-07:                      # kid 自定义，与前端请求头 In-Crypto-Kv 对应\n            public-key: \n            private-key: \n          k-2026-08:\n            public-key: \n            private-key: \n      secretKeys:\n        # 加密密钥 - 生产环境必须通过环境变量配置\n        aes: ${CRYPTO_AES_KEY:ingotingotingot1}\n        aes_gcm: ${CRYPTO_AES_GCM_KEY:ingotingotingot1}', '31351f80f66c047c1afa4d6293322545', '2026-07-18 07:03:20', '2026-07-18 07:19:58', 'nacos', '172.88.0.1', '', 'ingot', '加密算法，密钥，密钥轮换', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (350, 'in-security-policy.yml', 'DEV_GROUP', 'ingot:\n  security:\n    ignoreTenantValidateRoleCodeList:\n      - role_admin\n    \n    # 重放配置\n    replay:\n      enabled: true\n      window: 5m\n      clock-skew: 5m\n      key-prefix: \"replay:\"\n      fail-open: false\n    \n    # 凭证配置\n    credential:\n      cache:\n        # 是否启用 L1 Caffeine\n        l1-enabled: true\n        # L1 TTL（默认 5 分钟）\n        l1-ttl: 5m\n        # L1 最大条目数（实际单 key，但保留容量）\n        l1-maximum-size: 16\n        # 是否启用 L2 Redis\n        l2-enabled: true\n        # L2 TTL（默认 30 分钟）\n        l2-ttl: 30m\n        # L2 Redis key 前缀\n        l2-key-prefix: \"in:credential:configs:\"\n        # 是否启用跨节点失效订阅\n        invalidation-enabled: true\n      policy:\n        # 策略加载模式：local（本地配置）或 remote（远程加载）\n        mode: ${CREDENTIAL_MODE:local}\n\n        # 本地策略配置\n        strength:\n          # 是否启用\n          enabled: true\n          # 最小长度\n          min-length: 8\n          # 最大长度\n          max-length: 32\n          # 是否要求大写字母\n          require-uppercase: false\n          # 是否要求小写字母\n          require-lowercase: false\n          # 是否要求数字\n          require-digit: false\n          # 是否要求特殊字符\n          requireSpecialChar: false\n          # 特殊字符集合\n          specialChars: \"!@#$%^&*()_+-=[]{}|;:,.<>?\"\n          # 禁止的模式\n          forbiddenPatterns:\n            - \"password\"\n            - \"123456\"\n            - \"admin\"\n            - \"qwerty\"\n          # 禁止包含用户属性\n          forbidUserAttributes: false\n\n        history:\n          # 是否启用\n          enabled: true\n          # 检查最近N次密码\n          check-count: 5\n\n        expiration:\n          # 是否启用 \n          enabled: false\n          # 最大有效天数\n          max-days: 90\n          # 提前警告天数\n          warningDaysBefore: 7\n          # 宽限登录次数\n          graceLoginCount: 3\n\n        initialPassword:\n          # 初始密码生成方式：RANDOM-随机生成；FIXED-统一默认密码\n          generation: RANDOM\n          # 随机初始密码长度（generation=RANDOM 时生效）\n          length: 10\n          # 统一默认密码（generation=FIXED 时生效）\n          fixedPassword: In@123456\n          # 初始密码有效小时数；0 表示不限制。超过后视为初始密码失效，需重新重置。\n          validHours: 72\n          # 用后失效：初始密码修改成功后即失效（依赖 mustChangePwd/force_change 清除，默认 true）\n          oneTime: true\n          # 首次登录是否强制修改密码\n          forceChangeOnFirstLogin: true\n\n    # 永久锁 Redis TTL（PMS/Member 写、BFF 读）；必须全局同一份\n    account:\n      signal:\n        # 永久锁定时 uid/name key 的 TTL（天），默认 30。\n        permanent-lock-ttl-days: 30\n\n    # PMS/Member/Security 写本地 canonical / spool 时共用。\n    # Auth/Gateway 不 import 本文件；BFF import 但不启用 recording。\n    event:\n      # 投递层：BEST_EFFORT 走 memory，DURABLE 走 spool（两条独立管道，非溢出关系）。\n      delivery:\n        # BEST_EFFORT 有界内存队列参数；后台线程 security-recording-memory 攒批后投递。\n        memory:\n          # 内存队列容量；满时新 BEST_EFFORT 事件 DROPPED，不阻塞业务线程。\n          queue-capacity: 2048\n          # memory worker 单次 claim 条数上限。\n          batch-size: 32\n          # worker 攒批 poll 超时（毫秒）；队列空则等待该时长后再次 poll。\n          poll-timeout-ms: 100\n          # 进程关闭时等待 memory worker 排空队列的最长时间（毫秒）。\n          shutdown-timeout-ms: 5000\n        # DURABLE 本地 file spool；后台线程 security-recording-durable 持续 claim → 投递 → ack/nack 重试。\n        spool:\n          # spool 根目录（append-only segment 文件）。\n          directory: /ingot-data/security-recording/spool\n          # spool 目录总磁盘配额（如 1GB、512MB）。\n          max-bytes: 1GB\n          # 单个 segment 文件大小上限，达上限滚动新文件。\n          segment-bytes: 64MB\n          # 业务线程同步等待 spool 接纳 DURABLE 事件的最长时间（毫秒）；超时返回 FAILED（业务仍 fail-open）。\n          durable-ack-timeout-ms: 20\n          # durable worker 每次从 spool claim 的条数上限。\n          replay-batch-size: 32\n          # 投递失败 nack 后重试初始退避（毫秒）。\n          retry-initial-ms: 1000\n          # 重试退避上限（毫秒）。\n          retry-max-ms: 60000\n      # MySQL SecurityEventStore 写入侧参数（target=local 且 primary-store=mysql 时生效）。\n      mysql:\n        # 并发写入信号量许可数；默认 1，避免 canonical security_event 热点写冲突。\n        max-concurrent-writes: 1\n        # 单批 INSERT 事务超时（秒）。\n        transaction-timeout-seconds: 5\n', 'b12403c5dd8909e6e907d2d53964e0aa', '2026-07-18 07:20:58', '2026-08-25 08:46:29', 'nacos', '172.88.0.1', '', 'ingot', '密码策略，登录策略，会话策略，账号策略等', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (351, 'in-common.yml', 'TEST_GROUP', 'jasypt:\n  encryptor:\n    password: ${JASYPT_PASSWORD:ingot}\n\nserver:\n  forward-headers-strategy: framework\n  tomcat:\n    uri-encoding: UTF-8\n    remote-ip-header: x-forwarded-for\n    threads:\n      max: ${TOMCAT_THREADS_MAX:200}           # 最大线程数\n      min-spare: ${TOMCAT_THREADS_MIN:10}      # 最小空闲线程数\n    max-connections: ${TOMCAT_MAX_CONNECTIONS:8000}  # 最大连接数\n    accept-count: ${TOMCAT_ACCEPT_COUNT:100}   # 等待队列长度\n    connection-timeout: ${TOMCAT_CONNECTION_TIMEOUT:20000}  # 连接超时时间(ms)\n    max-http-form-post-size: ${TOMCAT_MAX_POST_SIZE:104857600}  # 100MB\n  shutdown: graceful  # 优雅关闭\n\n# Spring应用生命周期配置\nspring:\n  lifecycle:\n    timeout-per-shutdown-phase: ${SHUTDOWN_TIMEOUT:30s}\n  web:\n    forwarding:\n      enabled: true\n      strategy: framework\n  webflux:\n    forwarding:\n      enabled: true\n      strategy: framework\n  servlet:\n    multipart:\n      max-file-size: ${MAX_FILE_SIZE:100MB}\n      max-request-size: ${MAX_REQUEST_SIZE:100MB}\n      enabled: true\n      resolve-lazily: true  # 延迟解析，提高性能\n  jackson:\n    date-format: yyyy-MM-dd HH:mm:ss\n    time-zone: GMT+8\n    default-property-inclusion: non_null\n    serialization:\n      write-dates-as-timestamps: false\n      fail-on-empty-beans: false\n  data:\n    redis:\n      database: ${REDIS_DATABASE:0}\n      host: ${REDIS_HOST:localhost}\n      port: ${REDIS_PORT:6379}\n      timeout: ${REDIS_TIMEOUT:3000}\n      ssl:\n        enabled: ${REDIS_SSL_ENABLED:false}\n      lettuce:\n        pool:\n          max-active: ${REDIS_POOL_MAX_ACTIVE:100}    # 最大连接数\n          max-idle: ${REDIS_POOL_MAX_IDLE:20}        # 最大空闲连接\n          min-idle: ${REDIS_POOL_MIN_IDLE:5}         # 最小空闲连接\n          max-wait: ${REDIS_POOL_MAX_WAIT:3000}      # 最大等待时间(ms)\n          time-between-eviction-runs: 60000          # 空闲连接检测周期\n        shutdown-timeout: 5000\n        cluster:\n          refresh:\n            adaptive: true  # 自适应拓扑刷新\n  cloud:\n    sentinel:\n      eager: true\n      log:\n        dir: ${SENTINEL_LOG_DIR:/ingot-data/sentinel/}\n        switch-pid: true\n\n\n# 端点对外暴露\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        # 仅暴露必要端点，生产环境需要通过网关或防火墙限制访问\n        include: ${MANAGEMENT_ENDPOINTS:health,info,metrics}\n      base-path: /actuator\n  endpoint:\n    health:\n      access: unrestricted\n      show-details: ${HEALTH_SHOW_DETAILS:ALWAYS}\n      probes:\n        enabled: true  # 启用K8s健康检查\n    info:\n      access: unrestricted\n  health:\n    redis:\n      enabled: true\n    db:\n      enabled: true\n    diskspace:\n      enabled: true\n      threshold: ${HEALTH_DISK_THRESHOLD:10GB}\n\n# Feign配置优化\nfeign:\n  sentinel:\n    enabled: ${FEIGN_SENTINEL_ENABLED:true}\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: false\n    max-connections: ${FEIGN_MAX_CONNECTIONS:400}\n    max-connections-per-route: ${FEIGN_MAX_CONNECTIONS_PER_ROUTE:50}\n    time-to-live: 900\n    connection-timer-repeat: 3000\n  client:\n    config:\n      default:\n        connectTimeout: ${FEIGN_CONNECT_TIMEOUT:5000}\n        readTimeout: ${FEIGN_READ_TIMEOUT:10000}\n        loggerLevel: ${FEIGN_LOGGER_LEVEL:BASIC}  # NONE, BASIC, HEADERS, FULL\n  compression:\n    request:\n      enabled: true\n      mime-types: text/xml,application/xml,application/json\n      min-request-size: 2048\n    response:\n      enabled: true\n      useGzipDecoder: true\n  circuitbreaker:\n    enabled: true\n    alphanumeric-ids:\n      enabled: true\n', '38ac37dec6b1c10e8d91995130ca8e62', '2026-07-18 08:40:13', '2026-07-18 08:53:24', 'nacos', '172.88.0.1', '', 'ingot', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (352, 'in-database.yml', 'TEST_GROUP', 'spring:\n  datasource:\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      initial-size: ${DB_POOL_INITIAL_SIZE:5}           # 初始化连接数\n      min-idle: ${DB_POOL_MIN_IDLE:5}                   # 最小空闲连接\n      max-active: ${DB_POOL_MAX_ACTIVE:50}              # 最大活跃连接（单服务）\n      max-wait: ${DB_POOL_MAX_WAIT:5000}                # 获取连接最大等待时间(ms)\n      \n      # 连接保活和回收配置\n      test-on-borrow: false                              # 申请连接时不检测（影响性能）\n      test-on-return: false                              # 归还连接时不检测\n      test-while-idle: true                              # 空闲时检测\n      validation-query: SELECT 1                         # 检测SQL\n      validation-query-timeout: 3                        # 检测超时时间(s)\n      time-between-eviction-runs-millis: 60000          # 检测间隔(ms)\n      min-evictable-idle-time-millis: 300000            # 最小空闲时间(ms)\n      max-evictable-idle-time-millis: 900000            # 最大空闲时间(ms)\n      \n      # 连接泄露检测\n      remove-abandoned: ${DB_REMOVE_ABANDONED:true}      # 开启泄露检测\n      remove-abandoned-timeout: ${DB_REMOVE_ABANDONED_TIMEOUT:300}  # 泄露超时时间(s)\n      log-abandoned: ${DB_LOG_ABANDONED:true}            # 记录泄露日志\n      \n      # 连接属性配置\n      connection-properties: druid.stat.mergeSql=true;druid.stat.slowSqlMillis=${DB_SLOW_SQL_MILLIS:2000}\n      connection-init-sqls:\n        - SET NAMES utf8mb4\n        - SET SESSION sql_mode=\'STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION\'\n      \n      # SQL监控配置\n      filters: ${DB_FILTERS:stat,wall}  # 生产环境可移除log4j filter\n      \n      # StatFilter配置\n      stat-view-servlet:\n        enabled: ${DRUID_STAT_VIEW_ENABLED:true}\n        url-pattern: /druid/*\n        reset-enable: false                              # 禁止重置统计数据\n        login-username: ${DRUID_USERNAME:admin}\n        login-password: ${DRUID_PASSWORD:DruidAdmin@2025}\n        allow: ${DRUID_ALLOW:127.0.0.1}                 # IP白名单（生产环境严格控制）\n        deny: ${DRUID_DENY:}                            # IP黑名单\n      \n      # WebStatFilter配置\n      web-stat-filter:\n        enabled: ${DRUID_WEB_STAT_ENABLED:true}\n        url-pattern: /*\n        exclusions: \'*.js,*.gif,*.jpg,*.png,*.css,*.ico,/druid/*,/actuator/*\'\n        session-stat-enable: true\n        session-stat-max-count: 1000\n        principal-session-name: user\n        principal-cookie-name: user\n      \n      # SQL防火墙配置\n      wall:\n        enabled: true\n        config:\n          multi-statement-allow: true                   # 允许多条SQL\n          none-base-statement-allow: true\n          comment-allow: true                            # 允许注释\n          select-allow: true\n          select-into-allow: false                       # 禁止SELECT INTO\n          update-allow: true\n          insert-allow: true\n          delete-allow: true\n          create-table-allow: ${DB_WALL_CREATE_TABLE:false}  # 生产环境禁止\n          drop-table-allow: ${DB_WALL_DROP_TABLE:false}      # 生产环境禁止\n          alter-table-allow: ${DB_WALL_ALTER_TABLE:false}    # 生产环境禁止\n          truncate-allow: ${DB_WALL_TRUNCATE:false}          # 生产环境禁止\n      \n      # 监控统计异步化\n      use-global-data-source-stat: true\n      \n      # 超时配置\n      query-timeout: ${DB_QUERY_TIMEOUT:30}              # 查询超时时间(s)\n      transaction-query-timeout: ${DB_TX_QUERY_TIMEOUT:60}  # 事务查询超时(s)\n      \n      # Keep Alive配置（防止连接被中间件断开）\n      keep-alive: ${DB_KEEP_ALIVE:true}\n      keep-alive-between-time-millis: 120000            # Keep Alive间隔(ms)\n      \n      # 异步初始化\n      async-init: true\n\n# MyBatis配置优化\nmybatis:\n  configuration:\n    map-underscore-to-camel-case: true\n    cache-enabled: ${MYBATIS_CACHE_ENABLED:true}        # 二级缓存\n    lazy-loading-enabled: ${MYBATIS_LAZY_LOADING:true}  # 延迟加载\n    aggressive-lazy-loading: false                       # 关闭积极加载\n    multiple-result-sets-enabled: true\n    use-column-label: true\n    use-generated-keys: true\n    auto-mapping-behavior: partial\n    default-executor-type: reuse                        # 复用执行器\n    default-statement-timeout: ${MYBATIS_STATEMENT_TIMEOUT:30}  # 语句超时(s)\n    log-impl: org.apache.ibatis.logging.slf4j.Slf4jImpl\n\n# MyBatis-Plus配置优化\nmybatis-plus:\n  mapper-locations: classpath:/mapper/*Mapper.xml,classpath*:sdk/mapper/*.xml\n  configuration:\n    default-enum-type-handler: com.baomidou.mybatisplus.core.handlers.CompositeEnumTypeHandler\n    # 关闭MyBatis-Plus自带日志（使用SLF4J）\n    log-impl: org.apache.ibatis.logging.slf4j.Slf4jImpl\n  global-config:\n    banner: false\n    enable-sql-runner: false\n    db-config:\n      # 主键策略\n      id-type: ${MYBATIS_PLUS_ID_TYPE:ASSIGN_ID}\n      # 逻辑删除配置\n      logic-delete-value: now()                         # 逻辑已删除值\n      logic-not-delete-value: \"null\"                    # 逻辑未删除值\n      # 字段策略\n      insert-strategy: not_null\n      update-strategy: not_null\n\n', '79398126ace9d09f7618c532e5050f56', '2026-07-18 08:40:13', '2026-07-18 08:53:37', 'nacos', '172.88.0.1', '', 'ingot', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (353, 'in-service-pms.yml', 'TEST_GROUP', 'spring:\n  datasource:\n    # 数据库连接URL配置\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_core}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\n# Ingot业务配置\ningot:\n  security:\n    account:\n      # local 或 remote；remote 时下方 lockout 仅作 Nacos 地板\n      mode: local\n      policy:\n        fallback:\n          local-floor-enabled: true\n        cache:\n          l1-enabled: true\n          l1-ttl: 5m\n          l2-enabled: true\n          l2-ttl: 30m\n      lockout:\n        # 是否启用自动锁定账号\n        enabled: ${ACCOUNT_LOCKOUT_ENABLED:true}\n        # 失败次数阈值\n        maxAttempts: 5\n        # 锁定时长（分钟），0=永久锁定\n        lockDurationMinutes: 30\n        # 失败计数窗口期（分钟）\n        attemptWindowMinutes: 15\n        # 从第几次失败开始给出\"还剩几次将锁定\"的详细提示， 之前的失败一律返回通用\"账号或密码错误\"，避免暴露用户存在性。\n        # 例：maxAttempts=5，hintAfterAttempts=3 时：\n        # 第 1/2 次：通用提示\n        # 第 3 次：剩余 2 次\n        # 第 4 次：剩余 1 次\n        # 第 5 次：触发自动锁定，下次登录命中锁定分支\n        hintAfterAttempts: 3\n    event:\n      # 总开关。false：SecurityEventPublisher 不投递任何事件；true：由 target 决定落点。\n      enabled: true\n      # 主投递目标。\n      # local  = 写入本服务库 security_event（须 classpath 有 Store，通常配 primary-store: mysql）\n      # center = 经 Feign/Transport 上报 ingot-security 中心 admission\n      target: local\n      # target=local 且 classpath 存在多个 SecurityEventStore 时的主 Store id。\n      # 可选值：mysql（MySqlSecurityEventStore）、log（LogSecurityEventStore）。\n      # 仅有一个 Store Bean 时可省略，自动选中。\n      primary-store: mysql\n      # 次要投递目标（迁移 shadow 双写用）。稳定态留空 []。\n      # 元素取值：local | center；与主 target 去重后额外投递一份，shadow 失败不影响主链路 ack。\n      shadow-targets: []\n      # 上报方模块标识，写入 security_event.source_module。\n      # PMS 填 PMS，Member 填 MEMBER。\n      source-module: PMS\n      # 按事件大类过滤是否上报（enabled=true 时生效）；false 则该类别事件在 Publisher 层被丢弃。\n      categories:\n        # AUTH：登录成功/失败等认证类事件\n        auth: true\n        # ACCOUNT：锁定/解锁/创建/删除等账号类事件\n        account: true\n        # CREDENTIAL：改密/重置/强制改密等凭证类事件\n        credential: true\n        # ACCESS：网关封禁/限流违规等访问防护类；PMS/Member 通常不产生，可保持 true\n        access: true\n      # canonical security_event 过期物理删除（PurgeCanonicalSecurityEventTask，cron 0 30 3 * * ?）。\n      # delivery / mysql 在 in-security-policy.yml（本服务已 import）。\n      retention:\n        # 是否启用定时清理；false 等同永久保留。\n        enabled: true\n        # 保留天数；早于 now-days 的记录被删除；0 表示永久保留。\n        days: 30\n        # 单批 DELETE LIMIT 条数，避免长事务与大锁。\n        batch-size: 500\n        # 单次定时任务最多连续执行的批次数。\n        max-rounds: 100\n        # 单次 retention 任务最大执行时长（秒），超时停止本轮。\n        max-duration-seconds: 30\n        # memory/spool 队列使用率超过该百分比时，retention 让步暂停删除。\n        yield-queue-usage-percent: 50\n      # 按 eventType 覆盖默认优先级（BEST_EFFORT | DURABLE），支持 Nacos 热刷新。\n      # 未配置时使用 DefaultPriorityClassifier 内置默认表；示例：\n      # LOGIN_FAILURE: DURABLE\n      priority-overrides: {}\n  oss:\n    minio:\n      url: ${MINIO_URL:http://ingot-cloud:9090}\n      accessKey: ${MINIO_ACCESS_KEY:2NPpKzxFQjyeMTQFEXA1}\n      secretKey: ${MINIO_SECRET_KEY:8SGAp7DhqZCQrYnU9Poyu888pQOB6w4SP2ILHbVU}\n  social:\n    wechat:\n      miniProgramAppId: wx18dc0ea8c6ca1d7d\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:true}  # 生产环境关闭\n\n# SpringDoc/Swagger配置（测试环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.pms.mapper\n\n# 日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}\n', 'ad644df0ff3d171bd8ed0f0f55f430de', '2026-07-18 08:40:13', '2026-08-25 09:10:15', 'nacos', '172.88.0.1', '', 'ingot', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (354, 'in-service-gateway.yml', 'TEST_GROUP', 'spring:\n  cloud:\n    gateway:\n      server:\n        webflux:\n          routes:\n            - id: openapi\n              uri: lb://in-service-gateway\n              predicates:\n                - Path=/v3/api-docs/**\n              filters:\n                - RewritePath=/v3/api-docs/(?<path>.*), /$\\{path}/$\\{path}/v3/api-docs\n            - id: in-service-pms\n              uri: lb://in-service-pms\n              predicates:\n                - Path=/pms/**\n              filters:\n                - StripPrefix=1\n            - id: in-service-member\n              uri: lb://in-service-member\n              predicates:\n                - Path=/member/**\n              filters:\n                - StripPrefix=1\n            - id: in-service-security\n              uri: lb://in-service-security\n              predicates:\n                - Path=/security/**\n              filters:\n                - StripPrefix=1\n            - id: in-crypto-pubkey\n              uri: lb://in-service-bff\n              predicates:\n                - Path=/crypto/public-keys\n            - id: in-service-bff\n              uri: lb://in-service-bff\n              predicates:\n                - Path=/bff/**\n            - id: in-service-auth\n              uri: lb://in-service-auth\n              predicates:\n                - Path=/auth/client/**,/auth/token/**\n              filters:\n                - StripPrefix=1\n\ningot:\n  vc:\n    verifyUrls: []\n    image:\n      opsLimitGetPerMinute: 20\n      opsLimitCheckPerMinute: 40\n  security:\n    account:\n      gateway:\n        # 是否启用账号锁定 AccountLockFilter，默认开启\n        enabled: true\n        # 不检查锁定状态的路径 Ant 模式。\n        excludePathPatterns:\n          - /actuator/**\n          - /bff/auth/**\n    policy:\n      # GatewayRuleClientProperties\n      client:\n        # 跨节点失效订阅开关\n        invalidation-enabled: true\n        # 是否启用 remote → LKG → Nacos 地板 弹性降级链\n        resilience-enabled: true\n        # remote 不可用且 LKG 为空时，是否回落到 Nacos 地板配置\n        local-floor-enabled: true\n        # 共享快照的分层缓存参数。\n        cache:\n          # 1级缓存存活时间\n          l1-ttl: 5m\n          # 2级缓存存活时间\n          l2-ttl: 30m\n    # 限流域开关与来源；groups/rules 地板在 in-security-gateway.yml\n    ratelimit:\n      enabled: true\n      policy:\n        mode: local\n    # 黑白名单开关与来源；items 地板在 in-security-gateway.yml\n    blacklist:\n      enabled: false\n      policy:\n        mode: local\n    # 限流违规升级开关与来源；阈值地板在 in-security-gateway.yml\n    violation-escalation:\n      enabled: true\n      policy:\n        mode: local\n    # 挑战验证开关与来源；groups/policies 地板在 in-security-gateway.yml\n    challenge:\n      enabled: true\n      policy:\n        mode: local\n    # 事件配置\n    event:\n      # 总开关；Gateway 仅在上报 ACCESS 类事件时依赖此项。\n      enabled: true\n      # center：经 Feign 上报 ingot-security admission；不写网关本地 security_event 表。\n      target: center\n      # Gateway 稳定态不需要 shadow；留空 []。\n      shadow-targets: []\n      # 写入中心 security_event.source_module。\n      source-module: GATEWAY\n      # Gateway 通常只产生 ACCESS 类事件；其余类别关闭可减少无效配置。\n      categories:\n        auth: false\n        account: false\n        credential: false\n        access: true\n      # target=center 时 BEST_EFFORT 仍走 memory 缓冲后再 Feign 批量上报。\n      delivery:\n        memory:\n          queue-capacity: 2048\n          batch-size: 32\n          poll-timeout-ms: 100\n          shutdown-timeout-ms: 5000\n        # DURABLE 事件（如 BLACKLIST_BLOCK）仍需要 spool；未显式配置时使用下方 Java 默认值：\n        # spool.directory 为父目录，运行时再拼 spring.application.name。\n      # Gateway 不写本地 canonical 表，通常不需要 retention；中心库由 in-service-security 清理。\n      retention:\n        enabled: false\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n\n# 开发环境日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}', '4234148c0f80742f663c2a06bb12049d', '2026-07-18 08:40:13', '2026-08-28 06:41:31', 'nacos', '172.88.0.1', '', 'ingot', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (355, 'in-service-auth.yml', 'TEST_GROUP', 'spring:\n  mvc:\n    static-path-pattern: /static/**\n  thymeleaf:\n    cache: false\n    prefix: classpath:/templates/\n    suffix: .html\n    encoding: UTF-8\n    servlet:\n      content-type: text/html\n  datasource:\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_auth}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\ningot:\n  security:\n    oauth2:\n      auth:\n        loginFormUrl: https://login.ingotcloud.top/oauth2/challenge\n        issuer: http://${SERVICE_AUTH_HOST:localhost:5100}\n      resource:\n        publicUrls:\n          - /favicon.ico,GET\n          - /static/**,GET\n          - /logout,*\n          - /error,*\n    jwk:\n      key-lifetime: 90d\n      key-grace-period: 2h\n      max-active-keys: 3\n      cache-refresh-interval: 5m\n      master-key: ${AUTH_JWK_MASTER_KEY:a7A7FJ9KdQutfjbQh8sZSt2kcNtl/JUkmEI73aCR080=}\n      enable-encryption: true\n    access:\n      mode: local\n      loginFailure:\n        ip:\n          enabled: true\n          # 50次命中\n          maxAttempts: 50\n          # 时间窗口\n          windowMinutes: 1\n          # 锁定时间，秒\n          blockTtlSec: 3600\n          blockKeyType: \"IP\"\n        device:\n          enabled: false\n        client:\n          enabled: false\n        accountIp:\n          enabled: false\n    session:\n      # 会话存储不可用宽限期；超期一律拒绝，会话键不存在不在宽限范围内\n      store-unavailable-grace: 30s\n      # local：并发策略只读下面的 concurrency 段，不依赖安全中心（A9 场景）\n      mode: local\n      concurrency:\n        # 关闭后登录路径退回「只认 Client 的 UNIQUE / STANDARD」，紧急回退开关\n        enabled: true\n        # 0 = 不限并发；此时 Client 配置为 UNIQUE 仍按单会话处理\n        max-sessions: 0\n        # 会话数统计维度\n        dimension: USER_CLIENT\n        # 超限处置方式\n        overflow: KICK_OLDEST\n        # 管理用户（UserTypeEnum.ADMIN）是否强制单会话\n        admin-forbid-concurrent: false\n    event:\n      # 安全事件总开关；false 时不做任何上报\n      enabled: true\n      # center：会话撤销等 AUTH 事件 Feign 上报安全中心，Auth 本库不落 security_event\n      target: center\n      shadow-targets: []\n      # 写入 security_event.source_module\n      sourceModule: AUTH\n      # 安全事件大类上报开关\n      categories:\n        auth: true\n        account: false\n        credential: false\n        access: false\n      retention:\n        enabled: false\n\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:true}  # 生产环境关闭\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.auth.mapper\n\n# 日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}', '77a584c164aa7bbdf8b47f52c08b5b6c', '2026-07-18 08:40:13', '2026-08-21 07:00:17', 'nacos', '172.88.0.1', '', 'ingot', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (356, 'in-service-member.yml', 'TEST_GROUP', 'spring:\n  datasource:\n    # 数据库连接URL配置\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_member}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\n# Ingot业务配置\ningot:\n  security:\n    account:\n      # local 或 remote；remote 时下方 lockout 仅作 Nacos 地板\n      mode: local\n      policy:\n        fallback:\n          local-floor-enabled: true\n        cache:\n          l1-enabled: true\n          l1-ttl: 5m\n          l2-enabled: true\n          l2-ttl: 30m\n      lockout:\n        # 是否启用自动锁定账号\n        enabled: ${ACCOUNT_LOCKOUT_ENABLED:true}\n        # 失败次数阈值\n        maxAttempts: 5\n        # 锁定时长（分钟），0=永久锁定\n        lockDurationMinutes: 30\n        # 失败计数窗口期（分钟）\n        attemptWindowMinutes: 15\n        # 从第几次失败开始给出\"还剩几次将锁定\"的详细提示， 之前的失败一律返回通用\"账号或密码错误\"，避免暴露用户存在性。\n        # 例：maxAttempts=5，hintAfterAttempts=3 时：\n        # 第 1/2 次：通用提示\n        # 第 3 次：剩余 2 次\n        # 第 4 次：剩余 1 次\n        # 第 5 次：触发自动锁定，下次登录命中锁定分支\n        hintAfterAttempts: 3\n    event:\n      # 总开关。false：SecurityEventPublisher 不投递任何事件；true：由 target 决定落点。\n      enabled: true\n      # 主投递目标。\n      # local  = 写入本服务库 security_event（须 classpath 有 Store，通常配 primary-store: mysql）\n      # center = 经 Feign/Transport 上报 ingot-security 中心 admission\n      target: local\n      # target=local 且 classpath 存在多个 SecurityEventStore 时的主 Store id。\n      # 可选值：mysql（MySqlSecurityEventStore）、log（LogSecurityEventStore）。\n      # 仅有一个 Store Bean 时可省略，自动选中。\n      primary-store: mysql\n      # 次要投递目标（迁移 shadow 双写用）。稳定态留空 []。\n      # 元素取值：local | center；与主 target 去重后额外投递一份，shadow 失败不影响主链路 ack。\n      shadow-targets: []\n      # 上报方模块标识，写入 security_event.source_module。\n      # PMS 填 PMS，Member 填 MEMBER。\n      source-module: MEMBER\n      # 按事件大类过滤是否上报（enabled=true 时生效）；false 则该类别事件在 Publisher 层被丢弃。\n      categories:\n        # AUTH：登录成功/失败等认证类事件\n        auth: true\n        # ACCOUNT：锁定/解锁/创建/删除等账号类事件\n        account: true\n        # CREDENTIAL：改密/重置/强制改密等凭证类事件\n        credential: true\n        # ACCESS：网关封禁/限流违规等访问防护类；PMS/Member 通常不产生，可保持 true\n        access: true\n      # canonical security_event 过期物理删除（PurgeCanonicalSecurityEventTask，cron 0 30 3 * * ?）。\n      # delivery / mysql 在 in-security-policy.yml（本服务已 import）。\n      retention:\n        # 是否启用定时清理；false 等同永久保留。\n        enabled: true\n        # 保留天数；早于 now-days 的记录被删除；0 表示永久保留。\n        days: 30\n        # 单批 DELETE LIMIT 条数，避免长事务与大锁。\n        batch-size: 500\n        # 单次定时任务最多连续执行的批次数。\n        max-rounds: 100\n        # 单次 retention 任务最大执行时长（秒），超时停止本轮。\n        max-duration-seconds: 30\n        # memory/spool 队列使用率超过该百分比时，retention 让步暂停删除。\n        yield-queue-usage-percent: 50\n      # 按 eventType 覆盖默认优先级（BEST_EFFORT | DURABLE），支持 Nacos 热刷新。\n      # 未配置时使用 DefaultPriorityClassifier 内置默认表；示例：\n      # LOGIN_FAILURE: DURABLE\n      priority-overrides: {}\n  oss:\n    minio:\n      url: ${MINIO_URL:http://ingot-cloud:9090}\n      accessKey: ${MINIO_ACCESS_KEY:2NPpKzxFQjyeMTQFEXA1}\n      secretKey: ${MINIO_SECRET_KEY:8SGAp7DhqZCQrYnU9Poyu888pQOB6w4SP2ILHbVU}\n  social:\n    wechat:\n      miniProgramAppId: wx18dc0ea8c6ca1d7d\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:true}  # 生产环境关闭\n\n# SpringDoc/Swagger配置（测试环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.member.mapper\n\n# 日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}\n', 'b02b2e40d87571e2d015c09091e9232a', '2026-07-18 08:40:13', '2026-08-25 09:12:57', 'nacos', '172.88.0.1', '', 'ingot', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (357, 'in-service-security.yml', 'TEST_GROUP', 'spring:\n  datasource:\n    # 数据库连接URL配置\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_security}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\n# Ingot业务配置\ningot:\n  security:\n    event:\n      # 中心 admission 接收的事件异步入库；false 则 admission 入队被禁用。\n      enabled: true\n      # 中心将事件写入本库 ingot_security.security_event。\n      target: local\n      primary-store: mysql\n      shadow-targets: []\n      source-module: SECURITY\n      categories:\n        auth: true\n        account: true\n        credential: true\n        access: true\n      # 中心库数据量大，retention.days 可按合规要求拉长（如 90～180）。\n      # delivery / mysql 在 in-security-policy.yml（本服务已 import）。\n      retention:\n        enabled: true\n        days: 90\n        batch-size: 500\n        max-rounds: 100\n        max-duration-seconds: 30\n        yield-queue-usage-percent: 50\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:true}  # 生产环境关闭\n\n# SpringDoc/Swagger配置（测试环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.security.mapper\n\n# 日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}\n', 'ababda260d44ad2c113ed943a9d64f78', '2026-07-18 08:40:13', '2026-08-25 09:13:09', 'nacos', '172.88.0.1', '', 'ingot', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (358, 'in-service-bff.yml', 'TEST_GROUP', 'ingot:\n  security:\n    oauth2:\n      resource:\n        public-urls:\n          - /crypto/public-keys,GET\n    # 账号锁定 BFF 登录短路：解密后查 Redis name key；默认拦截不调 Auth\n    account:\n      bff:\n        # 是否在登录解密后检查 Redis name key，默认开启。\n        enabled: true\n        # BFF 拦截时是否仍调 Auth 以产生 LOGIN_FAILURE；默认关闭。\n        emit-login-failure-on-bff-block: false\n  bff:\n    client-id: ingot-bff\n    scope: system\n    # 管理用户:0, C端用户:1\n    user-type: \"0\"\n    session-ttl: 7200\n    redirect-uri: http://localhost:5400/bff/auth/callback\n    cookie:\n      # 开发环境不设置 domain（localhost 可用），生产环境设置顶级域名如 .ingotcloud.top\n      domain: ${BFF_COOKIE_DOMAIN:}\n      # 开发环境 false，生产必须 true\n      secure: ${BFF_COOKIE_SECURE:false}\n      same-site: ${BFF_COOKIE_SAME_SITE:Lax}\n    security:\n      # 客户端指纹校验，防止 Cookie 盗用\n      fingerprint-enabled: ${BFF_FINGERPRINT_ENABLED:true}\n      # 指纹模式: device（前端设备指纹，推荐）/ ip_ua（服务端 IP+UA，降级方案）\n      fingerprint-mode: ${BFF_FINGERPRINT_MODE:device}\n      # 信任的前端应用域名列表\n      allowed-frontends:\n        - http://localhost:1798\n        - http://localhost:5798\n      default-redirect-uri:\n        - http://localhost:5798\n\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n\n# 开发环境日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}', '30fd98a44708c0c5d4cb9380a49b7c79', '2026-07-18 08:40:13', '2026-08-25 09:13:25', 'nacos', '172.88.0.1', '', 'ingot', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (359, 'in-security-crypto.yml', 'TEST_GROUP', 'ingot:\n  security:\n    crypto:\n      hybrid:\n        response-wrap: DATA_ONLY          # DATA_ONLY:只加密 R.data, FULL:加密所有\n        active-kid: k-2026-08             # 当前激活 kid，响应头 In-Crypto-Kv 会回这个值\n        public-key-endpoint-enabled: true # 仅公钥下发服务开 true，其它服务可 false\n        replay-namespace: crypto\n        key-pairs:\n          k-2026-07:                      # kid 自定义，与前端请求头 In-Crypto-Kv 对应\n            public-key: \n            private-key: \n          k-2026-08:\n            public-key: \n            private-key: \n      secretKeys:\n        # 加密密钥 - 生产环境必须通过环境变量配置\n        aes: ${CRYPTO_AES_KEY:ingotingotingot1}\n        aes_gcm: ${CRYPTO_AES_GCM_KEY:ingotingotingot1}', '31351f80f66c047c1afa4d6293322545', '2026-07-18 08:40:13', '2026-07-18 08:40:13', 'nacos', '172.88.0.1', '', 'ingot', '加密算法，密钥，密钥轮换', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (360, 'in-security-policy.yml', 'TEST_GROUP', '# 跨服务安全策略地板。消费者：PMS / Member / Security / BFF。\n# Auth、Gateway 不要 import。\n# 含：replay、credential、account.signal、event.delivery/mysql。\n# 不含：event.target/source-module、account.lockout、网关限流规则。\ningot:\n  security:\n    ignoreTenantValidateRoleCodeList:\n      - role_admin\n    \n    # 重放配置\n    replay:\n      enabled: true\n      window: 5m\n      clock-skew: 5m\n      key-prefix: \"replay:\"\n      fail-open: false\n    \n    # 凭证配置\n    credential:\n      policy:\n        # 策略加载模式：local（本地配置）或 remote（远程加载）\n        mode: ${CREDENTIAL_MODE:local}\n\n        # 本地策略配置\n        strength:\n          # 是否启用\n          enabled: true\n          # 最小长度\n          min-length: 8\n          # 最大长度\n          max-length: 32\n          # 是否要求大写字母\n          require-uppercase: false\n          # 是否要求小写字母\n          require-lowercase: false\n          # 是否要求数字\n          require-digit: false\n          # 是否要求特殊字符\n          requireSpecialChar: false\n          # 特殊字符集合\n          specialChars: \"!@#$%^&*()_+-=[]{}|;:,.<>?\"\n          # 禁止的模式\n          forbiddenPatterns:\n            - \"password\"\n            - \"123456\"\n            - \"admin\"\n            - \"qwerty\"\n          # 禁止包含用户属性\n          forbidUserAttributes: false\n\n        history:\n          # 是否启用\n          enabled: true\n          # 检查最近N次密码\n          check-count: 5\n\n        expiration:\n          # 是否启用 \n          enabled: false\n          # 最大有效天数\n          max-days: 90\n          # 提前警告天数\n          warningDaysBefore: 7\n          # 宽限登录次数\n          graceLoginCount: 3\n\n        initialPassword:\n          # 初始密码生成方式：RANDOM-随机生成；FIXED-统一默认密码\n          generation: RANDOM\n          # 随机初始密码长度（generation=RANDOM 时生效）\n          length: 10\n          # 统一默认密码（generation=FIXED 时生效）\n          fixedPassword: In@123456\n          # 初始密码有效小时数；0 表示不限制。超过后视为初始密码失效，需重新重置。\n          validHours: 72\n          # 用后失效：初始密码修改成功后即失效（依赖 mustChangePwd/force_change 清除，默认 true）\n          oneTime: true\n          # 首次登录是否强制修改密码\n          forceChangeOnFirstLogin: true\n\n    # 永久锁 Redis TTL（PMS/Member 写、BFF 读）；必须全局同一份\n    account:\n      signal:\n        # 永久锁定时 uid/name key 的 TTL（天），默认 30。\n        permanent-lock-ttl-days: 30\n\n    # PMS/Member/Security 写本地 canonical / spool 时共用。\n    # Auth/Gateway 不 import 本文件；BFF import 但不启用 recording。\n    event:\n      # 投递层：BEST_EFFORT 走 memory，DURABLE 走 spool（两条独立管道，非溢出关系）。\n      delivery:\n        # BEST_EFFORT 有界内存队列参数；后台线程 security-recording-memory 攒批后投递。\n        memory:\n          # 内存队列容量；满时新 BEST_EFFORT 事件 DROPPED，不阻塞业务线程。\n          queue-capacity: 2048\n          # memory worker 单次 claim 条数上限。\n          batch-size: 32\n          # worker 攒批 poll 超时（毫秒）；队列空则等待该时长后再次 poll。\n          poll-timeout-ms: 100\n          # 进程关闭时等待 memory worker 排空队列的最长时间（毫秒）。\n          shutdown-timeout-ms: 5000\n        # DURABLE 本地 file spool；后台线程 security-recording-durable 持续 claim → 投递 → ack/nack 重试。\n        spool:\n          # spool 根目录（append-only segment 文件）。\n          directory: /ingot-data/security-recording/spool\n          # spool 目录总磁盘配额（如 1GB、512MB）。\n          max-bytes: 1GB\n          # 单个 segment 文件大小上限，达上限滚动新文件。\n          segment-bytes: 64MB\n          # 业务线程同步等待 spool 接纳 DURABLE 事件的最长时间（毫秒）；超时返回 FAILED（业务仍 fail-open）。\n          durable-ack-timeout-ms: 20\n          # durable worker 每次从 spool claim 的条数上限。\n          replay-batch-size: 32\n          # 投递失败 nack 后重试初始退避（毫秒）。\n          retry-initial-ms: 1000\n          # 重试退避上限（毫秒）。\n          retry-max-ms: 60000\n      # MySQL SecurityEventStore 写入侧参数（target=local 且 primary-store=mysql 时生效）。\n      mysql:\n        # 并发写入信号量许可数；默认 1，避免 canonical security_event 热点写冲突。\n        max-concurrent-writes: 1\n        # 单批 INSERT 事务超时（秒）。\n        transaction-timeout-seconds: 5\n', '31f7507779ad721dadcb2718296d3b48', '2026-07-18 08:40:13', '2026-08-25 09:13:50', 'nacos', '172.88.0.1', '', 'ingot', '密码策略，登录策略，会话策略，账号策略等', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (361, 'in-common.yml', 'PROD_GROUP', 'jasypt:\n  encryptor:\n    password: ${JASYPT_PASSWORD:ingot}\n\nserver:\n  forward-headers-strategy: framework\n  tomcat:\n    uri-encoding: UTF-8\n    remote-ip-header: x-forwarded-for\n    threads:\n      max: ${TOMCAT_THREADS_MAX:200}           # 最大线程数\n      min-spare: ${TOMCAT_THREADS_MIN:10}      # 最小空闲线程数\n    max-connections: ${TOMCAT_MAX_CONNECTIONS:8000}  # 最大连接数\n    accept-count: ${TOMCAT_ACCEPT_COUNT:100}   # 等待队列长度\n    connection-timeout: ${TOMCAT_CONNECTION_TIMEOUT:20000}  # 连接超时时间(ms)\n    max-http-form-post-size: ${TOMCAT_MAX_POST_SIZE:104857600}  # 100MB\n  shutdown: graceful  # 优雅关闭\n\n# Spring应用生命周期配置\nspring:\n  lifecycle:\n    timeout-per-shutdown-phase: ${SHUTDOWN_TIMEOUT:30s}\n  web:\n    forwarding:\n      enabled: true\n      strategy: framework\n  webflux:\n    forwarding:\n      enabled: true\n      strategy: framework\n  servlet:\n    multipart:\n      max-file-size: ${MAX_FILE_SIZE:100MB}\n      max-request-size: ${MAX_REQUEST_SIZE:100MB}\n      enabled: true\n      resolve-lazily: true  # 延迟解析，提高性能\n  jackson:\n    date-format: yyyy-MM-dd HH:mm:ss\n    time-zone: GMT+8\n    default-property-inclusion: non_null\n    serialization:\n      write-dates-as-timestamps: false\n      fail-on-empty-beans: false\n  data:\n    redis:\n      database: ${REDIS_DATABASE:0}\n      host: ${REDIS_HOST:localhost}\n      port: ${REDIS_PORT:6379}\n      timeout: ${REDIS_TIMEOUT:3000}\n      ssl:\n        enabled: ${REDIS_SSL_ENABLED:false}\n      lettuce:\n        pool:\n          max-active: ${REDIS_POOL_MAX_ACTIVE:100}    # 最大连接数\n          max-idle: ${REDIS_POOL_MAX_IDLE:20}        # 最大空闲连接\n          min-idle: ${REDIS_POOL_MIN_IDLE:5}         # 最小空闲连接\n          max-wait: ${REDIS_POOL_MAX_WAIT:3000}      # 最大等待时间(ms)\n          time-between-eviction-runs: 60000          # 空闲连接检测周期\n        shutdown-timeout: 5000\n        cluster:\n          refresh:\n            adaptive: true  # 自适应拓扑刷新\n  cloud:\n    sentinel:\n      eager: true\n      log:\n        dir: ${SENTINEL_LOG_DIR:/ingot-data/sentinel/}\n        switch-pid: true\n\n\n# 端点对外暴露\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        # 仅暴露必要端点，生产环境需要通过网关或防火墙限制访问\n        include: ${MANAGEMENT_ENDPOINTS:health,info,metrics}\n      base-path: /actuator\n  endpoint:\n    health:\n      access: unrestricted\n      show-details: ${HEALTH_SHOW_DETAILS:ALWAYS}\n      probes:\n        enabled: true  # 启用K8s健康检查\n    info:\n      access: unrestricted\n  health:\n    redis:\n      enabled: true\n    db:\n      enabled: true\n    diskspace:\n      enabled: true\n      threshold: ${HEALTH_DISK_THRESHOLD:10GB}\n\n# Feign配置优化\nfeign:\n  sentinel:\n    enabled: ${FEIGN_SENTINEL_ENABLED:true}\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: false\n    max-connections: ${FEIGN_MAX_CONNECTIONS:400}\n    max-connections-per-route: ${FEIGN_MAX_CONNECTIONS_PER_ROUTE:50}\n    time-to-live: 900\n    connection-timer-repeat: 3000\n  client:\n    config:\n      default:\n        connectTimeout: ${FEIGN_CONNECT_TIMEOUT:5000}\n        readTimeout: ${FEIGN_READ_TIMEOUT:10000}\n        loggerLevel: ${FEIGN_LOGGER_LEVEL:BASIC}  # NONE, BASIC, HEADERS, FULL\n  compression:\n    request:\n      enabled: true\n      mime-types: text/xml,application/xml,application/json\n      min-request-size: 2048\n    response:\n      enabled: true\n      useGzipDecoder: true\n  circuitbreaker:\n    enabled: true\n    alphanumeric-ids:\n      enabled: true\n\n', '97628009cee2ff288182df1d85c180b7', '2026-07-18 08:40:30', '2026-07-18 09:00:41', 'nacos', '172.88.0.1', '', 'ingot', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (362, 'in-database.yml', 'PROD_GROUP', 'spring:\n  datasource:\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      initial-size: ${DB_POOL_INITIAL_SIZE:5}           # 初始化连接数\n      min-idle: ${DB_POOL_MIN_IDLE:5}                   # 最小空闲连接\n      max-active: ${DB_POOL_MAX_ACTIVE:50}              # 最大活跃连接（单服务）\n      max-wait: ${DB_POOL_MAX_WAIT:5000}                # 获取连接最大等待时间(ms)\n      \n      # 连接保活和回收配置\n      test-on-borrow: false                              # 申请连接时不检测（影响性能）\n      test-on-return: false                              # 归还连接时不检测\n      test-while-idle: true                              # 空闲时检测\n      validation-query: SELECT 1                         # 检测SQL\n      validation-query-timeout: 3                        # 检测超时时间(s)\n      time-between-eviction-runs-millis: 60000          # 检测间隔(ms)\n      min-evictable-idle-time-millis: 300000            # 最小空闲时间(ms)\n      max-evictable-idle-time-millis: 900000            # 最大空闲时间(ms)\n      \n      # 连接泄露检测\n      remove-abandoned: ${DB_REMOVE_ABANDONED:true}      # 开启泄露检测\n      remove-abandoned-timeout: ${DB_REMOVE_ABANDONED_TIMEOUT:300}  # 泄露超时时间(s)\n      log-abandoned: ${DB_LOG_ABANDONED:true}            # 记录泄露日志\n      \n      # 连接属性配置\n      connection-properties: druid.stat.mergeSql=true;druid.stat.slowSqlMillis=${DB_SLOW_SQL_MILLIS:2000}\n      connection-init-sqls:\n        - SET NAMES utf8mb4\n        - SET SESSION sql_mode=\'STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION\'\n      \n      # SQL监控配置\n      filters: ${DB_FILTERS:stat,wall}  # 生产环境可移除log4j filter\n      \n      # StatFilter配置\n      stat-view-servlet:\n        enabled: ${DRUID_STAT_VIEW_ENABLED:true}\n        url-pattern: /druid/*\n        reset-enable: false                              # 禁止重置统计数据\n        login-username: ${DRUID_USERNAME:admin}\n        login-password: ${DRUID_PASSWORD:DruidAdmin@2025}\n        allow: ${DRUID_ALLOW:127.0.0.1}                 # IP白名单（生产环境严格控制）\n        deny: ${DRUID_DENY:}                            # IP黑名单\n      \n      # WebStatFilter配置\n      web-stat-filter:\n        enabled: ${DRUID_WEB_STAT_ENABLED:true}\n        url-pattern: /*\n        exclusions: \'*.js,*.gif,*.jpg,*.png,*.css,*.ico,/druid/*,/actuator/*\'\n        session-stat-enable: true\n        session-stat-max-count: 1000\n        principal-session-name: user\n        principal-cookie-name: user\n      \n      # SQL防火墙配置\n      wall:\n        enabled: true\n        config:\n          multi-statement-allow: true                   # 允许多条SQL\n          none-base-statement-allow: true\n          comment-allow: true                            # 允许注释\n          select-allow: true\n          select-into-allow: false                       # 禁止SELECT INTO\n          update-allow: true\n          insert-allow: true\n          delete-allow: true\n          create-table-allow: ${DB_WALL_CREATE_TABLE:false}  # 生产环境禁止\n          drop-table-allow: ${DB_WALL_DROP_TABLE:false}      # 生产环境禁止\n          alter-table-allow: ${DB_WALL_ALTER_TABLE:false}    # 生产环境禁止\n          truncate-allow: ${DB_WALL_TRUNCATE:false}          # 生产环境禁止\n      \n      # 监控统计异步化\n      use-global-data-source-stat: true\n      \n      # 超时配置\n      query-timeout: ${DB_QUERY_TIMEOUT:30}              # 查询超时时间(s)\n      transaction-query-timeout: ${DB_TX_QUERY_TIMEOUT:60}  # 事务查询超时(s)\n      \n      # Keep Alive配置（防止连接被中间件断开）\n      keep-alive: ${DB_KEEP_ALIVE:true}\n      keep-alive-between-time-millis: 120000            # Keep Alive间隔(ms)\n      \n      # 异步初始化\n      async-init: true\n\n# MyBatis配置优化\nmybatis:\n  configuration:\n    map-underscore-to-camel-case: true\n    cache-enabled: ${MYBATIS_CACHE_ENABLED:true}        # 二级缓存\n    lazy-loading-enabled: ${MYBATIS_LAZY_LOADING:true}  # 延迟加载\n    aggressive-lazy-loading: false                       # 关闭积极加载\n    multiple-result-sets-enabled: true\n    use-column-label: true\n    use-generated-keys: true\n    auto-mapping-behavior: partial\n    default-executor-type: reuse                        # 复用执行器\n    default-statement-timeout: ${MYBATIS_STATEMENT_TIMEOUT:30}  # 语句超时(s)\n    log-impl: org.apache.ibatis.logging.slf4j.Slf4jImpl\n\n# MyBatis-Plus配置优化\nmybatis-plus:\n  mapper-locations: classpath:/mapper/*Mapper.xml,classpath*:sdk/mapper/*.xml\n  configuration:\n    default-enum-type-handler: com.baomidou.mybatisplus.core.handlers.CompositeEnumTypeHandler\n    # 关闭MyBatis-Plus自带日志（使用SLF4J）\n    log-impl: org.apache.ibatis.logging.slf4j.Slf4jImpl\n  global-config:\n    banner: false\n    enable-sql-runner: false\n    db-config:\n      # 主键策略\n      id-type: ${MYBATIS_PLUS_ID_TYPE:ASSIGN_ID}\n      # 逻辑删除配置\n      logic-delete-value: now()                         # 逻辑已删除值\n      logic-not-delete-value: \"null\"                    # 逻辑未删除值\n      # 字段策略\n      insert-strategy: not_null\n      update-strategy: not_null\n\n', '79398126ace9d09f7618c532e5050f56', '2026-07-18 08:40:30', '2026-07-18 09:00:59', 'nacos', '172.88.0.1', '', 'ingot', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (363, 'in-service-pms.yml', 'PROD_GROUP', 'spring:\n  datasource:\n    # 数据库连接URL配置\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_core}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\n# 业务配置\ningot:\n  security:\n    account:\n      # local 或 remote；remote 时下方 lockout 仅作 Nacos 地板\n      mode: local\n      policy:\n        fallback:\n          local-floor-enabled: true\n        cache:\n          l1-enabled: true\n          l1-ttl: 5m\n          l2-enabled: true\n          l2-ttl: 30m\n      lockout:\n        # 是否启用自动锁定账号\n        enabled: ${ACCOUNT_LOCKOUT_ENABLED:true}\n        # 失败次数阈值\n        maxAttempts: 5\n        # 锁定时长（分钟），0=永久锁定\n        lockDurationMinutes: 30\n        # 失败计数窗口期（分钟）\n        attemptWindowMinutes: 15\n        # 从第几次失败开始给出\"还剩几次将锁定\"的详细提示， 之前的失败一律返回通用\"账号或密码错误\"，避免暴露用户存在性。\n        # 例：maxAttempts=5，hintAfterAttempts=3 时：\n        # 第 1/2 次：通用提示\n        # 第 3 次：剩余 2 次\n        # 第 4 次：剩余 1 次\n        # 第 5 次：触发自动锁定，下次登录命中锁定分支\n        hintAfterAttempts: 3\n    event:\n      # 总开关。false：SecurityEventPublisher 不投递任何事件；true：由 target 决定落点。\n      enabled: true\n      # 主投递目标。\n      # local  = 写入本服务库 security_event（须 classpath 有 Store，通常配 primary-store: mysql）\n      # center = 经 Feign/Transport 上报 ingot-security 中心 admission\n      target: local\n      # target=local 且 classpath 存在多个 SecurityEventStore 时的主 Store id。\n      # 可选值：mysql（MySqlSecurityEventStore）、log（LogSecurityEventStore）。\n      # 仅有一个 Store Bean 时可省略，自动选中。\n      primary-store: mysql\n      # 次要投递目标（迁移 shadow 双写用）。稳定态留空 []。\n      # 元素取值：local | center；与主 target 去重后额外投递一份，shadow 失败不影响主链路 ack。\n      shadow-targets: []\n      # 上报方模块标识，写入 security_event.source_module。\n      # PMS 填 PMS，Member 填 MEMBER。\n      source-module: PMS\n      # 按事件大类过滤是否上报（enabled=true 时生效）；false 则该类别事件在 Publisher 层被丢弃。\n      categories:\n        # AUTH：登录成功/失败等认证类事件\n        auth: true\n        # ACCOUNT：锁定/解锁/创建/删除等账号类事件\n        account: true\n        # CREDENTIAL：改密/重置/强制改密等凭证类事件\n        credential: true\n        # ACCESS：网关封禁/限流违规等访问防护类；PMS/Member 通常不产生，可保持 true\n        access: true\n      # canonical security_event 过期物理删除（PurgeCanonicalSecurityEventTask，cron 0 30 3 * * ?）。\n      # delivery / mysql 在 in-security-policy.yml（本服务已 import）。\n      retention:\n        # 是否启用定时清理；false 等同永久保留。\n        enabled: true\n        # 保留天数；早于 now-days 的记录被删除；0 表示永久保留。\n        days: 30\n        # 单批 DELETE LIMIT 条数，避免长事务与大锁。\n        batch-size: 500\n        # 单次定时任务最多连续执行的批次数。\n        max-rounds: 100\n        # 单次 retention 任务最大执行时长（秒），超时停止本轮。\n        max-duration-seconds: 30\n        # memory/spool 队列使用率超过该百分比时，retention 让步暂停删除。\n        yield-queue-usage-percent: 50\n      # 按 eventType 覆盖默认优先级（BEST_EFFORT | DURABLE），支持 Nacos 热刷新。\n      # 未配置时使用 DefaultPriorityClassifier 内置默认表；示例：\n      # LOGIN_FAILURE: DURABLE\n      priority-overrides: {}\n  oss:\n    minio:\n      url: ${MINIO_URL:http://ingot-cloud:9090}\n      accessKey: ${MINIO_ACCESS_KEY:2NPpKzxFQjyeMTQFEXA1}\n      secretKey: ${MINIO_SECRET_KEY:8SGAp7DhqZCQrYnU9Poyu888pQOB6w4SP2ILHbVU}\n    rustfs:\n      url: ${RUSTFS_URL:http://ingot-cloud:19000}\n      accessKey: ${RUSTFS_ACCESS_KEY:7eYdiTxLbcpsfaNoKSQ0}\n      secretKey: ${RUSTFS_SECRET_KEY:PgXcoiT9bmYBrIUj6S7QHltf0w8KDzWaC5FMqLsx}\n  social:\n    wechat:\n      miniProgramAppId: wx18dc0ea8c6ca1d7d\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:false}\n\n# SpringDoc/Swagger配置（生产环境关闭）\nspringdoc:\n  api-docs:\n    enabled: false\n  swagger-ui:\n    enabled: false\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.pms.mapper\n\n# 生产环境日志级别配置\nlogging:\n  level:\n    root: ${LOG_LEVEL_ROOT:WARN}\n    org.springframework.web: ${LOG_LEVEL_WEB:WARN}\n    org.springframework.security: ${LOG_LEVEL_SECURITY:WARN}\n    org.springframework.cloud: ${LOG_LEVEL_CLOUD:WARN}\n    com.alibaba.nacos.client: ${LOG_LEVEL_NACOS:ERROR}\n    com.alibaba.cloud: ${LOG_LEVEL_ALIBABA_CLOUD:WARN}\n    com.ingot: ${LOG_LEVEL_APP:INFO}\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}', '64cd09820636496b11666d39b9f283a2', '2026-07-18 08:40:30', '2026-08-25 09:16:31', 'nacos', '172.88.0.1', '', 'ingot', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (364, 'in-service-gateway.yml', 'PROD_GROUP', 'spring:\n  cloud:\n    gateway:\n      server:\n        webflux:\n          routes:\n            - id: openapi\n              uri: lb://in-service-gateway\n              predicates:\n                - Path=/v3/api-docs/**\n              filters:\n                - RewritePath=/v3/api-docs/(?<path>.*), /$\\{path}/$\\{path}/v3/api-docs\n            - id: in-service-pms\n              uri: lb://in-service-pms\n              predicates:\n                - Path=/pms/**\n              filters:\n                - StripPrefix=1\n            - id: in-service-member\n              uri: lb://in-service-member\n              predicates:\n                - Path=/member/**\n              filters:\n                - StripPrefix=1\n            - id: in-service-security\n              uri: lb://in-service-security\n              predicates:\n                - Path=/security/**\n              filters:\n                - StripPrefix=1\n            - id: in-crypto-pubkey\n              uri: lb://in-service-bff\n              predicates:\n                - Path=/crypto/public-keys\n            - id: in-service-bff\n              uri: lb://in-service-bff\n              predicates:\n                - Path=/bff/**\n            - id: in-service-auth\n              uri: lb://in-service-auth\n              predicates:\n                - Path=/auth/client/**,/auth/token/**\n              filters:\n                - StripPrefix=1\n\ningot:\n  vc:\n    verifyUrls: []\n    image:\n      opsLimitGetPerMinute: 20\n      opsLimitCheckPerMinute: 40\n  security:\n    account:\n      gateway:\n        # 是否启用账号锁定 AccountLockFilter，默认开启\n        enabled: true\n        # 不检查锁定状态的路径 Ant 模式。\n        excludePathPatterns:\n          - /actuator/**\n          - /bff/auth/**\n    policy:\n      # GatewayRuleClientProperties\n      client:\n        # 跨节点失效订阅开关\n        invalidation-enabled: true\n        # 是否启用 remote → LKG → Nacos 地板 弹性降级链\n        resilience-enabled: true\n        # remote 不可用且 LKG 为空时，是否回落到 Nacos 地板配置\n        local-floor-enabled: true\n        # 共享快照的分层缓存参数。\n        cache:\n          # 1级缓存存活时间\n          l1-ttl: 5m\n          # 2级缓存存活时间\n          l2-ttl: 30m\n    # 限流域开关与来源；groups/rules 地板在 in-security-gateway.yml\n    ratelimit:\n      enabled: true\n      policy:\n        mode: local\n    # 黑白名单开关与来源；items 地板在 in-security-gateway.yml\n    blacklist:\n      enabled: false\n      policy:\n        mode: local\n    # 限流违规升级开关与来源；阈值地板在 in-security-gateway.yml\n    violation-escalation:\n      enabled: true\n      policy:\n        mode: local\n    # 挑战验证开关与来源；groups/policies 地板在 in-security-gateway.yml\n    challenge:\n      enabled: true\n      policy:\n        mode: local\n    # 事件配置\n    event:\n      # 总开关；Gateway 仅在上报 ACCESS 类事件时依赖此项。\n      enabled: true\n      # center：经 Feign 上报 ingot-security admission；不写网关本地 security_event 表。\n      target: center\n      # Gateway 稳定态不需要 shadow；留空 []。\n      shadow-targets: []\n      # 写入中心 security_event.source_module。\n      source-module: GATEWAY\n      # Gateway 通常只产生 ACCESS 类事件；其余类别关闭可减少无效配置。\n      categories:\n        auth: false\n        account: false\n        credential: false\n        access: true\n      # target=center 时 BEST_EFFORT 仍走 memory 缓冲后再 Feign 批量上报。\n      delivery:\n        memory:\n          queue-capacity: 2048\n          batch-size: 32\n          poll-timeout-ms: 100\n          shutdown-timeout-ms: 5000\n        # DURABLE 事件（如 BLACKLIST_BLOCK）仍需要 spool；未显式配置时使用下方 Java 默认值：\n        # spool.directory 为父目录，运行时再拼 spring.application.name。\n      # Gateway 不写本地 canonical 表，通常不需要 retention；中心库由 in-service-security 清理。\n      retention:\n        enabled: false\n\n# SpringDoc/Swagger配置（生产环境关闭）\nspringdoc:\n  api-docs:\n    enabled: false\n  swagger-ui:\n    enabled: false\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n\n# 生产环境日志级别配置\nlogging:\n  level:\n    root: ${LOG_LEVEL_ROOT:WARN}\n    org.springframework.web: ${LOG_LEVEL_WEB:WARN}\n    org.springframework.security: ${LOG_LEVEL_SECURITY:WARN}\n    org.springframework.cloud: ${LOG_LEVEL_CLOUD:WARN}\n    com.alibaba.nacos.client: ${LOG_LEVEL_NACOS:ERROR}\n    com.alibaba.cloud: ${LOG_LEVEL_ALIBABA_CLOUD:WARN}\n    com.ingot: ${LOG_LEVEL_APP:INFO}\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}', '54e0069178b103e23d6f871974bd6845', '2026-07-18 08:40:30', '2026-08-28 06:41:51', 'nacos', '172.88.0.1', '', 'ingot', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (365, 'in-service-auth.yml', 'PROD_GROUP', 'spring:\n  mvc:\n    static-path-pattern: /static/**\n  thymeleaf:\n    cache: false\n    prefix: classpath:/templates/\n    suffix: .html\n    encoding: UTF-8\n    servlet:\n      content-type: text/html\n  datasource:\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_auth}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\ningot:\n  security:\n    oauth2:\n      auth:\n        loginFormUrl: https://login.ingotcloud.top/oauth2/challenge\n        issuer: http://${SERVICE_AUTH_HOST:localhost:5100}\n      resource:\n        publicUrls:\n          - /favicon.ico,GET\n          - /static/**,GET\n          - /logout,*\n          - /error,*\n    jwk:\n      key-lifetime: 90d\n      key-grace-period: 2h\n      max-active-keys: 3\n      cache-refresh-interval: 5m\n      master-key: ${AUTH_JWK_MASTER_KEY}\n      enable-encryption: true\n    access:\n      mode: local\n      loginFailure:\n        ip:\n          enabled: true\n          # 50次命中\n          maxAttempts: 50\n          # 时间窗口\n          windowMinutes: 1\n          # 锁定时间，秒\n          blockTtlSec: 3600\n          blockKeyType: \"IP\"\n        device:\n          enabled: false\n        client:\n          enabled: false\n        accountIp:\n          enabled: false\n    session:\n      # 会话存储不可用宽限期；超期一律拒绝，会话键不存在不在宽限范围内\n      store-unavailable-grace: 30s\n      # local：并发策略只读下面的 concurrency 段，不依赖安全中心（A9 场景）\n      mode: local\n      concurrency:\n        # 关闭后登录路径退回「只认 Client 的 UNIQUE / STANDARD」，紧急回退开关\n        enabled: true\n        # 0 = 不限并发；此时 Client 配置为 UNIQUE 仍按单会话处理\n        max-sessions: 0\n        # 会话数统计维度\n        dimension: USER_CLIENT\n        # 超限处置方式\n        overflow: KICK_OLDEST\n        # 管理用户（UserTypeEnum.ADMIN）是否强制单会话\n        admin-forbid-concurrent: false\n    event:\n      # 安全事件总开关；false 时不做任何上报\n      enabled: true\n      # center：会话撤销等 AUTH 事件 Feign 上报安全中心，Auth 本库不落 security_event\n      target: center\n      shadow-targets: []\n      # 写入 security_event.source_module\n      sourceModule: AUTH\n      # 安全事件大类上报开关\n      categories:\n        auth: true\n        account: false\n        credential: false\n        access: false\n      retention:\n        enabled: false\n\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:false}  # 生产环境关闭\n\n# SpringDoc/Swagger配置（生产环境关闭）\nspringdoc:\n  api-docs:\n    enabled: false\n  swagger-ui:\n    enabled: false\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.auth.mapper\n\n# 日志级别配置\nlogging:\n  level:\n    root: ${LOG_LEVEL_ROOT:WARN}\n    org.springframework.web: ${LOG_LEVEL_WEB:WARN}\n    org.springframework.security: ${LOG_LEVEL_SECURITY:WARN}\n    org.springframework.cloud: ${LOG_LEVEL_CLOUD:WARN}\n    com.alibaba.nacos.client: ${LOG_LEVEL_NACOS:ERROR}\n    com.alibaba.cloud: ${LOG_LEVEL_ALIBABA_CLOUD:WARN}\n    com.ingot: ${LOG_LEVEL_APP:INFO}\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}', 'f419460024796381461f026d2fe9a504', '2026-07-18 08:40:30', '2026-08-21 07:00:34', 'nacos', '172.88.0.1', '', 'ingot', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (366, 'in-service-member.yml', 'PROD_GROUP', 'spring:\n  datasource:\n    # 数据库连接URL配置\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_member}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\n# Ingot业务配置\ningot:\n  security:\n    account:\n      # local 或 remote；remote 时下方 lockout 仅作 Nacos 地板\n      mode: local\n      policy:\n        fallback:\n          local-floor-enabled: true\n        cache:\n          l1-enabled: true\n          l1-ttl: 5m\n          l2-enabled: true\n          l2-ttl: 30m\n      lockout:\n        # 是否启用自动锁定账号\n        enabled: ${ACCOUNT_LOCKOUT_ENABLED:true}\n        # 失败次数阈值\n        maxAttempts: 5\n        # 锁定时长（分钟），0=永久锁定\n        lockDurationMinutes: 30\n        # 失败计数窗口期（分钟）\n        attemptWindowMinutes: 15\n        # 从第几次失败开始给出\"还剩几次将锁定\"的详细提示， 之前的失败一律返回通用\"账号或密码错误\"，避免暴露用户存在性。\n        # 例：maxAttempts=5，hintAfterAttempts=3 时：\n        # 第 1/2 次：通用提示\n        # 第 3 次：剩余 2 次\n        # 第 4 次：剩余 1 次\n        # 第 5 次：触发自动锁定，下次登录命中锁定分支\n        hintAfterAttempts: 3\n    event:\n      # 总开关。false：SecurityEventPublisher 不投递任何事件；true：由 target 决定落点。\n      enabled: true\n      # 主投递目标。\n      # local  = 写入本服务库 security_event（须 classpath 有 Store，通常配 primary-store: mysql）\n      # center = 经 Feign/Transport 上报 ingot-security 中心 admission\n      target: local\n      # target=local 且 classpath 存在多个 SecurityEventStore 时的主 Store id。\n      # 可选值：mysql（MySqlSecurityEventStore）、log（LogSecurityEventStore）。\n      # 仅有一个 Store Bean 时可省略，自动选中。\n      primary-store: mysql\n      # 次要投递目标（迁移 shadow 双写用）。稳定态留空 []。\n      # 元素取值：local | center；与主 target 去重后额外投递一份，shadow 失败不影响主链路 ack。\n      shadow-targets: []\n      # 上报方模块标识，写入 security_event.source_module。\n      # PMS 填 PMS，Member 填 MEMBER。\n      source-module: MEMBER\n      # 按事件大类过滤是否上报（enabled=true 时生效）；false 则该类别事件在 Publisher 层被丢弃。\n      categories:\n        # AUTH：登录成功/失败等认证类事件\n        auth: true\n        # ACCOUNT：锁定/解锁/创建/删除等账号类事件\n        account: true\n        # CREDENTIAL：改密/重置/强制改密等凭证类事件\n        credential: true\n        # ACCESS：网关封禁/限流违规等访问防护类；PMS/Member 通常不产生，可保持 true\n        access: true\n      # canonical security_event 过期物理删除（PurgeCanonicalSecurityEventTask，cron 0 30 3 * * ?）。\n      # delivery / mysql 在 in-security-policy.yml（本服务已 import）。\n      retention:\n        # 是否启用定时清理；false 等同永久保留。\n        enabled: true\n        # 保留天数；早于 now-days 的记录被删除；0 表示永久保留。\n        days: 30\n        # 单批 DELETE LIMIT 条数，避免长事务与大锁。\n        batch-size: 500\n        # 单次定时任务最多连续执行的批次数。\n        max-rounds: 100\n        # 单次 retention 任务最大执行时长（秒），超时停止本轮。\n        max-duration-seconds: 30\n        # memory/spool 队列使用率超过该百分比时，retention 让步暂停删除。\n        yield-queue-usage-percent: 50\n      # 按 eventType 覆盖默认优先级（BEST_EFFORT | DURABLE），支持 Nacos 热刷新。\n      # 未配置时使用 DefaultPriorityClassifier 内置默认表；示例：\n      # LOGIN_FAILURE: DURABLE\n      priority-overrides: {}\n  oss:\n    minio:\n      url: ${MINIO_URL:http://ingot-cloud:9090}\n      accessKey: ${MINIO_ACCESS_KEY:2NPpKzxFQjyeMTQFEXA1}\n      secretKey: ${MINIO_SECRET_KEY:8SGAp7DhqZCQrYnU9Poyu888pQOB6w4SP2ILHbVU}\n  social:\n    wechat:\n      miniProgramAppId: wx18dc0ea8c6ca1d7d\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:false}\n\n# SpringDoc/Swagger配置（生产环境关闭）\nspringdoc:\n  api-docs:\n    enabled: false\n  swagger-ui:\n    enabled: false\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.member.mapper\n\n# 生产环境日志级别配置\nlogging:\n  level:\n    root: ${LOG_LEVEL_ROOT:WARN}\n    org.springframework.web: ${LOG_LEVEL_WEB:WARN}\n    org.springframework.security: ${LOG_LEVEL_SECURITY:WARN}\n    org.springframework.cloud: ${LOG_LEVEL_CLOUD:WARN}\n    com.alibaba.nacos.client: ${LOG_LEVEL_NACOS:ERROR}\n    com.alibaba.cloud: ${LOG_LEVEL_ALIBABA_CLOUD:WARN}\n    com.ingot: ${LOG_LEVEL_APP:INFO}\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}\n', 'fafa43ab6c667bc5dff4e0889e220aaf', '2026-07-18 08:40:30', '2026-08-25 09:16:06', 'nacos', '172.88.0.1', '', 'ingot', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (367, 'in-service-security.yml', 'PROD_GROUP', 'spring:\n  datasource:\n    # 数据库连接URL配置\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_security}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\n# Ingot业务配置\ningot:\n  security:\n    event:\n      # 中心 admission 接收的事件异步入库；false 则 admission 入队被禁用。\n      enabled: true\n      # 中心将事件写入本库 ingot_security.security_event。\n      target: local\n      primary-store: mysql\n      shadow-targets: []\n      source-module: SECURITY\n      categories:\n        auth: true\n        account: true\n        credential: true\n        access: true\n      # 中心库数据量大，retention.days 可按合规要求拉长（如 90～180）。\n      # delivery / mysql 在 in-security-policy.yml（本服务已 import）。\n      retention:\n        enabled: true\n        days: 90\n        batch-size: 500\n        max-rounds: 100\n        max-duration-seconds: 30\n        yield-queue-usage-percent: 50\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:false}\n\n# SpringDoc/Swagger配置（生产环境关闭）\nspringdoc:\n  api-docs:\n    enabled: false\n  swagger-ui:\n    enabled: false\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.security.mapper\n\n# 生产环境日志级别配置\nlogging:\n  level:\n    root: ${LOG_LEVEL_ROOT:WARN}\n    org.springframework.web: ${LOG_LEVEL_WEB:WARN}\n    org.springframework.security: ${LOG_LEVEL_SECURITY:WARN}\n    org.springframework.cloud: ${LOG_LEVEL_CLOUD:WARN}\n    com.alibaba.nacos.client: ${LOG_LEVEL_NACOS:ERROR}\n    com.alibaba.cloud: ${LOG_LEVEL_ALIBABA_CLOUD:WARN}\n    com.ingot: ${LOG_LEVEL_APP:INFO}\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}\n', 'd900c64554c790aa092fd7121465a2e0', '2026-07-18 08:40:30', '2026-08-25 09:16:50', 'nacos', '172.88.0.1', '', 'ingot', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (368, 'in-service-bff.yml', 'PROD_GROUP', 'ingot:\n  security:\n    oauth2:\n      resource:\n        public-urls:\n          - /crypto/public-keys,GET\n    # 账号锁定 BFF 登录短路：解密后查 Redis name key；默认拦截不调 Auth\n    account:\n      bff:\n        # 是否在登录解密后检查 Redis name key，默认开启。\n        enabled: true\n        # BFF 拦截时是否仍调 Auth 以产生 LOGIN_FAILURE；默认关闭。\n        emit-login-failure-on-bff-block: false\n  bff:\n    client-id: ingot-bff\n    scope: system\n    # 管理用户:0, C端用户:1\n    user-type: \"0\"\n    session-ttl: 7200\n    redirect-uri: http://localhost:5400/bff/auth/callback\n    cookie:\n      # 开发环境不设置 domain（localhost 可用），生产环境设置顶级域名如 .ingotcloud.top\n      domain: ${BFF_COOKIE_DOMAIN:}\n      # 开发环境 false，生产必须 true\n      secure: ${BFF_COOKIE_SECURE:false}\n      same-site: ${BFF_COOKIE_SAME_SITE:Lax}\n    security:\n      # 客户端指纹校验，防止 Cookie 盗用\n      fingerprint-enabled: ${BFF_FINGERPRINT_ENABLED:true}\n      # 指纹模式: device（前端设备指纹，推荐）/ ip_ua（服务端 IP+UA，降级方案）\n      fingerprint-mode: ${BFF_FINGERPRINT_MODE:device}\n      # 信任的前端应用域名列表\n      allowed-frontends:\n        - http://localhost:1798\n        - http://localhost:5798\n      default-redirect-uri:\n        - http://localhost:5798\n\n# SpringDoc/Swagger配置（生产环境关闭）\nspringdoc:\n  api-docs:\n    enabled: false\n  swagger-ui:\n    enabled: false\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n\n# 生产环境日志级别配置\nlogging:\n  level:\n    root: ${LOG_LEVEL_ROOT:WARN}\n    org.springframework.web: ${LOG_LEVEL_WEB:WARN}\n    org.springframework.security: ${LOG_LEVEL_SECURITY:WARN}\n    org.springframework.cloud: ${LOG_LEVEL_CLOUD:WARN}\n    com.alibaba.nacos.client: ${LOG_LEVEL_NACOS:ERROR}\n    com.alibaba.cloud: ${LOG_LEVEL_ALIBABA_CLOUD:WARN}\n    com.ingot: ${LOG_LEVEL_APP:INFO}\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}', 'f0d43e865d796efd46f3bbbb29320086', '2026-07-18 08:40:30', '2026-08-25 09:15:48', 'nacos', '172.88.0.1', '', 'ingot', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (369, 'in-security-crypto.yml', 'PROD_GROUP', 'ingot:\n  security:\n    crypto:\n      hybrid:\n        response-wrap: DATA_ONLY          # DATA_ONLY:只加密 R.data, FULL:加密所有\n        active-kid: k-2026-08             # 当前激活 kid，响应头 In-Crypto-Kv 会回这个值\n        public-key-endpoint-enabled: true # 仅公钥下发服务开 true，其它服务可 false\n        replay-namespace: crypto\n        key-pairs:\n          k-2026-07:                      # kid 自定义，与前端请求头 In-Crypto-Kv 对应\n            public-key: \n            private-key: \n          k-2026-08:\n            public-key: \n            private-key: \n      secretKeys:\n        # 加密密钥 - 生产环境必须通过环境变量配置\n        aes: ${CRYPTO_AES_KEY:ingotingotingot1}\n        aes_gcm: ${CRYPTO_AES_GCM_KEY:ingotingotingot1}', '31351f80f66c047c1afa4d6293322545', '2026-07-18 08:40:30', '2026-07-18 08:40:30', 'nacos', '172.88.0.1', '', 'ingot', '加密算法，密钥，密钥轮换', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (370, 'in-security-policy.yml', 'PROD_GROUP', '# 跨服务安全策略地板。消费者：PMS / Member / Security / BFF。\n# Auth、Gateway 不要 import。\n# 含：replay、credential、account.signal、event.delivery/mysql。\n# 不含：event.target/source-module、account.lockout、网关限流规则。\ningot:\n  security:\n    ignoreTenantValidateRoleCodeList:\n      - role_admin\n    \n    # 重放配置\n    replay:\n      enabled: true\n      window: 5m\n      clock-skew: 5m\n      key-prefix: \"replay:\"\n      fail-open: false\n    \n    # 凭证配置\n    credential:\n      policy:\n        # 策略加载模式：local（本地配置）或 remote（远程加载）\n        mode: ${CREDENTIAL_MODE:local}\n\n        # 本地策略配置\n        strength:\n          # 是否启用\n          enabled: true\n          # 最小长度\n          min-length: 8\n          # 最大长度\n          max-length: 32\n          # 是否要求大写字母\n          require-uppercase: false\n          # 是否要求小写字母\n          require-lowercase: false\n          # 是否要求数字\n          require-digit: false\n          # 是否要求特殊字符\n          requireSpecialChar: false\n          # 特殊字符集合\n          specialChars: \"!@#$%^&*()_+-=[]{}|;:,.<>?\"\n          # 禁止的模式\n          forbiddenPatterns:\n            - \"password\"\n            - \"123456\"\n            - \"admin\"\n            - \"qwerty\"\n          # 禁止包含用户属性\n          forbidUserAttributes: false\n\n        history:\n          # 是否启用\n          enabled: true\n          # 检查最近N次密码\n          check-count: 5\n\n        expiration:\n          # 是否启用 \n          enabled: false\n          # 最大有效天数\n          max-days: 90\n          # 提前警告天数\n          warningDaysBefore: 7\n          # 宽限登录次数\n          graceLoginCount: 3\n\n        initialPassword:\n          # 初始密码生成方式：RANDOM-随机生成；FIXED-统一默认密码\n          generation: RANDOM\n          # 随机初始密码长度（generation=RANDOM 时生效）\n          length: 10\n          # 统一默认密码（generation=FIXED 时生效）\n          fixedPassword: In@123456\n          # 初始密码有效小时数；0 表示不限制。超过后视为初始密码失效，需重新重置。\n          validHours: 72\n          # 用后失效：初始密码修改成功后即失效（依赖 mustChangePwd/force_change 清除，默认 true）\n          oneTime: true\n          # 首次登录是否强制修改密码\n          forceChangeOnFirstLogin: true\n\n    # 永久锁 Redis TTL（PMS/Member 写、BFF 读）；必须全局同一份\n    account:\n      signal:\n        # 永久锁定时 uid/name key 的 TTL（天），默认 30。\n        permanent-lock-ttl-days: 30\n\n    # PMS/Member/Security 写本地 canonical / spool 时共用。\n    # Auth/Gateway 不 import 本文件；BFF import 但不启用 recording。\n    event:\n      # 投递层：BEST_EFFORT 走 memory，DURABLE 走 spool（两条独立管道，非溢出关系）。\n      delivery:\n        # BEST_EFFORT 有界内存队列参数；后台线程 security-recording-memory 攒批后投递。\n        memory:\n          # 内存队列容量；满时新 BEST_EFFORT 事件 DROPPED，不阻塞业务线程。\n          queue-capacity: 2048\n          # memory worker 单次 claim 条数上限。\n          batch-size: 32\n          # worker 攒批 poll 超时（毫秒）；队列空则等待该时长后再次 poll。\n          poll-timeout-ms: 100\n          # 进程关闭时等待 memory worker 排空队列的最长时间（毫秒）。\n          shutdown-timeout-ms: 5000\n        # DURABLE 本地 file spool；后台线程 security-recording-durable 持续 claim → 投递 → ack/nack 重试。\n        spool:\n          # spool 根目录（append-only segment 文件）。\n          directory: /ingot-data/security-recording/spool\n          # spool 目录总磁盘配额（如 1GB、512MB）。\n          max-bytes: 1GB\n          # 单个 segment 文件大小上限，达上限滚动新文件。\n          segment-bytes: 64MB\n          # 业务线程同步等待 spool 接纳 DURABLE 事件的最长时间（毫秒）；超时返回 FAILED（业务仍 fail-open）。\n          durable-ack-timeout-ms: 20\n          # durable worker 每次从 spool claim 的条数上限。\n          replay-batch-size: 32\n          # 投递失败 nack 后重试初始退避（毫秒）。\n          retry-initial-ms: 1000\n          # 重试退避上限（毫秒）。\n          retry-max-ms: 60000\n      # MySQL SecurityEventStore 写入侧参数（target=local 且 primary-store=mysql 时生效）。\n      mysql:\n        # 并发写入信号量许可数；默认 1，避免 canonical security_event 热点写冲突。\n        max-concurrent-writes: 1\n        # 单批 INSERT 事务超时（秒）。\n        transaction-timeout-seconds: 5\n', '31f7507779ad721dadcb2718296d3b48', '2026-07-18 08:40:30', '2026-08-25 09:15:34', 'nacos', '172.88.0.1', '', 'ingot', '密码策略，登录策略，会话策略，账号策略等', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (371, 'in-security-gateway.yml', 'DEV_GROUP', 'ingot:\n  security:\n    # 限流域：编译为 Sentinel GatewayFlowRule；未配置的路径默认不限流（白名单式）\n    ratelimit:\n      policy:\n        groups:\n          - code: login-auth-floor\n            name: 登录授权层\n            enabled: true\n            pattern-list:\n              - path: /bff/auth/platform/login\n                method: POST\n              - path: /bff/auth/tenant/login\n                method: POST\n          - code: api-business-floor\n            name: 公共业务层\n            enabled: true\n            pattern-list:\n              - path: /iam/**\n                method: ANY\n              - path: /member/**\n                method: ANY\n              - path: /security/**\n                method: ANY\n        rules:\n          - code: login-ip-floor\n            group-code: login-auth-floor\n            # IP / DEVICE / USER\n            dimension: IP  \n            # 平均 QPS\n            qps: 8\n            # 突发容量\n            burst: 12\n            # 统计窗口（秒）\n            interval-sec: 60\n            # F=快速失败(429) Q=排队\n            control-behavior: F\n            enabled: true\n            priority: 0\n          - code: biz-ip-floor\n            group-code: api-business-floor\n            dimension: IP\n            qps: 150\n            burst: 225\n            interval-sec: 1\n            control-behavior: F\n            enabled: true\n            priority: 10\n    # 黑白名单：静态名单 + Redis 临时封禁（限流违规升级）\n    blacklist:\n      policy:\n        items:\n          # BLACK / WHITE\n          - list-type: WHITE\n            # IP / DEVICE / USER / CIDR / USER_AGENT / REFERER\n            key-type: IP\n            key-value: 127.0.0.1\n            enabled: true\n    # 限流违规升级：滑动窗口计数\n    violation-escalation:\n      policy:\n        window-sec: 60\n        block-threshold: 25\n        temp-block-ttl-sec: 900\n        enabled: true\n    # 挑战验证地板：登录强制滑块。不要写 challenge.enabled / policy.mode\n    challenge:\n      policy:\n        groups:\n          - code: login-auth-floor\n            name: 登录认证入口\n            enabled: true\n            pattern-list:\n              - path: /bff/auth/platform/login\n                method: POST\n              - path: /bff/auth/tenant/login\n                method: POST\n        policies:\n          - code: login-always-floor\n            group-code: login-auth-floor\n            trigger: ALWAYS\n            challenge-type: SLIDER\n            scope: login\n            pass-token-ttl-sec: 300\n            pass-token-remaining: 1\n            enabled: true\n            priority: 0', 'e563c4509ce8deaed7dd8b88e3e3abd1', '2026-08-25 08:14:35', '2026-09-17 02:59:03', 'nacos', '192.168.65.1', '', 'ingot', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (372, 'in-security-gateway.yml', 'TEST_GROUP', '# 网关安全策略地板（仅 Gateway import）。\n# 只放各域 policy 数值（groups / rules / items），不要写 enabled / policy.mode，\n# 以免与 in-service-gateway.yml 同前缀覆盖。\n# 开关与 mode 仍在 in-service-gateway.yml。\ningot:\n  security:\n    # 限流域：编译为 Sentinel GatewayFlowRule；未配置的路径默认不限流（白名单式）\n    ratelimit:\n      policy:\n        groups:\n          - code: login-auth-floor\n            name: 登录授权层\n            enabled: true\n            pattern-list:\n              - path: /bff/auth/login  # 网关对外路径（Ant 风格）；非下游 /test/**\n                method: POST           # 当前 Sentinel 编译忽略 method，保留供扩展\n          - code: api-business-floor\n            name: 公共业务层\n            enabled: true\n            pattern-list:\n              - path: /pms/**\n                method: ANY\n              - path: /member/**\n                method: ANY\n              - path: /security/**\n                method: ANY\n        rules:\n          - code: login-ip-floor\n            group-code: login-auth-floor\n            # IP / DEVICE / USER\n            dimension: IP\n            # 平均 QPS\n            qps: 8\n            # 突发容量\n            burst: 12\n            # 统计窗口（秒）\n            interval-sec: 60\n            # F=快速失败(429) Q=排队\n            control-behavior: F\n            enabled: true\n            priority: 0\n          - code: biz-ip-floor\n            group-code: api-business-floor\n            dimension: IP\n            qps: 150\n            burst: 225\n            interval-sec: 1\n            control-behavior: F\n            enabled: true\n            priority: 10\n    # 黑白名单：静态名单 + Redis 临时封禁（限流违规升级）\n    blacklist:\n      policy:\n        items:\n          # BLACK / WHITE\n          - list-type: WHITE\n            # IP / DEVICE / USER / CIDR / USER_AGENT / REFERER\n            key-type: IP\n            key-value: 127.0.0.1\n            enabled: true\n    # 限流违规升级：滑动窗口计数\n    violation-escalation:\n      policy:\n        window-sec: 60\n        block-threshold: 25\n        temp-block-ttl-sec: 900\n        enabled: true\n    # 挑战验证地板：登录强制滑块。不要写 challenge.enabled / policy.mode\n    challenge:\n      policy:\n        groups:\n          - code: login-auth-floor\n            name: 登录认证入口\n            enabled: true\n            pattern-list:\n              - path: /bff/auth/login\n                method: POST\n        policies:\n          - code: login-always-floor\n            group-code: login-auth-floor\n            trigger: ALWAYS\n            challenge-type: SLIDER\n            scope: login\n            pass-token-ttl-sec: 300\n            pass-token-remaining: 1\n            enabled: true\n            priority: 0', '5d7ea21762d5421df402cf6390e8fcdc', '2026-08-25 09:14:19', '2026-08-28 06:42:20', 'nacos', '172.88.0.1', '', 'ingot', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (373, 'in-security-gateway.yml', 'PROD_GROUP', '# 网关安全策略地板（仅 Gateway import）。\n# 只放各域 policy 数值（groups / rules / items），不要写 enabled / policy.mode，\n# 以免与 in-service-gateway.yml 同前缀覆盖。\n# 开关与 mode 仍在 in-service-gateway.yml。\ningot:\n  security:\n    # 限流域：编译为 Sentinel GatewayFlowRule；未配置的路径默认不限流（白名单式）\n    ratelimit:\n      policy:\n        groups:\n          - code: login-auth-floor\n            name: 登录授权层\n            enabled: true\n            pattern-list:\n              - path: /bff/auth/login  # 网关对外路径（Ant 风格）；非下游 /test/**\n                method: POST           # 当前 Sentinel 编译忽略 method，保留供扩展\n          - code: api-business-floor\n            name: 公共业务层\n            enabled: true\n            pattern-list:\n              - path: /pms/**\n                method: ANY\n              - path: /member/**\n                method: ANY\n              - path: /security/**\n                method: ANY\n        rules:\n          - code: login-ip-floor\n            group-code: login-auth-floor\n            # IP / DEVICE / USER\n            dimension: IP\n            # 平均 QPS\n            qps: 8\n            # 突发容量\n            burst: 12\n            # 统计窗口（秒）\n            interval-sec: 60\n            # F=快速失败(429) Q=排队\n            control-behavior: F\n            enabled: true\n            priority: 0\n          - code: biz-ip-floor\n            group-code: api-business-floor\n            dimension: IP\n            qps: 150\n            burst: 225\n            interval-sec: 1\n            control-behavior: F\n            enabled: true\n            priority: 10\n    # 黑白名单：静态名单 + Redis 临时封禁（限流违规升级）\n    blacklist:\n      policy:\n        items:\n          # BLACK / WHITE\n          - list-type: WHITE\n            # IP / DEVICE / USER / CIDR / USER_AGENT / REFERER\n            key-type: IP\n            key-value: 127.0.0.1\n            enabled: true\n    # 限流违规升级：滑动窗口计数\n    violation-escalation:\n      policy:\n        window-sec: 60\n        block-threshold: 25\n        temp-block-ttl-sec: 900\n        enabled: true\n    # 挑战验证地板：登录强制滑块。不要写 challenge.enabled / policy.mode\n    challenge:\n      policy:\n        groups:\n          - code: login-auth-floor\n            name: 登录认证入口\n            enabled: true\n            pattern-list:\n              - path: /bff/auth/login\n                method: POST\n        policies:\n          - code: login-always-floor\n            group-code: login-auth-floor\n            trigger: ALWAYS\n            challenge-type: SLIDER\n            scope: login\n            pass-token-ttl-sec: 300\n            pass-token-remaining: 1\n            enabled: true\n            priority: 0\n', '4fc0d216623173e6adaa3874da9831ae', '2026-08-25 09:15:24', '2026-08-28 06:42:30', 'nacos', '172.88.0.1', '', 'ingot', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (376, 'in-service-iam.yml', 'DEV_GROUP', 'spring:\n  datasource:\n    # 数据库连接URL配置\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_iam}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&connectionTimeZone=UTC&forceConnectionTimeZoneToSession=true&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\n# Ingot业务配置\ningot:\n  security:\n    account:\n      # local 或 remote；remote 时下方 lockout 仅作 Nacos 地板\n      mode: local\n      policy:\n        fallback:\n          local-floor-enabled: true\n        cache:\n          l1-enabled: true\n          l1-ttl: 5m\n          l2-enabled: true\n          l2-ttl: 30m\n      lockout:\n        # 是否启用自动锁定账号\n        enabled: ${ACCOUNT_LOCKOUT_ENABLED:true}\n        # 失败次数阈值\n        maxAttempts: 5\n        # 锁定时长（分钟），0=永久锁定\n        lockDurationMinutes: 30\n        # 失败计数窗口期（分钟）\n        attemptWindowMinutes: 15\n        # 从第几次失败开始给出\"还剩几次将锁定\"的详细提示， 之前的失败一律返回通用\"账号或密码错误\"，避免暴露用户存在性。\n        # 例：maxAttempts=5，hintAfterAttempts=3 时：\n        # 第 1/2 次：通用提示\n        # 第 3 次：剩余 2 次\n        # 第 4 次：剩余 1 次\n        # 第 5 次：触发自动锁定，下次登录命中锁定分支\n        hintAfterAttempts: 3\n    event:\n      # 总开关。false：SecurityEventPublisher 不投递任何事件；true：由 target 决定落点。\n      enabled: true\n      # 主投递目标。\n      # local  = 写入本服务库 security_event（须 classpath 有 Store，通常配 primary-store: mysql）\n      # center = 经 Feign/Transport 上报 ingot-security 中心 admission\n      target: local\n      # target=local 且 classpath 存在多个 SecurityEventStore 时的主 Store id。\n      # 可选值：mysql（MySqlSecurityEventStore）、log（LogSecurityEventStore）。\n      # 仅有一个 Store Bean 时可省略，自动选中。\n      primary-store: mysql\n      # 次要投递目标（迁移 shadow 双写用）。稳定态留空 []。\n      # 元素取值：local | center；与主 target 去重后额外投递一份，shadow 失败不影响主链路 ack。\n      shadow-targets: []\n      # 上报方模块标识，写入 security_event.source_module。\n      # IAM 填 IAM，Member 填 MEMBER。\n      source-module: IAM\n      # 按事件大类过滤是否上报（enabled=true 时生效）；false 则该类别事件在 Publisher 层被丢弃。\n      categories:\n        # AUTH：登录成功/失败等认证类事件\n        auth: true\n        # ACCOUNT：锁定/解锁/创建/删除等账号类事件\n        account: true\n        # CREDENTIAL：改密/重置/强制改密等凭证类事件\n        credential: true\n        # ACCESS：网关封禁/限流违规等访问防护类；IAM/Member 通常不产生，可保持 true\n        access: true\n      # canonical security_event 过期物理删除（PurgeCanonicalSecurityEventTask，cron 0 30 3 * * ?）。\n      # delivery / mysql 在 in-security-policy.yml（本服务已 import）。\n      retention:\n        # 是否启用定时清理；false 等同永久保留。\n        enabled: true\n        # 保留天数；早于 now-days 的记录被删除；0 表示永久保留。\n        days: 30\n        # 单批 DELETE LIMIT 条数，避免长事务与大锁。\n        batch-size: 500\n        # 单次定时任务最多连续执行的批次数。\n        max-rounds: 100\n        # 单次 retention 任务最大执行时长（秒），超时停止本轮。\n        max-duration-seconds: 30\n        # memory/spool 队列使用率超过该百分比时，retention 让步暂停删除。\n        yield-queue-usage-percent: 50\n      # 按 eventType 覆盖默认优先级（BEST_EFFORT | DURABLE），支持 Nacos 热刷新。\n      # 未配置时使用 DefaultPriorityClassifier 内置默认表；示例：\n      # LOGIN_FAILURE: DURABLE\n      priority-overrides: {}\n  oss:\n    minio:\n      url: ${MINIO_URL:http://ingot-cloud:9090}\n      accessKey: ${MINIO_ACCESS_KEY:2NPpKzxFQjyeMTQFEXA1}\n      secretKey: ${MINIO_SECRET_KEY:8SGAp7DhqZCQrYnU9Poyu888pQOB6w4SP2ILHbVU}\n    rustfs:\n      url: ${RUSTFS_URL:http://ingot-cloud:19000}\n      accessKey: ${RUSTFS_ACCESS_KEY:7eYdiTxLbcpsfaNoKSQ0}\n      secretKey: ${RUSTFS_SECRET_KEY:PgXcoiT9bmYBrIUj6S7QHltf0w8KDzWaC5FMqLsx}\n  social:\n    wechat:\n      miniProgramAppId: wx18dc0ea8c6ca1d7d\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:true}  # 生产环境关闭\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.iam.mapper\n\n# 开发环境日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}\n', 'ee90a9a4a4dfe8a1f105ca150b2839fb', '2026-09-14 06:10:28', '2026-09-14 06:10:28', 'nacos', '172.88.0.1', '', 'ingot', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (377, 'in-bff-apps.yml', 'DEV_GROUP', '# 仅 Gateway 与 BFF 加载\ningot:\n  bff:\n    require-https: false\n    apps:\n      - app-id: platform-admin\n        domain: PLATFORM\n        admin-origin: http://localhost:5799\n        login-origin: http://localhost:1799\n        oauth-client-id: in-bff-platform\n        oauth-scope: system\n        oauth-redirect-uri: http://localhost:5400/bff/auth/platform/callback\n        default-return-to: /\n      - app-id: tenant-admin\n        domain: TENANT\n        admin-origin: http://localhost:5798\n        login-origin: http://localhost:1798\n        oauth-client-id: in-bff-tenant\n        oauth-scope: system\n        oauth-redirect-uri: http://localhost:5400/bff/auth/tenant/callback\n        default-return-to: /\n', 'bbf0561c7e1673a4c606e497f9980051', '2026-09-17 02:57:57', '2026-09-17 02:57:57', 'nacos', '192.168.65.1', '', 'ingot', NULL, NULL, NULL, 'yaml', NULL, '');
COMMIT;

