        # 例：maxAttempts=5，hintAfterAttempts=3 时：\n        # 第 1/2 次：通用提示\n        # 第 3 次：剩余 2 次\n        # 第 4 次：剩余 1 次\n        # 第 5 次：触发自动锁定，下次登录命中锁定分支\n        hintAfterAttempts: 3\n  oss:\n    minio:\n      url: ${MINIO_URL:http://ingot-cloud:9090}\n      accessKey: ${MINIO_ACCESS_KEY:2NPpKzxFQjyeMTQFEXA1}\n      secretKey: ${MINIO_SECRET_KEY:8SGAp7DhqZCQrYnU9Poyu888pQOB6w4SP2ILHbVU}\n    rustfs:\n      url: ${RUSTFS_URL:http://ingot-cloud:19000}\n      accessKey: ${RUSTFS_ACCESS_KEY:7eYdiTxLbcpsfaNoKSQ0}\n      secretKey: ${RUSTFS_SECRET_KEY:PgXcoiT9bmYBrIUj6S7QHltf0w8KDzWaC5FMqLsx}\n  social:\n    wechat:\n      miniProgramAppId: wx18dc0ea8c6ca1d7d\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:false}\n\n# SpringDoc/Swagger配置（生产环境关闭）\nspringdoc:\n  api-docs:\n    enabled: false\n  swagger-ui:\n    enabled: false\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.pms.mapper\n\n# 生产环境日志级别配置\nlogging:\n  level:\n    root: ${LOG_LEVEL_ROOT:WARN}\n    org.springframework.web: ${LOG_LEVEL_WEB:WARN}\n    org.springframework.security: ${LOG_LEVEL_SECURITY:WARN}\n    org.springframework.cloud: ${LOG_LEVEL_CLOUD:WARN}\n    com.alibaba.nacos.client: ${LOG_LEVEL_NACOS:ERROR}\n    com.alibaba.cloud: ${LOG_LEVEL_ALIBABA_CLOUD:WARN}\n    com.ingot: ${LOG_LEVEL_APP:INFO}\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}', '5a283b17ce4386ec808e06cbf1086ca7', '2026-08-21 06:20:05', '2026-08-21 14:20:06', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (356, 860, 'in-service-member.yml', 'TEST_GROUP', '', 'spring:\n  datasource:\n    # 数据库连接URL配置\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_member}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\n# Ingot业务配置\ningot:\n  security:\n    event:\n      # 是否启用安全事件上报（总开关）\n      enabled: true\n      # 上报模式, local, remote\n      mode: local\n      # 上报方模块标识，写入中心库\n      sourceModule: MEMBER\n      # 按事件大类控制是否上报安全中心（仅 {@code mode=remote} 时生效）\n      categories:\n        # 认证类：登录成功/失败等（AUTH）\n        auth: true\n        # 账号类：锁定/解锁/创建等（ACCOUNT）\n        account: true\n        # 凭证类：改密/重置等（CREDENTIAL）\n        credential: true\n        # 访问防护类：网关封禁/限流违规等（ACCESS）；通常仅网关产生\n        access: true\n      # 过期事件物理删除策略\n      retention:\n        # 是否启用定时清理任务\n        enabled: true\n        # 保留天数\n        days: 30\n        # 单批 {@code DELETE ... LIMIT N} 条数，避免长事务与大锁\n        batchSize: 500\n        # 单次定时任务最多连续执行的批次数，防止清理洪峰占用连接过久\n        maxRounds: 100\n    account:\n      # local 或 remote\n      mode: local\n      lockout:\n        # 是否启用自动锁定账号\n        enabled: ${ACCOUNT_LOCKOUT_ENABLED:true}\n        # 失败次数阈值\n        maxAttempts: 5\n        # 锁定时长（分钟），0=永久锁定\n        lockDurationMinutes: 30\n        # 失败计数窗口期（分钟）\n        attemptWindowMinutes: 15\n        # 从第几次失败开始给出\"还剩几次将锁定\"的详细提示， 之前的失败一律返回通用\"账号或密码错误\"，避免暴露用户存在性。\n        # 例：maxAttempts=5，hintAfterAttempts=3 时：\n        # 第 1/2 次：通用提示\n        # 第 3 次：剩余 2 次\n        # 第 4 次：剩余 1 次\n        # 第 5 次：触发自动锁定，下次登录命中锁定分支\n        hintAfterAttempts: 3\n  oss:\n    minio:\n      url: ${MINIO_URL:http://ingot-cloud:9090}\n      accessKey: ${MINIO_ACCESS_KEY:2NPpKzxFQjyeMTQFEXA1}\n      secretKey: ${MINIO_SECRET_KEY:8SGAp7DhqZCQrYnU9Poyu888pQOB6w4SP2ILHbVU}\n  social:\n    wechat:\n      miniProgramAppId: wx18dc0ea8c6ca1d7d\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:true}  # 生产环境关闭\n\n# SpringDoc/Swagger配置（测试环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.member.mapper\n\n# 日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}\n', 'a0f44fb5684fc8ba1d090cd54916c64d', '2026-08-21 06:20:44', '2026-08-21 14:20:44', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (366, 861, 'in-service-member.yml', 'PROD_GROUP', '', 'spring:\n  datasource:\n    # 数据库连接URL配置\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_member}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\n# Ingot业务配置\ningot:\n  security:\n    event:\n      # 是否启用安全事件上报（总开关）\n      enabled: true\n      # 上报模式, local, remote\n      mode: local\n      # 上报方模块标识，写入中心库\n      sourceModule: MEMBER\n      # 按事件大类控制是否上报安全中心（仅 {@code mode=remote} 时生效）\n      categories:\n        # 认证类：登录成功/失败等（AUTH）\n        auth: true\n        # 账号类：锁定/解锁/创建等（ACCOUNT）\n        account: true\n        # 凭证类：改密/重置等（CREDENTIAL）\n        credential: true\n        # 访问防护类：网关封禁/限流违规等（ACCESS）；通常仅网关产生\n        access: true\n      # 过期事件物理删除策略\n      retention:\n        # 是否启用定时清理任务\n        enabled: true\n        # 保留天数\n        days: 30\n        # 单批 {@code DELETE ... LIMIT N} 条数，避免长事务与大锁\n        batchSize: 500\n        # 单次定时任务最多连续执行的批次数，防止清理洪峰占用连接过久\n        maxRounds: 100\n    account:\n      # local 或 remote\n      mode: local\n      lockout:\n        # 是否启用自动锁定账号\n        enabled: ${ACCOUNT_LOCKOUT_ENABLED:true}\n        # 失败次数阈值\n        maxAttempts: 5\n        # 锁定时长（分钟），0=永久锁定\n        lockDurationMinutes: 30\n        # 失败计数窗口期（分钟）\n        attemptWindowMinutes: 15\n        # 从第几次失败开始给出\"还剩几次将锁定\"的详细提示， 之前的失败一律返回通用\"账号或密码错误\"，避免暴露用户存在性。\n        # 例：maxAttempts=5，hintAfterAttempts=3 时：\n        # 第 1/2 次：通用提示\n        # 第 3 次：剩余 2 次\n        # 第 4 次：剩余 1 次\n        # 第 5 次：触发自动锁定，下次登录命中锁定分支\n        hintAfterAttempts: 3\n  oss:\n    minio:\n      url: ${MINIO_URL:http://ingot-cloud:9090}\n      accessKey: ${MINIO_ACCESS_KEY:2NPpKzxFQjyeMTQFEXA1}\n      secretKey: ${MINIO_SECRET_KEY:8SGAp7DhqZCQrYnU9Poyu888pQOB6w4SP2ILHbVU}\n  social:\n    wechat:\n      miniProgramAppId: wx18dc0ea8c6ca1d7d\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:false}\n\n# SpringDoc/Swagger配置（生产环境关闭）\nspringdoc:\n  api-docs:\n    enabled: false\n  swagger-ui:\n    enabled: false\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.member.mapper\n\n# 生产环境日志级别配置\nlogging:\n  level:\n    root: ${LOG_LEVEL_ROOT:WARN}\n    org.springframework.web: ${LOG_LEVEL_WEB:WARN}\n    org.springframework.security: ${LOG_LEVEL_SECURITY:WARN}\n    org.springframework.cloud: ${LOG_LEVEL_CLOUD:WARN}\n    com.alibaba.nacos.client: ${LOG_LEVEL_NACOS:ERROR}\n    com.alibaba.cloud: ${LOG_LEVEL_ALIBABA_CLOUD:WARN}\n    com.ingot: ${LOG_LEVEL_APP:INFO}\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}\n', 'a4e9370d03e545b7ada45f77fc88bd92', '2026-08-21 06:20:53', '2026-08-21 14:20:54', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
