6-08-21 07:00:17', '2026-08-21 15:00:17', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (365, 877, 'in-service-auth.yml', 'PROD_GROUP', '', 'spring:\n  mvc:\n    static-path-pattern: /static/**\n  thymeleaf:\n    cache: false\n    prefix: classpath:/templates/\n    suffix: .html\n    encoding: UTF-8\n    servlet:\n      content-type: text/html\n  datasource:\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_auth}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\ningot:\n  security:\n    oauth2:\n      auth:\n        loginFormUrl: https://login.ingotcloud.top/oauth2/challenge\n        issuer: http://${SERVICE_AUTH_HOST:localhost:5100}\n      resource:\n        publicUrls:\n          - /favicon.ico,GET\n          - /static/**,GET\n          - /logout,*\n          - /error,*\n    jwk:\n      key-lifetime: 90d\n      key-grace-period: 2h\n      max-active-keys: 3\n      cache-refresh-interval: 5m\n      master-key: ${AUTH_JWK_MASTER_KEY}\n      enable-encryption: true\n    access:\n      mode: local\n      loginFailure:\n        ip:\n          enabled: true\n          # 50次命中\n          maxAttempts: 50\n          # 时间窗口\n          windowMinutes: 1\n          # 锁定时间，秒\n          blockTtlSec: 3600\n          blockKeyType: \"IP\"\n        device:\n          enabled: false\n        client:\n          enabled: false\n        accountIp:\n          enabled: false\n    session:\n      # 会话存储不可用宽限期；超期一律拒绝，会话键不存在不在宽限范围内\n      store-unavailable-grace: 30s\n      # local：并发策略只读下面的 concurrency 段，不依赖安全中心（A9 场景）\n      mode: local\n      concurrency:\n        # 关闭后登录路径退回「只认 Client 的 UNIQUE / STANDARD」，紧急回退开关\n        enabled: true\n        # 0 = 不限并发；此时 Client 配置为 UNIQUE 仍按单会话处理\n        max-sessions: 0\n        # 会话数统计维度\n        dimension: USER_CLIENT\n        # 超限处置方式\n        overflow: KICK_OLDEST\n        # 管理用户（UserTypeEnum.ADMIN）是否强制单会话\n        admin-forbid-concurrent: false\n    event:\n      # 安全事件总开关；false 时不做任何上报\n      enabled: true\n      # center：会话撤销等 AUTH 事件 Feign 上报安全中心，Auth 本库不落 security_event\n      target: center\n      shadow-targets: []\n      # 写入 security_event.source_module\n      sourceModule: AUTH\n      categories:\n        auth: true\n      retention:\n        enabled: false\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:false}  # 生产环境关闭\n\n# SpringDoc/Swagger配置（生产环境关闭）\nspringdoc:\n  api-docs:\n    enabled: false\n  swagger-ui:\n    enabled: false\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.auth.mapper\n\n# 日志级别配置\nlogging:\n  level:\n    root: ${LOG_LEVEL_ROOT:WARN}\n    org.springframework.web: ${LOG_LEVEL_WEB:WARN}\n    org.springframework.security: ${LOG_LEVEL_SECURITY:WARN}\n    org.springframework.cloud: ${LOG_LEVEL_CLOUD:WARN}\n    com.alibaba.nacos.client: ${LOG_LEVEL_NACOS:ERROR}\n    com.alibaba.cloud: ${LOG_LEVEL_ALIBABA_CLOUD:WARN}\n    com.ingot: ${LOG_LEVEL_APP:INFO}\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}', '6a6c0453e2e3d2540678e950645983fb', '2026-08-21 07:00:34', '2026-08-21 15:00:34', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (358, 878, 'in-service-bff.yml', 'TEST_GROUP', '', 'ingot:\n  security:\n    oauth2:\n      resource:\n        public-urls:\n          - /crypto/public-keys,GET\n  bff:\n    client-id: ingot-bff\n    scope: system\n    # 管理用户:0, C端用户:1\n    user-type: \"0\"\n    session-ttl: 7200\n    redirect-uri: http://localhost:5400/bff/auth/callback\n    cookie:\n      # 开发环境不设置 domain（localhost 可用），生产环境设置顶级域名如 .ingotcloud.top\n      domain: ${BFF_COOKIE_DOMAIN:}\n      # 开发环境 false，生产必须 true\n      secure: ${BFF_COOKIE_SECURE:false}\n      same-site: ${BFF_COOKIE_SAME_SITE:Lax}\n    security:\n      # 客户端指纹校验，防止 Cookie 盗用\n      fingerprint-enabled: ${BFF_FINGERPRINT_ENABLED:true}\n      # 指纹模式: device（前端设备指纹，推荐）/ ip_ua（服务端 IP+UA，降级方案）\n      fingerprint-mode: ${BFF_FINGERPRINT_MODE:device}\n      # 信任的前端应用域名列表\n      allowed-frontends:\n        - http://localhost:1798\n        - http://localhost:5798\n      default-redirect-uri:\n        - http://localhost:5798\n\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n\n# 开发环境日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}', '6b18c36ead7aa85b808d561e5177eaba', '2026-08-21 07:01:36', '2026-08-21 15:01:36', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (368, 879, 'in-service-bff.yml', 'PROD_GROUP', '', 'ingot:\n  security:\n    oauth2:\n      resource:\n        public-urls:\n          - /crypto/public-keys,GET\n  bff:\n    client-id: ingot-bff\n    scope: system\n    # 管理用户:0, C端用户:1\n    user-type: \"0\"\n    session-ttl: 7200\n    redirect-uri: http://localhost:5400/bff/auth/callback\n    cookie:\n      # 开发环境不设置 domain（localhost 可用），生产环境设置顶级域名如 .ingotcloud.top\n      domain: ${BFF_COOKIE_DOMAIN:}\n      # 开发环境 false，生产必须 true\n      secure: ${BFF_COOKIE_SECURE:false}\n      same-site: ${BFF_COOKIE_SAME_SITE:Lax}\n    security:\n      # 客户端指纹校验，防止 Cookie 盗用\n      fingerprint-enabled: ${BFF_FINGERPRINT_ENABLED:true}\n      # 指纹模式: device（前端设备指纹，推荐）/ ip_ua（服务端 IP+UA，降级方案）\n      fingerprint-mode: ${BFF_FINGERPRINT_MODE:device}\n      # 信任的前端应用域名列表\n      allowed-frontends:\n        - http://localhost:1798\n        - http://localhost:5798\n      default-redirect-uri:\n        - http://localhost:5798\n\n# SpringDoc/Swagger配置（生产环境关闭）\nspringdoc:\n  api-docs:\n    enabled: false\n  swagger-ui:\n    enabled: false\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n\n# 生产环境日志级别配置\nlogging:\n  level:\n    root: ${LOG_LEVEL_ROOT:WARN}\n    org.springframework.web: ${LOG_LEVEL_WEB:WARN}\n    org.springframework.security: ${LOG_LEVEL_SECURITY:WARN}\n    org.springframework.cloud: ${LOG_LEVEL_CLOUD:WARN}\n    com.alibaba.nacos.client: ${LOG_LEVEL_NACOS:ERROR}\n    com.alibaba.cloud: ${LOG_LEVEL_ALIBABA_CLOUD:WARN}\n    com.ingot: ${LOG_LEVEL_APP:INFO}\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}', '3315d4de5f1457e8f32c46e79fbc18c0', '2026-08-21 07:01:45', '2026-08-21 15:01:45', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (343, 880, 'in-service-pms.yml', 'DEV_GROUP', '', 'spring:\n  datasource:\n    # 数据库连接URL配置\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_core}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\n# Ingot业务配置\ningot:\n  security:\n    account:\n      # local 或 remote\n      mode: local\n      lockout:\n        # 是否启用自动锁定账号\n        enabled: ${ACCOUNT_LOCKOUT_ENABLED:true}\n        # 失败次数阈值\n        maxAttempts: 5\n        # 锁定时长（分钟），0=永久锁定\n        lockDurationMinutes: 30\n        # 失败计数窗口期（分钟）\n        attemptWindowMinutes: 15\n        # 从第几次失败开始给出\"还剩几次将锁定\"的详细提示， 之前的失败一律返回通用\"账号或密码错误\"，避免暴露用户存在性。\n        # 例：maxAttempts=5，hintAfterAttempts=3 时：\n        # 第 1/2 次：通用提示\n        # 第 3 次：剩余 2 次\n        # 第 4 次：剩余 1 次\n        # 第 5 次：触发自动锁定，下次登录命中锁定分支\n        hintAfterAttempts: 3\n    account-lock-signal:\n      # 永久锁定时 uid/name key 的 TTL（天），默认 30。\n      permanent-lock-ttl-days: 30\n    event:\n      # 总开关。false：SecurityEventPublisher 不投递任何事件；true：由 target 决定落点。\n      enabled: true\n      # 主投递目标。\n      # local  = 写入本服务库 security_event（须 classpath 有 Store，通常配 primary-store: mysql）\n      # center = 经 Feign/Transport 上报 ingot-security 中心 admission\n      target: local\n      # target=local 且 classpath 存在多个 SecurityEventStore 时的主 Store id。\n      # 可选值：mysql（MySqlSecurityEventStore）、log（LogSecurityEventStore）。\n      # 仅有一个 Store Bean 时可省略，自动选中。\n      primary-store: mysql\n      # 次要投递目标（迁移 shadow 双写用）。稳定态留空 []。\n      # 元素取值：local | center；与主 target 去重后额外投递一份，shadow 失败不影响主链路 ack。\n      shadow-targets: []\n      # 上报方模块标识，写入 security_event.source_module。\n      # PMS 填 PMS，Member 填 MEMBER。\n      source-module: PMS\n      # 按事件大类过滤是否上报（enabled=true 时生效）；false 则该类别事件在 Publisher 层被丢弃。\n      categories:\n        # AUTH：登录成功/失败等认证类事件\n        auth: true\n        # ACCOUNT：锁定/解锁/创建/删除等账号类事件\n        account: true\n        # CREDENTIAL：改密/重置/强制改密等凭证类事件\n        credential: true\n        # ACCESS：网关封禁/限流违规等访问防护类；PMS/Member 通常不产生，可保持 true\n        access: true\n      # 投递层：BEST_EFFORT 走 memory，DURABLE 走 spool（两条独立管道，非溢出关系）。\n      delivery:\n        # BEST_EFFORT 有界内存队列参数；后台线程 security-recording-memory 攒批后投递。\n        memory:\n          # 内存队列容量；满时新 BEST_EFFORT 事件 DROPPED，不阻塞业务线程。\n          queue-capacity: 2048\n          # memory worker 单次 claim 条数上限。\n          batch-size: 32\n          # worker 攒批 poll 超时（毫秒）；队列空则等待该时长后再次 poll。\n          poll-timeout-ms: 100\n          # 进程关闭时等待 memory worker 排空队列的最长时间（毫秒）。\n          shutdown-timeout-ms: 5000\n        # DURABLE 本地 file spool；后台线程 security-recording-durable 持续 claim → 投递 → ack/nack 重试。\n        spool:\n          # spool 根目录（append-only segment 文件）。\n          directory: /ingot-data/security-recording/spool\n          # spool 目录总磁盘配额（如 1GB、512MB）。\n          max-bytes: 1GB\n          # 单个 segment 文件大小上限，达上限滚动新文件。\n          segment-bytes: 64MB\n          # 业务线程同步等待 spool 接纳 DURABLE 事件的最长时间（毫秒）；超时返回 FAILED（业务仍 fail-open）。\n          durable-ack-timeout-ms: 20\n          # durable worker 每次从 spool claim 的条数上限。\n          replay-batch-size: 32\n          # 投递失败 nack 后重试初始退避（毫秒）。\n          retry-initial-ms: 1000\n          # 重试退避上限（毫秒）。\n          retry-max-ms: 60000\n      # MySQL SecurityEventStore 写入侧参数（target=local 且 primary-store=mysql 时生效）。\n      mysql:\n        # 并发写入信号量许可数；默认 1，避免 canonical security_event 热点写冲突。\n        max-concurrent-writes: 1\n        # 单批 INSERT 事务超时（秒）。\n        transaction-timeout-seconds: 5\n      # canonical security_event 过期物理删除（PurgeCanonicalSecurityEventTask，cron 0 30 3 * * ?）。\n      retention:\n        # 是否启用定时清理；false 等同永久保留。\n        enabled: true\n        # 保留天数；早于 now-days 的记录被删除；0 表示永久保留。\n        days: 30\n        # 单批 DELETE LIMIT 条数，避免长事务与大锁。\n        batch-size: 500\n        # 单次定时任务最多连续执行的批次数。\n        max-rounds: 100\n        # 单次 retention 任务最大执行时长（秒），超时停止本轮。\n        max-duration-seconds: 30\n        # memory/spool 队列使用率超过该百分比时，retention 让步暂停删除。\n        yield-queue-usage-percent: 50\n      # 按 eventType 覆盖默认优先级（BEST_EFFORT | DURABLE），支持 Nacos 热刷新。\n      # 未配置时使用 DefaultPriorityClassifier 内置默认表；示例：\n      # LOGIN_FAILURE: DURABLE\n      priority-overrides: {}\n  oss:\n    minio:\n      url: ${MINIO_URL:http://ingot-cloud:9090}\n      accessKey: ${MINIO_ACCESS_KEY:2NPpKzxFQjyeMTQFEXA1}\n      secretKey: ${MINIO_SECRET_KEY:8SGAp7DhqZCQrYnU9Poyu888pQOB6w4SP2ILHbVU}\n    rustfs:\n      url: ${RUSTFS_URL:http://ingot-cloud:19000}\n      accessKey: ${RUSTFS_ACCESS_KEY:7eYdiTxLbcpsfaNoKSQ0}\n      secretKey: ${RUSTFS_SECRET_KEY:PgXcoiT9bmYBrIUj6S7QHltf0w8KDzWaC5FMqLsx}\n  social:\n    wechat:\n      miniProgramAppId: wx18dc0ea8c6ca1d7d\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:true}  # 生产环境关闭\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.pms.mapper\n\n# 开发环境日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}\n', '5bfc4bc70cfe4add9515e62b5e600112', '2026-08-21 07:17:05', '2026-08-21 15:17:05', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (353, 881, 'in-service-pms.yml', 'TEST_GROUP', '', 'spring:\n  datasource:\n    # 数据库连接URL配置\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_core}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\n# Ingot业务配置\ningot:\n  security:\n    account:\n      # local 或 remote\n      mode: local\n      lockout:\n        # 是否启用自动锁定账号\n        enabled: ${ACCOUNT_LOCKOUT_ENABLED:true}\n        # 失败次数阈值\n        maxAttempts: 5\n        # 锁定时长（分钟），0=永久锁定\n        lockDurationMinutes: 30\n        # 失败计数窗口期（分钟）\n        attemptWindowMinutes: 15\n        # 从第几次失败开始给出\"还剩几次将锁定\"的详细提示， 之前的失败一律返回通用\"账号或密码错误\"，避免暴露用户存在性。\n        # 例：maxAttempts=5，hintAfterAttempts=3 时：\n        # 第 1/2 次：通用提示\n        # 第 3 次：剩余 2 次\n        # 第 4 次：剩余 1 次\n        # 第 5 次：触发自动锁定，下次登录命中锁定分支\n        hintAfterAttempts: 3\n    account-lock-signal:\n      # 永久锁定时 uid/name key 的 TTL（天），默认 30。\n      permanent-lock-ttl-days: 30\n    event:\n      # 总开关。false：SecurityEventPublisher 不投递任何事件；true：由 target 决定落点。\n      enabled: true\n      # 主投递目标。\n      # local  = 写入本服务库 security_event（须 classpath 有 Store，通常配 primary-store: mysql）\n      # center = 经 Feign/Transport 上报 ingot-security 中心 admission\n      target: local\n      # target=local 且 classpath 存在多个 SecurityEventStore 时的主 Store id。\n      # 可选值：mysql（MySqlSecurityEventStore）、log（LogSecurityEventStore）。\n      # 仅有一个 Store Bean 时可省略，自动选中。\n      primary-store: mysql\n      # 次要投递目标（迁移 shadow 双写用）。稳定态留空 []。\n      # 元素取值：local | center；与主 target 去重后额外投递一份，shadow 失败不影响主链路 ack。\n      shadow-targets: []\n      # 上报方模块标识，写入 security_event.source_module。\n      # PMS 填 PMS，Member 填 MEMBER。\n      source-module: PMS\n      # 按事件大类过滤是否上报（enabled=true 时生效）；false 则该类别事件在 Publisher 层被丢弃。\n      categories:\n        # AUTH：登录成功/失败等认证类事件\n        auth: true\n        # ACCOUNT：锁定/解锁/创建/删除等账号类事件\n        account: true\n        # CREDENTIAL：改密/重置/强制改密等凭证类事件\n        credential: true\n        # ACCESS：网关封禁/限流违规等访问防护类；PMS/Member 通常不产生，可保持 true\n        access: true\n      # 投递层：BEST_EFFORT 走 memory，DURABLE 走 spool（两条独立管道，非溢出关系）。\n      delivery:\n        # BEST_EFFORT 有界内存队列参数；后台线程 security-recording-memory 攒批后投递。\n        memory:\n          # 内存队列容量；满时新 BEST_EFFORT 事件 DROPPED，不阻塞业务线程。\n          queue-capacity: 2048\n          # memory worker 单次 claim 条数上限。\n          batch-size: 32\n          # worker 攒批 poll 超时（毫秒）；队列空则等待该时长后再次 poll。\n          poll-timeout-ms: 100\n          # 进程关闭时等待 memory worker 排空队列的最长时间（毫秒）。\n          shutdown-timeout-ms: 5000\n        # DURABLE 本地 file spool；后台线程 security-recording-durable 持续 claim → 投递 → ack/nack 重试。\n        spool:\n          # spool 根目录（append-only segment 文件）。\n          directory: /ingot-data/security-recording/spool\n          # spool 目录总磁盘配额（如 1GB、512MB）。\n          max-bytes: 1GB\n          # 单个 segment 文件大小上限，达上限滚动新文件。\n          segment-bytes: 64MB\n          # 业务线程同步等待 spool 接纳 DURABLE 事件的最长时间（毫秒）；超时返回 FAILED（业务仍 fail-open）。\n          durable-ack-timeout-ms: 20\n          # durable worker 每次从 spool claim 的条数上限。\n          replay-batch-size: 32\n          # 投递失败 nack 后重试初始退避（毫秒）。\n          retry-initial-ms: 1000\n          # 重试退避上限（毫秒）。\n          retry-max-ms: 60000\n      # MySQL SecurityEventStore 写入侧参数（target=local 且 primary-store=mysql 时生效）。\n      mysql:\n        # 并发写入信号量许可数；默认 1，避免 canonical security_event 热点写冲突。\n        max-concurrent-writes: 1\n        # 单批 INSERT 事务超时（秒）。\n        transaction-timeout-seconds: 5\n      # canonical security_event 过期物理删除（PurgeCanonicalSecurityEventTask，cron 0 30 3 * * ?）。\n      retention:\n        # 是否启用定时清理；false 等同永久保留。\n        enabled: true\n        # 保留天数；早于 now-days 的记录被删除；0 表示永久保留。\n        days: 30\n        # 单批 DELETE LIMIT 条数，避免长事务与大锁。\n        batch-size: 500\n        # 单次定时任务最多连续执行的批次数。\n        max-rounds: 100\n        # 单次 retention 任务最大执行时长（秒），超时停止本轮。\n        max-duration-seconds: 30\n        # memory/spool 队列使用率超过该百分比时，retention 让步暂停删除。\n        yield-queue-usage-percent: 50\n      # 按 eventType 覆盖默认优先级（BEST_EFFORT | DURABLE），支持 Nacos 热刷新。\n      # 未配置时使用 DefaultPriorityClassifier 内置默认表；示例：\n      # LOGIN_FAILURE: DURABLE\n      priority-overrides: {}\n  oss:\n    minio:\n      url: ${MINIO_URL:http://ingot-cloud:9090}\n      accessKey: ${MINIO_ACCESS_KEY:2NPpKzxFQjyeMTQFEXA1}\n      secretKey: ${MINIO_SECRET_KEY:8SGAp7DhqZCQrYnU9Poyu888pQOB6w4SP2ILHbVU}\n  social:\n    wechat:\n      miniProgramAppId: wx18dc0ea8c6ca1d7d\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:true}  # 生产环境关闭\n\n# SpringDoc/Swagger配置（测试环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.pms.mapper\n\n# 日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}\n', 'd7967fe370dbede84068639dbb8155d0', '2026-08-21 07:20:19', '2026-08-21 15:20:20', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (363, 882, 'in-service-pms.yml', 'PROD_GROUP', '', 'spring:\n  datasource:\n    # 数据库连接URL配置\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_core}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\n# 业务配置\ningot:\n  security:\n    account:\n      # local 或 remote\n      mode: local\n      lockout:\n        # 是否启用自动锁定账号\n        enabled: ${ACCOUNT_LOCKOUT_ENABLED:true}\n        # 失败次数阈值\n        maxAttempts: 5\n        # 锁定时长（分钟），0=永久锁定\n        lockDurationMinutes: 30\n        # 失败计数窗口期（分钟）\n        attemptWindowMinutes: 15\n        # 从第几次失败开始给出\"还剩几次将锁定\"的详细提示， 之前的失败一律返回通用\"账号或密码错误\"，避免暴露用户存在性。\n        # 例：maxAttempts=5，hintAfterAttempts=3 时：\n        # 第 1/2 次：通用提示\n        # 第 3 次：剩余 2 次\n        # 第 4 次：剩余 1 次\n        # 第 5 次：触发自动锁定，下次登录命中锁定分支\n        hintAfterAttempts: 3\n    account-lock-signal:\n      # 永久锁定时 uid/name key 的 TTL（天），默认 30。\n      permanent-lock-ttl-days: 30\n    event:\n      # 总开关。false：SecurityEventPublisher 不投递任何事件；true：由 target 决定落点。\n      enabled: true\n      # 主投递目标。\n      # local  = 写入本服务库 security_event（须 classpath 有 Store，通常配 primary-store: mysql）\n      # center = 经 Feign/Transport 上报 ingot-security 中心 admission\n      target: local\n      # target=local 且 classpath 存在多个 SecurityEventStore 时的主 Store id。\n      # 可选值：mysql（MySqlSecurityEventStore）、log（LogSecurityEventStore）。\n      # 仅有一个 Store Bean 时可省略，自动选中。\n      primary-store: mysql\n      # 次要投递目标（迁移 shadow 双写用）。稳定态留空 []。\n      # 元素取值：local | center；与主 target 去重后额外投递一份，shadow 失败不影响主链路 ack。\n      shadow-targets: []\n      # 上报方模块标识，写入 security_event.source_module。\n      # PMS 填 PMS，Member 填 MEMBER。\n      source-module: PMS\n      # 按事件大类过滤是否上报（enabled=true 时生效）；false 则该类别事件在 Publisher 层被丢弃。\n      categories:\n        # AUTH：登录成功/失败等认证类事件\n        auth: true\n        # ACCOUNT：锁定/解锁/创建/删除等账号类事件\n        account: true\n        # CREDENTIAL：改密/重置/强制改密等凭证类事件\n        credential: true\n        # ACCESS：网关封禁/限流违规等访问防护类；PMS/Member 通常不产生，可保持 true\n        access: true\n      # 投递层：BEST_EFFORT 走 memory，DURABLE 走 spool（两条独立管道，非溢出关系）。\n      delivery:\n        # BEST_EFFORT 有界内存队列参数；后台线程 security-recording-memory 攒批后投递。\n        memory:\n          # 内存队列容量；满时新 BEST_EFFORT 事件 DROPPED，不阻塞业务线程。\n          queue-capacity: 2048\n          # memory worker 单次 claim 条数上限。\n          batch-size: 32\n          # worker 攒批 poll 超时（毫秒）；队列空则等待该时长后再次 poll。\n          poll-timeout-ms: 100\n          # 进程关闭时等待 memory worker 排空队列的最长时间（毫秒）。\n          shutdown-timeout-ms: 5000\n        # DURABLE 本地 file spool；后台线程 security-recording-durable 持续 claim → 投递 → ack/nack 重试。\n        spool:\n          # spool 根目录（append-only segment 文件）。\n          directory: /ingot-data/security-recording/spool\n          # spool 目录总磁盘配额（如 1GB、512MB）。\n          max-bytes: 1GB\n          # 单个 segment 文件大小上限，达上限滚动新文件。\n          segment-bytes: 64MB\n          # 业务线程同步等待 spool 接纳 DURABLE 事件的最长时间（毫秒）；超时返回 FAILED（业务仍 fail-open）。\n          durable-ack-timeout-ms: 20\n          # durable worker 每次从 spool claim 的条数上限。\n          replay-batch-size: 32\n          # 投递失败 nack 后重试初始退避（毫秒）。\n          retry-initial-ms: 1000\n          # 重试退避上限（毫秒）。\n          retry-max-ms: 60000\n      # MySQL SecurityEventStore 写入侧参数（target=local 且 primary-store=mysql 时生效）。\n      mysql:\n        # 并发写入信号量许可数；默认 1，避免 canonical security_event 热点写冲突。\n        max-concurrent-writes: 1\n        # 单批 INSERT 事务超时（秒）。\n        transaction-timeout-seconds: 5\n      # canonical security_event 过期物理删除（PurgeCanonicalSecurityEventTask，cron 0 30 3 * * ?）。\n      retention:\n        # 是否启用定时清理；false 等同永久保留。\n        enabled: true\n        # 保留天数；早于 now-days 的记录被删除；0 表示永久保留。\n        days: 30\n        # 单批 DELETE LIMIT 条数，避免长事务与大锁。\n        batch-size: 500\n        # 单次定时任务最多连续执行的批次数。\n        max-rounds: 100\n        # 单次 retention 任务最大执行时长（秒），超时停止本轮。\n        max-duration-seconds: 30\n        # memory/spool 队列使用率超过该百分比时，retention 让步暂停删除。\n        yield-queue-usage-percent: 50\n      # 按 eventType 覆盖默认优先级（BEST_EFFORT | DURABLE），支持 Nacos 热刷新。\n      # 未配置时使用 DefaultPriorityClassifier 内置默认表；示例：\n      # LOGIN_FAILURE: DURABLE\n      priority-overrides: {}\n  oss:\n    minio:\n      url: ${MINIO_URL:http://ingot-cloud:9090}\n      accessKey: ${MINIO_ACCESS_KEY:2NPpKzxFQjyeMTQFEXA1}\n      secretKey: ${MINIO_SECRET_KEY:8SGAp7DhqZCQrYnU9Poyu888pQOB6w4SP2ILHbVU}\n    rustfs:\n      url: ${RUSTFS_URL:http://ingot-cloud:19000}\n      accessKey: ${RUSTFS_ACCESS_KEY:7eYdiTxLbcpsfaNoKSQ0}\n      secretKey: ${RUSTFS_SECRET_KEY:PgXcoiT9bmYBrIUj6S7QHltf0w8KDzWaC5FMqLsx}\n  social:\n    wechat:\n      miniProgramAppId: wx18dc0ea8c6ca1d7d\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:false}\n\n# SpringDoc/Swagger配置（生产环境关闭）\nspringdoc:\n  api-docs:\n    enabled: false\n  swagger-ui:\n    enabled: false\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.pms.mapper\n\n# 生产环境日志级别配置\nlogging:\n  level:\n    root: ${LOG_LEVEL_ROOT:WARN}\n    org.springframework.web: ${LOG_LEVEL_WEB:WARN}\n    org.springframework.security: ${LOG_LEVEL_SECURITY:WARN}\n    org.springframework.cloud: ${LOG_LEVEL_CLOUD:WARN}\n    com.alibaba.nacos.client: ${LOG_LEVEL_NACOS:ERROR}\n    com.alibaba.cloud: ${LOG_LEVEL_ALIBABA_CLOUD:WARN}\n    com.ingot: ${LOG_LEVEL_APP:INFO}\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}', 'ac63035c4e79aaabe8ed2c9935a8967f', '2026-08-21 07:20:28', '2026-08-21 15:20:28', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (346, 883, 'in-service-member.yml', 'DEV_GROUP', '', 'spring:\n  datasource:\n    # 数据库连接URL配置\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_member}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\n# Ingot业务配置\ningot:\n  security:\n    account:\n      # local 或 remote\n      mode: local\n      lockout:\n        # 是否启用自动锁定账号\n        enabled: ${ACCOUNT_LOCKOUT_ENABLED:true}\n        # 失败次数阈值\n        maxAttempts: 5\n        # 锁定时长（分钟），0=永久锁定\n        lockDurationMinutes: 30\n        # 失败计数窗口期（分钟）\n        attemptWindowMinutes: 15\n        # 从第几次失败开始给出\"还剩几次将锁定\"的详细提示， 之前的失败一律返回通用\"账号或密码错误\"，避免暴露用户存在性。\n        # 例：maxAttempts=5，hintAfterAttempts=3 时：\n        # 第 1/2 次：通用提示\n        # 第 3 次：剩余 2 次\n        # 第 4 次：剩余 1 次\n        # 第 5 次：触发自动锁定，下次登录命中锁定分支\n        hintAfterAttempts: 3\n    event:\n      # 总开关。false：SecurityEventPublisher 不投递任何事件；true：由 target 决定落点。\n      enabled: true\n      # 主投递目标。\n      # local  = 写入本服务库 security_event（须 classpath 有 Store，通常配 primary-store: mysql）\n      # center = 经 Feign/Transport 上报 ingot-security 中心 admission\n      target: local\n      # target=local 且 classpath 存在多个 SecurityEventStore 时的主 Store id。\n      # 可选值：mysql（MySqlSecurityEventStore）、log（LogSecurityEventStore）。\n      # 仅有一个 Store Bean 时可省略，自动选中。\n      primary-store: mysql\n      # 次要投递目标（迁移 shadow 双写用）。稳定态留空 []。\n      # 元素取值：local | center；与主 target 去重后额外投递一份，shadow 失败不影响主链路 ack。\n      shadow-targets: []\n      # 上报方模块标识，写入 security_event.source_module。\n      # PMS 填 PMS，Member 填 MEMBER。\n      source-module: MEMBER\n      # 按事件大类过滤是否上报（enabled=true 时生效）；false 则该类别事件在 Publisher 层被丢弃。\n      categories:\n        # AUTH：登录成功/失败等认证类事件\n        auth: true\n        # ACCOUNT：锁定/解锁/创建/删除等账号类事件\n        account: true\n        # CREDENTIAL：改密/重置/强制改密等凭证类事件\n        credential: true\n        # ACCESS：网关封禁/限流违规等访问防护类；PMS/Member 通常不产生，可保持 true\n        access: true\n      # 投递层：BEST_EFFORT 走 memory，DURABLE 走 spool（两条独立管道，非溢出关系）。\n      delivery:\n        # BEST_EFFORT 有界内存队列参数；后台线程 security-recording-memory 攒批后投递。\n        memory:\n          # 内存队列容量；满时新 BEST_EFFORT 事件 DROPPED，不阻塞业务线程。\n          queue-capacity: 2048\n          # memory worker 单次 claim 条数上限。\n          batch-size: 32\n          # worker 攒批 poll 超时（毫秒）；队列空则等待该时长后再次 poll。\n          poll-timeout-ms: 100\n          # 进程关闭时等待 memory worker 排空队列的最长时间（毫秒）。\n          shutdown-timeout-ms: 5000\n        # DURABLE 本地 file spool；后台线程 security-recording-durable 持续 claim → 投递 → ack/nack 重试。\n        spool:\n          # spool 根目录（append-only segment 文件）。\n          directory: ./logs/security-recording/spool\n          # spool 目录总磁盘配额（如 1GB、512MB）。\n          max-bytes: 1GB\n          # 单个 segment 文件大小上限，达上限滚动新文件。\n          segment-bytes: 64MB\n          # 业务线程同步等待 spool 接纳 DURABLE 事件的最长时间（毫秒）；超时返回 FAILED（业务仍 fail-open）。\n          durable-ack-timeout-ms: 20\n          # durable worker 每次从 spool claim 的条数上限。\n          replay-batch-size: 32\n          # 投递失败 nack 后重试初始退避（毫秒）。\n          retry-initial-ms: 1000\n          # 重试退避上限（毫秒）。\n          retry-max-ms: 60000\n      # MySQL SecurityEventStore 写入侧参数（target=local 且 primary-store=mysql 时生效）。\n      mysql:\n        # 并发写入信号量许可数；默认 1，避免 canonical security_event 热点写冲突。\n        max-concurrent-writes: 1\n        # 单批 INSERT 事务超时（秒）。\n        transaction-timeout-seconds: 5\n      # canonical security_event 过期物理删除（PurgeCanonicalSecurityEventTask，cron 0 30 3 * * ?）。\n      retention:\n        # 是否启用定时清理；false 等同永久保留。\n        enabled: true\n        # 保留天数；早于 now-days 的记录被删除；0 表示永久保留。\n        days: 30\n        # 单批 DELETE LIMIT 条数，避免长事务与大锁。\n        batch-size: 500\n        # 单次定时任务最多连续执行的批次数。\n        max-rounds: 100\n        # 单次 retention 任务最大执行时长（秒），超时停止本轮。\n        max-duration-seconds: 30\n        # memory/spool 队列使用率超过该百分比时，retention 让步暂停删除。\n        yield-queue-usage-percent: 50\n      # 按 eventType 覆盖默认优先级（BEST_EFFORT | DURABLE），支持 Nacos 热刷新。\n      # 未配置时使用 DefaultPriorityClassifier 内置默认表；示例：\n      # LOGIN_FAILURE: DURABLE\n      priority-overrides: {}\n  oss:\n    minio:\n      url: ${MINIO_URL:http://ingot-cloud:9090}\n      accessKey: ${MINIO_ACCESS_KEY:2NPpKzxFQjyeMTQFEXA1}\n      secretKey: ${MINIO_SECRET_KEY:8SGAp7DhqZCQrYnU9Poyu888pQOB6w4SP2ILHbVU}\n  social:\n    wechat:\n      miniProgramAppId: wx18dc0ea8c6ca1d7d\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:true}  # 生产环境关闭\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.member.mapper\n\n# 开发环境日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}\n', 'f52057639aa1e1c2fd13df1e49fa3af2', '2026-08-21 07:20:51', '2026-08-21 15:20:51', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (356, 884, 'in-service-member.yml', 'TEST_GROUP', '', 'spring:\n  datasource:\n    # 数据库连接URL配置\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_member}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\n# Ingot业务配置\ningot:\n  security:\n    account:\n      # local 或 remote\n      mode: local\n      lockout:\n        # 是否启用自动锁定账号\n        enabled: ${ACCOUNT_LOCKOUT_ENABLED:true}\n        # 失败次数阈值\n        maxAttempts: 5\n        # 锁定时长（分钟），0=永久锁定\n        lockDurationMinutes: 30\n        # 失败计数窗口期（分钟）\n        attemptWindowMinutes: 15\n        # 从第几次失败开始给出\"还剩几次将锁定\"的详细提示， 之前的失败一律返回通用\"账号或密码错误\"，避免暴露用户存在性。\n        # 例：maxAttempts=5，hintAfterAttempts=3 时：\n        # 第 1/2 次：通用提示\n        # 第 3 次：剩余 2 次\n        # 第 4 次：剩余 1 次\n        # 第 5 次：触发自动锁定，下次登录命中锁定分支\n        hintAfterAttempts: 3\n    event:\n      # 总开关。false：SecurityEventPublisher 不投递任何事件；true：由 target 决定落点。\n      enabled: true\n      # 主投递目标。\n      # local  = 写入本服务库 security_event（须 classpath 有 Store，通常配 primary-store: mysql）\n      # center = 经 Feign/Transport 上报 ingot-security 中心 admission\n      target: local\n      # target=local 且 classpath 存在多个 SecurityEventStore 时的主 Store id。\n      # 可选值：mysql（MySqlSecurityEventStore）、log（LogSecurityEventStore）。\n      # 仅有一个 Store Bea