5dd518dbbcb', '2026-08-22 09:51:15', '2026-08-22 17:51:15', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (345, 900, 'in-service-auth.yml', 'DEV_GROUP', '', 'spring:\n  mvc:\n    static-path-pattern: /static/**\n  thymeleaf:\n    cache: false\n    prefix: classpath:/templates/\n    suffix: .html\n    encoding: UTF-8\n    servlet:\n      content-type: text/html\n  datasource:\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_auth}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\ningot:\n  security:\n    oauth2:\n      auth:\n        loginFormUrl: https://login.ingotcloud.top/oauth2/challenge\n        issuer: http://${SERVICE_AUTH_HOST:localhost:5100}\n      resource:\n        publicUrls:\n          - /favicon.ico,GET\n          - /static/**,GET\n          - /logout,*\n          - /error,*\n    jwk:\n      key-lifetime: 90d\n      key-grace-period: 2h\n      max-active-keys: 3\n      cache-refresh-interval: 5m\n      master-key: ${AUTH_JWK_MASTER_KEY:a7A7FJ9KdQutfjbQh8sZSt2kcNtl/JUkmEI73aCR080=}\n      enable-encryption: true\n    access:\n      mode: local\n      loginFailure:\n        ip:\n          enabled: true\n          # 50次命中\n          maxAttempts: 1\n          # 时间窗口\n          windowMinutes: 1\n          # 锁定时间，秒\n          blockTtlSec: 3600\n          blockKeyType: \"IP\"\n        device:\n          enabled: false\n        client:\n          enabled: false\n        accountIp:\n          enabled: false\n    session:\n      # 会话存储不可用宽限期；超期一律拒绝，会话键不存在不在宽限范围内\n      store-unavailable-grace: 30s\n      # local：并发策略只读下面的 concurrency 段，不依赖安全中心（A9 场景）\n      mode: local\n      concurrency:\n        # 关闭后登录路径退回「只认 Client 的 UNIQUE / STANDARD」，紧急回退开关\n        enabled: true\n        # 0 = 不限并发；此时 Client 配置为 UNIQUE 仍按单会话处理\n        max-sessions: 0\n        # 会话数统计维度\n        dimension: USER_CLIENT\n        # 超限处置方式\n        overflow: KICK_OLDEST\n        # 管理用户（UserTypeEnum.ADMIN）是否强制单会话\n        admin-forbid-concurrent: false\n    event:\n      # 安全事件总开关；false 时不做任何上报\n      enabled: true\n      # center：会话撤销等 AUTH 事件 Feign 上报安全中心，Auth 本库不落 security_event\n      target: center\n      shadow-targets: []\n      # 写入 security_event.source_module\n      sourceModule: AUTH\n      # 安全事件大类上报开关\n      categories:\n        auth: true\n        account: false\n        credential: false\n        access: false\n      retention:\n        enabled: false\n\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:true}  # 生产环境关闭\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.auth.mapper\n\n# 日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}', '534c11945de445b6b086ca1a68872b03', '2026-08-22 09:51:28', '2026-08-22 17:51:28', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (350, 901, 'in-security-policy.yml', 'DEV_GROUP', '', 'ingot:\n  security:\n    ignoreTenantValidateRoleCodeList:\n      - role_admin\n    \n    # 重放配置\n    replay:\n      enabled: true\n      window: 5m\n      clock-skew: 5m\n      key-prefix: \"replay:\"\n      fail-open: false\n    \n    # 凭证配置\n    credential:\n      cache:\n        # 是否启用 L1 Caffeine\n        l1-enabled: true\n        # L1 TTL（默认 5 分钟）\n        l1-ttl: 5m\n        # L1 最大条目数（实际单 key，但保留容量）\n        l1-maximum-size: 16\n        # 是否启用 L2 Redis\n        l2-enabled: true\n        # L2 TTL（默认 30 分钟）\n        l2-ttl: 30m\n        # L2 Redis key 前缀\n        l2-key-prefix: \"in:credential:configs:\"\n        # 是否启用跨节点失效订阅\n        invalidation-enabled: true\n      policy:\n        # 策略加载模式：local（本地配置）或 remote（远程加载）\n        mode: ${CREDENTIAL_MODE:local}\n\n        # 本地策略配置\n        strength:\n          # 是否启用\n          enabled: true\n          # 最小长度\n          min-length: 8\n          # 最大长度\n          max-length: 32\n          # 是否要求大写字母\n          require-uppercase: false\n          # 是否要求小写字母\n          require-lowercase: false\n          # 是否要求数字\n          require-digit: false\n          # 是否要求特殊字符\n          requireSpecialChar: false\n          # 特殊字符集合\n          specialChars: \"!@#$%^&*()_+-=[]{}|;:,.<>?\"\n          # 禁止的模式\n          forbiddenPatterns:\n            - \"password\"\n            - \"123456\"\n            - \"admin\"\n            - \"qwerty\"\n          # 禁止包含用户属性\n          forbidUserAttributes: false\n\n        history:\n          # 是否启用\n          enabled: true\n          # 检查最近N次密码\n          check-count: 5\n\n        expiration:\n          # 是否启用 \n          enabled: false\n          # 最大有效天数\n          max-days: 90\n          # 提前警告天数\n          warningDaysBefore: 7\n          # 宽限登录次数\n          graceLoginCount: 3\n\n        initialPassword:\n          # 初始密码生成方式：RANDOM-随机生成；FIXED-统一默认密码\n          generation: RANDOM\n          # 随机初始密码长度（generation=RANDOM 时生效）\n          length: 10\n          # 统一默认密码（generation=FIXED 时生效）\n          fixedPassword: In@123456\n          # 初始密码有效小时数；0 表示不限制。超过后视为初始密码失效，需重新重置。\n          validHours: 72\n          # 用后失效：初始密码修改成功后即失效（依赖 mustChangePwd/force_change 清除，默认 true）\n          oneTime: true\n          # 首次登录是否强制修改密码\n          forceChangeOnFirstLogin: true\n', 'c79b65467e70f351c4b2b861c8f8dbc4', '2026-08-24 01:28:31', '2026-08-24 09:28:31', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\",\"c_desc\":\"密码策略，登录策略，会话策略，账号策略等\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (350, 902, 'in-security-policy.yml', 'DEV_GROUP', '', 'ingot:\n  security:\n    ignoreTenantValidateRoleCodeList:\n      - role_admin\n    \n    # 重放配置\n    replay:\n      enabled: true\n      window: 5m\n      clock-skew: 5m\n      key-prefix: \"replay:\"\n      fail-open: false\n    \n    # 凭证配置\n    credential:\n      cache:\n        # 是否启用 L1 Caffeine\n        l1-enabled: true\n        # L1 TTL（默认 5 分钟）\n        l1-ttl: 5m\n        # L1 最大条目数（实际单 key，但保留容量）\n        l1-maximum-size: 16\n        # 是否启用 L2 Redis\n        l2-enabled: true\n        # L2 TTL（默认 30 分钟）\n        l2-ttl: 30m\n        # L2 Redis key 前缀\n        l2-key-prefix: \"in:credential:configs:\"\n        # 是否启用跨节点失效订阅\n        invalidation-enabled: true\n      policy:\n        # 策略加载模式：local（本地配置）或 remote（远程加载）\n        mode: ${CREDENTIAL_MODE:local}\n\n        # 本地策略配置\n        strength:\n          # 是否启用\n          enabled: true\n          # 最小长度\n          min-length: 7\n          # 最大长度\n          max-length: 32\n          # 是否要求大写字母\n          require-uppercase: false\n          # 是否要求小写字母\n          require-lowercase: false\n          # 是否要求数字\n          require-digit: false\n          # 是否要求特殊字符\n          requireSpecialChar: false\n          # 特殊字符集合\n          specialChars: \"!@#$%^&*()_+-=[]{}|;:,.<>?\"\n          # 禁止的模式\n          forbiddenPatterns:\n            - \"password\"\n            - \"123456\"\n            - \"admin\"\n            - \"qwerty\"\n          # 禁止包含用户属性\n          forbidUserAttributes: false\n\n        history:\n          # 是否启用\n          enabled: true\n          # 检查最近N次密码\n          check-count: 5\n\n        expiration:\n          # 是否启用 \n          enabled: false\n          # 最大有效天数\n          max-days: 90\n          # 提前警告天数\n          warningDaysBefore: 7\n          # 宽限登录次数\n          graceLoginCount: 3\n\n        initialPassword:\n          # 初始密码生成方式：RANDOM-随机生成；FIXED-统一默认密码\n          generation: RANDOM\n          # 随机初始密码长度（generation=RANDOM 时生效）\n          length: 10\n          # 统一默认密码（generation=FIXED 时生效）\n          fixedPassword: In@123456\n          # 初始密码有效小时数；0 表示不限制。超过后视为初始密码失效，需重新重置。\n          validHours: 72\n          # 用后失效：初始密码修改成功后即失效（依赖 mustChangePwd/force_change 清除，默认 true）\n          oneTime: true\n          # 首次登录是否强制修改密码\n          forceChangeOnFirstLogin: true\n', 'e29b65b6fd8c472b1701196e37d505d5', '2026-08-24 01:28:52', '2026-08-24 09:28:52', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\",\"c_desc\":\"密码策略，登录策略，会话策略，账号策略等\"}');
