警告天数\n          warningDaysBefore: 7\n          # 宽限登录次数\n          graceLoginCount: 3\n\n        initialPassword:\n          # 初始密码生成方式：RANDOM-随机生成；FIXED-统一默认密码\n          generation: RANDOM\n          # 随机初始密码长度（generation=RANDOM 时生效）\n          length: 10\n          # 统一默认密码（generation=FIXED 时生效）\n          fixedPassword: In@123456\n          # 初始密码有效小时数；0 表示不限制。超过后视为初始密码失效，需重新重置。\n          validHours: 72\n          # 用后失效：初始密码修改成功后即失效（依赖 mustChangePwd/force_change 清除，默认 true）\n          oneTime: true\n          # 首次登录是否强制修改密码\n          forceChangeOnFirstLogin: true\n', '09990a85505926a2eb526568460b97c6', '2026-08-24 08:58:16', '2026-08-24 16:58:16', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\",\"c_desc\":\"密码策略，登录策略，会话策略，账号策略等\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (343, 904, 'in-service-pms.yml', 'DEV_GROUP', '', 'spring:\n  datasource:\n    # 数据库连接URL配置\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_core}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\n# Ingot业务配置\ningot:\n  security:\n    account:\n      # local 或 remote\n      mode: local\n      lockout:\n        # 是否启用自动锁定账号\n        enabled: ${ACCOUNT_LOCKOUT_ENABLED:false}\n        # 失败次数阈值\n        maxAttempts: 5\n        # 锁定时长（分钟），0=永久锁定\n        lockDurationMinutes: 30\n        # 失败计数窗口期（分钟）\n        attemptWindowMinutes: 15\n        # 从第几次失败开始给出\"还剩几次将锁定\"的详细提示， 之前的失败一律返回通用\"账号或密码错误\"，避免暴露用户存在性。\n        # 例：maxAttempts=5，hintAfterAttempts=3 时：\n        # 第 1/2 次：通用提示\n        # 第 3 次：剩余 2 次\n        # 第 4 次：剩余 1 次\n        # 第 5 次：触发自动锁定，下次登录命中锁定分支\n        hintAfterAttempts: 3\n    account-lock-signal:\n      # 永久锁定时 uid/name key 的 TTL（天），默认 30。\n      permanent-lock-ttl-days: 30\n    event:\n      # 总开关。false：SecurityEventPublisher 不投递任何事件；true：由 target 决定落点。\n      enabled: true\n      # 主投递目标。\n      # local  = 写入本服务库 security_event（须 classpath 有 Store，通常配 primary-store: mysql）\n      # center = 经 Feign/Transport 上报 ingot-security 中心 admission\n      target: local\n      # target=local 且 classpath 存在多个 SecurityEventStore 时的主 Store id。\n      # 可选值：mysql（MySqlSecurityEventStore）、log（LogSecurityEventStore）。\n      # 仅有一个 Store Bean 时可省略，自动选中。\n      primary-store: mysql\n      # 次要投递目标（迁移 shadow 双写用）。稳定态留空 []。\n      # 元素取值：local | center；与主 target 去重后额外投递一份，shadow 失败不影响主链路 ack。\n      shadow-targets: []\n      # 上报方模块标识，写入 security_event.source_module。\n      # PMS 填 PMS，Member 填 MEMBER。\n      source-module: PMS\n      # 按事件大类过滤是否上报（enabled=true 时生效）；false 则该类别事件在 Publisher 层被丢弃。\n      categories:\n        # AUTH：登录成功/失败等认证类事件\n        auth: true\n        # ACCOUNT：锁定/解锁/创建/删除等账号类事件\n        account: true\n        # CREDENTIAL：改密/重置/强制改密等凭证类事件\n        credential: true\n        # ACCESS：网关封禁/限流违规等访问防护类；PMS/Member 通常不产生，可保持 true\n        access: true\n      # 投递层：BEST_EFFORT 走 memory，DURABLE 走 spool（两条独立管道，非溢出关系）。\n      delivery:\n        # BEST_EFFORT 有界内存队列参数；后台线程 security-recording-memory 攒批后投递。\n        memory:\n          # 内存队列容量；满时新 BEST_EFFORT 事件 DROPPED，不阻塞业务线程。\n          queue-capacity: 2048\n          # memory worker 单次 claim 条数上限。\n          batch-size: 32\n          # worker 攒批 poll 超时（毫秒）；队列空则等待该时长后再次 poll。\n          poll-timeout-ms: 100\n          # 进程关闭时等待 memory worker 排空队列的最长时间（毫秒）。\n          shutdown-timeout-ms: 5000\n        # DURABLE 本地 file spool；后台线程 security-recording-durable 持续 claim → 投递 → ack/nack 重试。\n        spool:\n          # spool 根目录（append-only segment 文件）。\n          directory: /ingot-data/security-recording/spool\n          # spool 目录总磁盘配额（如 1GB、512MB）。\n          max-bytes: 1GB\n          # 单个 segment 文件大小上限，达上限滚动新文件。\n          segment-bytes: 64MB\n          # 业务线程同步等待 spool 接纳 DURABLE 事件的最长时间（毫秒）；超时返回 FAILED（业务仍 fail-open）。\n          durable-ack-timeout-ms: 20\n          # durable worker 每次从 spool claim 的条数上限。\n          replay-batch-size: 32\n          # 投递失败 nack 后重试初始退避（毫秒）。\n          retry-initial-ms: 1000\n          # 重试退避上限（毫秒）。\n          retry-max-ms: 60000\n      # MySQL SecurityEventStore 写入侧参数（target=local 且 primary-store=mysql 时生效）。\n      mysql:\n        # 并发写入信号量许可数；默认 1，避免 canonical security_event 热点写冲突。\n        max-concurrent-writes: 1\n        # 单批 INSERT 事务超时（秒）。\n        transaction-timeout-seconds: 5\n      # canonical security_event 过期物理删除（PurgeCanonicalSecurityEventTask，cron 0 30 3 * * ?）。\n      retention:\n        # 是否启用定时清理；false 等同永久保留。\n        enabled: true\n        # 保留天数；早于 now-days 的记录被删除；0 表示永久保留。\n        days: 30\n        # 单批 DELETE LIMIT 条数，避免长事务与大锁。\n        batch-size: 500\n        # 单次定时任务最多连续执行的批次数。\n        max-rounds: 100\n        # 单次 retention 任务最大执行时长（秒），超时停止本轮。\n        max-duration-seconds: 30\n        # memory/spool 队列使用率超过该百分比时，retention 让步暂停删除。\n        yield-queue-usage-percent: 50\n      # 按 eventType 覆盖默认优先级（BEST_EFFORT | DURABLE），支持 Nacos 热刷新。\n      # 未配置时使用 DefaultPriorityClassifier 内置默认表；示例：\n      # LOGIN_FAILURE: DURABLE\n      priority-overrides: {}\n  oss:\n    minio:\n      url: ${MINIO_URL:http://ingot-cloud:9090}\n      accessKey: ${MINIO_ACCESS_KEY:2NPpKzxFQjyeMTQFEXA1}\n      secretKey: ${MINIO_SECRET_KEY:8SGAp7DhqZCQrYnU9Poyu888pQOB6w4SP2ILHbVU}\n    rustfs:\n      url: ${RUSTFS_URL:http://ingot-cloud:19000}\n      accessKey: ${RUSTFS_ACCESS_KEY:7eYdiTxLbcpsfaNoKSQ0}\n      secretKey: ${RUSTFS_SECRET_KEY:PgXcoiT9bmYBrIUj6S7QHltf0w8KDzWaC5FMqLsx}\n  social:\n    wechat:\n      miniProgramAppId: wx18dc0ea8c6ca1d7d\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:true}  # 生产环境关闭\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.pms.mapper\n\n# 开发环境日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}\n', 'd5ddbd0d03f5d2dba3816c10e739fbe3', '2026-08-25 02:28:10', '2026-08-25 10:28:11', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (343, 905, 'in-service-pms.yml', 'DEV_GROUP', '', 'spring:\n  datasource:\n    # 数据库连接URL配置\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_core}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\n# Ingot业务配置\ningot:\n  security:\n    account:\n      # local 或 remote\n      mode: local\n      lockout:\n        # 是否启用自动锁定账号\n        enabled: ${ACCOUNT_LOCKOUT_ENABLED:true}\n        # 失败次数阈值\n        maxAttempts: 5\n        # 锁定时长（分钟），0=永久锁定\n        lockDurationMinutes: 30\n        # 失败计数窗口期（分钟）\n        attemptWindowMinutes: 15\n        # 从第几次失败开始给出\"还剩几次将锁定\"的详细提示， 之前的失败一律返回通用\"账号或密码错误\"，避免暴露用户存在性。\n        # 例：maxAttempts=5，hintAfterAttempts=3 时：\n        # 第 1/2 次：通用提示\n        # 第 3 次：剩余 2 次\n        # 第 4 次：剩余 1 次\n        # 第 5 次：触发自动锁定，下次登录命中锁定分支\n        hintAfterAttempts: 3\n    account-lock-signal:\n      # 永久锁定时 uid/name key 的 TTL（天），默认 30。\n      permanent-lock-ttl-days: 30\n    event:\n      # 总开关。false：SecurityEventPublisher 不投递任何事件；true：由 target 决定落点。\n      enabled: true\n      # 主投递目标。\n      # local  = 写入本服务库 security_event（须 classpath 有 Store，通常配 primary-store: mysql）\n      # center = 经 Feign/Transport 上报 ingot-security 中心 admission\n      target: local\n      # target=local 且 classpath 存在多个 SecurityEventStore 时的主 Store id。\n      # 可选值：mysql（MySqlSecurityEventStore）、log（LogSecurityEventStore）。\n      # 仅有一个 Store Bean 时可省略，自动选中。\n      primary-store: mysql\n      # 次要投递目标（迁移 shadow 双写用）。稳定态留空 []。\n      # 元素取值：local | center；与主 target 去重后额外投递一份，shadow 失败不影响主链路 ack。\n      shadow-targets: []\n      # 上报方模块标识，写入 security_event.source_module。\n      # PMS 填 PMS，Member 填 MEMBER。\n      source-module: PMS\n      # 按事件大类过滤是否上报（enabled=true 时生效）；false 则该类别事件在 Publisher 层被丢弃。\n      categories:\n        # AUTH：登录成功/失败等认证类事件\n        auth: true\n        # ACCOUNT：锁定/解锁/创建/删除等账号类事件\n        account: true\n        # CREDENTIAL：改密/重置/强制改密等凭证类事件\n        credential: true\n        # ACCESS：网关封禁/限流违规等访问防护类；PMS/Member 通常不产生，可保持 true\n        access: true\n      # 投递层：BEST_EFFORT 走 memory，DURABLE 走 spool（两条独立管道，非溢出关系）。\n      delivery:\n        # BEST_EFFORT 有界内存队列参数；后台线程 security-recording-memory 攒批后投递。\n        memory:\n          # 内存队列容量；满时新 BEST_EFFORT 事件 DROPPED，不阻塞业务线程。\n          queue-capacity: 2048\n          # memory worker 单次 claim 条数上限。\n          batch-size: 32\n          # worker 攒批 poll 超时（毫秒）；队列空则等待该时长后再次 poll。\n          poll-timeout-ms: 100\n          # 进程关闭时等待 memory worker 排空队列的最长时间（毫秒）。\n          shutdown-timeout-ms: 5000\n        # DURABLE 本地 file spool；后台线程 security-recording-durable 持续 claim → 投递 → ack/nack 重试。\n        spool:\n          # spool 根目录（append-only segment 文件）。\n          directory: /ingot-data/security-recording/spool\n          # spool 目录总磁盘配额（如 1GB、512MB）。\n          max-bytes: 1GB\n          # 单个 segment 文件大小上限，达上限滚动新文件。\n          segment-bytes: 64MB\n          # 业务线程同步等待 spool 接纳 DURABLE 事件的最长时间（毫秒）；超时返回 FAILED（业务仍 fail-open）。\n          durable-ack-timeout-ms: 20\n          # durable worker 每次从 spool claim 的条数上限。\n          replay-batch-size: 32\n          # 投递失败 nack 后重试初始退避（毫秒）。\n          retry-initial-ms: 1000\n          # 重试退避上限（毫秒）。\n          retry-max-ms: 60000\n      # MySQL SecurityEventStore 写入侧参数（target=local 且 primary-store=mysql 时生效）。\n      mysql:\n        # 并发写入信号量许可数；默认 1，避免 canonical security_event 热点写冲突。\n        max-concurrent-writes: 1\n        # 单批 INSERT 事务超时（秒）。\n        transaction-timeout-seconds: 5\n      # canonical security_event 过期物理删除（PurgeCanonicalSecurityEventTask，cron 0 30 3 * * ?）。\n      retention:\n        # 是否启用定时清理；false 等同永久保留。\n        enabled: true\n        # 保留天数；早于 now-days 的记录被删除；0 表示永久保留。\n        days: 30\n        # 单批 DELETE LIMIT 条数，避免长事务与大锁。\n        batch-size: 500\n        # 单次定时任务最多连续执行的批次数。\n        max-rounds: 100\n        # 单次 retention 任务最大执行时长（秒），超时停止本轮。\n        max-duration-seconds: 30\n        # memory/spool 队列使用率超过该百分比时，retention 让步暂停删除。\n        yield-queue-usage-percent: 50\n      # 按 eventType 覆盖默认优先级（BEST_EFFORT | DURABLE），支持 Nacos 热刷新。\n      # 未配置时使用 DefaultPriorityClassifier 内置默认表；示例：\n      # LOGIN_FAILURE: DURABLE\n      priority-overrides: {}\n  oss:\n    minio:\n      url: ${MINIO_URL:http://ingot-cloud:9090}\n      accessKey: ${MINIO_ACCESS_KEY:2NPpKzxFQjyeMTQFEXA1}\n      secretKey: ${MINIO_SECRET_KEY:8SGAp7DhqZCQrYnU9Poyu888pQOB6w4SP2ILHbVU}\n    rustfs:\n      url: ${RUSTFS_URL:http://ingot-cloud:19000}\n      accessKey: ${RUSTFS_ACCESS_KEY:7eYdiTxLbcpsfaNoKSQ0}\n      secretKey: ${RUSTFS_SECRET_KEY:PgXcoiT9bmYBrIUj6S7QHltf0w8KDzWaC5FMqLsx}\n  social:\n    wechat:\n      miniProgramAppId: wx18dc0ea8c6ca1d7d\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:true}  # 生产环境关闭\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.pms.mapper\n\n# 开发环境日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}\n', '5bfc4bc70cfe4add9515e62b5e600112', '2026-08-25 02:31:04', '2026-08-25 10:31:04', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (343, 906, 'in-service-pms.yml', 'DEV_GROUP', '', 'spring:\n  datasource:\n    # 数据库连接URL配置\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_core}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\n# Ingot业务配置\ningot:\n  security:\n    account:\n      # local 或 remote\n      mode: local\n      lockout:\n        # 是否启用自动锁定账号\n        enabled: ${ACCOUNT_LOCKOUT_ENABLED:true}\n        # 失败次数阈值\n        maxAttempts: 5\n        # 锁定时长（分钟），0=永久锁定\n        lockDurationMinutes: 30\n        # 失败计数窗口期（分钟）\n        attemptWindowMinutes: 15\n        # 从第几次失败开始给出\"还剩几次将锁定\"的详细提示， 之前的失败一律返回通用\"账号或密码错误\"，避免暴露用户存在性。\n        # 例：maxAttempts=5，hintAfterAttempts=3 时：\n        # 第 1/2 次：通用提示\n        # 第 3 次：剩余 2 次\n        # 第 4 次：剩余 1 次\n        # 第 5 次：触发自动锁定，下次登录命中锁定分支\n        hintAfterAttempts: 3\n    account-lock-signal:\n      # 永久锁定时 uid/name key 的 TTL（天），默认 30。\n      permanent-lock-ttl-days: 30\n    event:\n      # 总开关。false：SecurityEventPublisher 不投递任何事件；true：由 target 决定落点。\n      enabled: true\n      # 主投递目标。\n      # local  = 写入本服务库 security_event（须 classpath 有 Store，通常配 primary-store: mysql）\n      # center = 经 Feign/Transport 上报 ingot-security 中心 admission\n      target: local\n      # target=local 且 classpath 存在多个 SecurityEventStore 时的主 Store id。\n      # 可选值：mysql（MySqlSecurityEventStore）、log（LogSecurityEventStore）。\n      # 仅有一个 Store Bean 时可省略，自动选中。\n      primary-store: mysql\n      # 次要投递目标（迁移 shadow 双写用）。稳定态留空 []。\n      # 元素取值：local | center；与主 target 去重后额外投递一份，shadow 失败不影响主链路 ack。\n      shadow-targets: []\n      # 上报方模块标识，写入 security_event.source_module。\n      # PMS 填 PMS，Member 填 MEMBER。\n      source-module: PMS\n      # 按事件大类过滤是否上报（enabled=true 时生效）；false 则该类别事件在 Publisher 层被丢弃。\n      categories:\n        # AUTH：登录成功/失败等认证类事件\n        auth: true\n        # ACCOUNT：锁定/解锁/创建/删除等账号类事件\n        account: true\n        # CREDENTIAL：改密/重置/强制改密等凭证类事件\n        credential: true\n        # ACCESS：网关封禁/限流违规等访问防护类；PMS/Member 通常不产生，可保持 true\n        access: true\n      # 投递层：BEST_EFFORT 走 memory，DURABLE 走 spool（两条独立管道，非溢出关系）。\n      delivery:\n        # BEST_EFFORT 有界内存队列参数；后台线程 security-recording-memory 攒批后投递。\n        memory:\n          # 内存队列容量；满时新 BEST_EFFORT 事件 DROPPED，不阻塞业务线程。\n          queue-capacity: 2048\n          # memory worker 单次 claim 条数上限。\n          batch-size: 32\n          # worker 攒批 poll 超时（毫秒）；队列空则等待该时长后再次 poll。\n          poll-timeout-ms: 100\n          # 进程关闭时等待 memory worker 排空队列的最长时间（毫秒）。\n          shutdown-timeout-ms: 5000\n        # DURABLE 本地 file spool；后台线程 security-recording-durable 持续 claim → 投递 → ack/nack 重试。\n        spool:\n          # spool 根目录（append-only segment 文件）。\n          directory: /ingot-data/security-recording/spool\n          # spool 目录总磁盘配额（如 1GB、512MB）。\n          max-bytes: 1GB\n          # 单个 segment 文件大小上限，达上限滚动新文件。\n          segment-bytes: 64MB\n          # 业务线程同步等待 spool 接纳 DURABLE 事件的最长时间（毫秒）；超时返回 FAILED（业务仍 fail-open）。\n          durable-ack-timeout-ms: 20\n          # durable worker 每次从 spool claim 的条数上限。\n          replay-batch-size: 32\n          # 投递失败 nack 后重试初始退避（毫秒）。\n          retry-initial-ms: 1000\n          # 重试退避上限（毫秒）。\n          retry-max-ms: 60000\n      # MySQL SecurityEventStore 写入侧参数（target=local 且 primary-store=mysql 时生效）。\n      mysql:\n        # 并发写入信号量许可数；默认 1，避免 canonical security_event 热点写冲突。\n        max-concurrent-writes: 1\n        # 单批 INSERT 事务超时（秒）。\n        transaction-timeout-seconds: 5\n      # canonical security_event 过期物理删除（PurgeCanonicalSecurityEventTask，cron 0 30 3 * * ?）。\n      retention:\n        # 是否启用定时清理；false 等同永久保留。\n        enabled: true\n        # 保留天数；早于 now-days 的记录被删除；0 表示永久保留。\n        days: 30\n        # 单批 DELETE LIMIT 条数，避免长事务与大锁。\n        batch-size: 500\n        # 单次定时任务最多连续执行的批次数。\n        max-rounds: 100\n        # 单次 retention 任务最大执行时长（秒），超时停止本轮。\n        max-duration-seconds: 30\n        # memory/spool 队列使用率超过该百分比时，retention 让步暂停删除。\n        yield-queue-usage-percent: 50\n      # 按 eventType 覆盖默认优先级（BEST_EFFORT | DURABLE），支持 Nacos 热刷新。\n      # 未配置时使用 DefaultPriorityClassifier 内置默认表；示例：\n      # LOGIN_FAILURE: DURABLE\n      priority-overrides: {}\n  oss:\n    minio:\n      url: ${MINIO_URL:http://ingot-cloud:9090}\n      accessKey: ${MINIO_ACCESS_KEY:2NPpKzxFQjyeMTQFEXA1}\n      secretKey: ${MINIO_SECRET_KEY:8SGAp7DhqZCQrYnU9Poyu888pQOB6w4SP2ILHbVU}\n    rustfs:\n      url: ${RUSTFS_URL:http://ingot-cloud:19000}\n      accessKey: ${RUSTFS_ACCESS_KEY:7eYdiTxLbcpsfaNoKSQ0}\n      secretKey: ${RUSTFS_SECRET_KEY:PgXcoiT9bmYBrIUj6S7QHltf0w8KDzWaC5FMqLsx}\n  social:\n    wechat:\n      miniProgramAppId: wx18dc0ea8c6ca1d7d\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:true}  # 生产环境关闭\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.pms.mapper\n\n# 开发环境日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}\n', '5bfc4bc70cfe4add9515e62b5e600112', '2026-08-25 03:23:10', '2026-08-25 11:23:11', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (343, 907, 'in-service-pms.yml', 'DEV_GROUP', '', 'spring:\n  datasource:\n    # 数据库连接URL配置\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_core}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\n# Ingot业务配置\ningot:\n  security:\n    account:\n      # local 或 remote\n      mode: remote\n      lockout:\n        # 是否启用自动锁定账号\n        enabled: ${ACCOUNT_LOCKOUT_ENABLED:true}\n        # 失败次数阈值\n        maxAttempts: 5\n        # 锁定时长（分钟），0=永久锁定\n        lockDurationMinutes: 30\n        # 失败计数窗口期（分钟）\n        attemptWindowMinutes: 15\n        # 从第几次失败开始给出\"还剩几次将锁定\"的详细提示， 之前的失败一律返回通用\"账号或密码错误\"，避免暴露用户存在性。\n        # 例：maxAttempts=5，hintAfterAttempts=3 时：\n        # 第 1/2 次：通用提示\n        # 第 3 次：剩余 2 次\n        # 第 4 次：剩余 1 次\n        # 第 5 次：触发自动锁定，下次登录命中锁定分支\n        hintAfterAttempts: 3\n    account-lock-signal:\n      # 永久锁定时 uid/name key 的 TTL（天），默认 30。\n      permanent-lock-ttl-days: 30\n    event:\n      # 总开关。false：SecurityEventPublisher 不投递任何事件；true：由 target 决定落点。\n      enabled: true\n      # 主投递目标。\n      # local  = 写入本服务库 security_event（须 classpath 有 Store，通常配 primary-store: mysql）\n      # center = 经 Feign/Transport 上报 ingot-security 中心 admission\n      target: local\n      # target=local 且 classpath 存在多个 SecurityEventStore 时的主 Store id。\n      # 可选值：mysql（MySqlSecurityEventStore）、log（LogSecurityEventStore）。\n      # 仅有一个 Store Bean 时可省略，自动选中。\n      primary-store: mysql\n      # 次要投递目标（迁移 shadow 双写用）。稳定态留空 []。\n      # 元素取值：local | center；与主 target 去重后额外投递一份，shadow 失败不影响主链路 ack。\n      shadow-targets: []\n      # 上报方模块标识，写入 security_event.source_module。\n      # PMS 填 PMS，Member 填 MEMBER。\n      source-module: PMS\n      # 按事件大类过滤是否上报（enabled=true 时生效）；false 则该类别事件在 Publisher 层被丢弃。\n      categories:\n        # AUTH：登录成功/失败等认证类事件\n        auth: true\n        # ACCOUNT：锁定/解锁/创建/删除等账号类事件\n        account: true\n        # CREDENTIAL：改密/重置/强制改密等凭证类事件\n        credential: true\n        # ACCESS：网关封禁/限流违规等访问防护类；PMS/Member 通常不产生，可保持 true\n        access: true\n      # 投递层：BEST_EFFORT 走 memory，DURABLE 走 spool（两条独立管道，非溢出关系）。\n      delivery:\n        # BEST_EFFORT 有界内存队列参数；后台线程 security-recording-memory 攒批后投递。\n        memory:\n          # 内存队列容量；满时新 BEST_EFFORT 事件 DROPPED，不阻塞业务线程。\n          queue-capacity: 2048\n          # memory worker 单次 claim 条数上限。\n          batch-size: 32\n          # worker 攒批 poll 超时（毫秒）；队列空则等待该时长后再次 poll。\n          poll-timeout-ms: 100\n          # 进程关闭时等待 memory worker 排空队列的最长时间（毫秒）。\n          shutdown-timeout-ms: 5000\n        # DURABLE 本地 file spool；后台线程 security-recording-durable 持续 claim → 投递 → ack/nack 重试。\n        spool:\n          # spool 根目录（append-only segment 文件）。\n          directory: /ingot-data/security-recording/spool\n          # spool 目录总磁盘配额（如 1GB、512MB）。\n          max-bytes: 1GB\n          # 单个 segment 文件大小上限，达上限滚动新文件。\n          segment-bytes: 64MB\n          # 业务线程同步等待 spool 接纳 DURABLE 事件的最长时间（毫秒）；超时返回 FAILED（业务仍 fail-open）。\n          durable-ack-timeout-ms: 20\n          # durable worker 每次从 spool claim 的条数上限。\n          replay-batch-size: 32\n          # 投递失败 nack 后重试初始退避（毫秒）。\n          retry-initial-ms: 1000\n          # 重试退避上限（毫秒）。\n          retry-max-ms: 60000\n      # MySQL SecurityEventStore 写入侧参数（target=local 且 primary-store=mysql 时生效）。\n      mysql:\n        # 并发写入信号量许可数；默认 1，避免 canonical security_event 热点写冲突。\n        max-concurrent-writes: 1\n        # 单批 INSERT 事务超时（秒）。\n        transaction-timeout-seconds: 5\n      # canonical security_event 过期物理删除（PurgeCanonicalSecurityEventTask，cron 0 30 3 * * ?）。\n      retention:\n        # 是否启用定时清理；false 等同永久保留。\n        enabled: true\n        # 保留天数；早于 now-days 的记录被删除；0 表示永久保留。\n        days: 30\n        # 单批 DELETE LIMIT 条数，避免长事务与大锁。\n        batch-size: 500\n        # 单次定时任务最多连续执行的批次数。\n        max-rounds: 100\n        # 单次 retention 任务最大执行时长（秒），超时停止本轮。\n        max-duration-seconds: 30\n        # memory/spool 队列使用率超过该百分比时，retention 让步暂停删除。\n        yield-queue-usage-percent: 50\n      # 按 eventType 覆盖默认优先级（BEST_EFFORT | DURABLE），支持 Nacos 热刷新。\n      # 未配置时使用 DefaultPriorityClassifier 内置默认表；示例：\n      # LOGIN_FAILURE: DURABLE\n      priority-overrides: {}\n  oss:\n    minio:\n      url: ${MINIO_URL:http://ingot-cloud:9090}\n      accessKey: ${MINIO_ACCESS_KEY:2NPpKzxFQjyeMTQFEXA1}\n      secretKey: ${MINIO_SECRET_KEY:8SGAp7DhqZCQrYnU9Poyu888pQOB6w4SP2ILHbVU}\n    rustfs:\n      url: ${RUSTFS_URL:http://ingot-cloud:19000}\n      accessKey: ${RUSTFS_ACCESS_KEY:7eYdiTxLbcpsfaNoKSQ0}\n      secretKey: ${RUSTFS_SECRET_KEY:PgXcoiT9bmYBrIUj6S7QHltf0w8KDzWaC5FMqLsx}\n  social:\n    wechat:\n      miniProgramAppId: wx18dc0ea8c6ca1d7d\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:true}  # 生产环境关闭\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.pms.mapper\n\n# 开发环境日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}\n', '4bd38217709e96078177568497138d08', '2026-08-25 05:01:10', '2026-08-25 13:01:10', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (0, 908, 'in-security-gateway.yml', 'DEV_GROUP', '', 'ingot:\n  security:\n    ratelimit:\n      policy:\n        groups:\n          - code: login-auth-floor\n            name: 登录授权层\n            enabled: true\n            pattern-list:\n              - path: /bff/auth/login\n                method: POST\n          - code: api-business-floor\n            name: 公共业务层\n            enabled: true\n            pattern-list:\n              - path: /pms/**\n                method: ANY\n              - path: /member/**\n                method: ANY\n              - path: /security/**\n                method: ANY\n        rules:\n          - code: login-ip-floor\n            group-code: login-auth-floor\n            dimension: IP\n            qps: 8\n            burst: 12\n            interval-sec: 60\n            control-behavior: F\n            enabled: true\n            priority: 0\n          - code: biz-ip-floor\n            group-code: api-business-floor\n            dimension: IP\n            qps: 150\n            burst: 225\n            interval-sec: 1\n            control-behavior: F\n            enabled: true\n            priority: 10\n    blacklist:\n      policy:\n        items:\n          - list-type: WHITE\n            key-type: IP\n            key-value: 127.0.0.1\n            enabled: true\n    violation-escalation:\n      policy:\n        window-sec: 60\n        block-threshold: 25\n        temp-block-ttl-sec: 900\n        enabled: true', 'd6dd5549c50c093614e94574c0b92e1b', '2026-08-25 08:14:34', '2026-08-25 16:14:35', 'nacos', '172.88.0.1', 'I', 'ingot', '', 'formal', '', '{\"src_user\":\"nacos\",\"type\":\"yaml\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (371, 909, 'in-security-gateway.yml', 'DEV_GROUP', '', 'ingot:\n  security:\n    ratelimit:\n      policy:\n        groups:\n          - code: login-auth-floor\n            name: 登录授权层\n            enabled: true\n            pattern-list:\n              - path: /bff/auth/login\n                method: POST\n          - code: api-business-floor\n            name: 公共业务层\n            enabled: true\n            pattern-list:\n              - path: /pms/**\n                method: ANY\n              - path: /member/**\n                method: ANY\n              - path: /security/**\n                method: ANY\n        rules:\n          - code: login-ip-floor\n            group-code: login-auth-floor\n            dimension: IP\n            qps: 8\n            burst: 12\n            interval-sec: 60\n            control-behavior: F\n            enabled: true\n            priority: 0\n          - code: biz-ip-floor\n            group-code: api-business-floor\n            dimension: IP\n            qps: 150\n            burst: 225\n            interval-sec: 1\n            control-behavior: F\n            enabled: true\n            priority: 10\n    blacklist:\n      policy:\n        items:\n          - list-type: WHITE\n            key-type: IP\n            key-value: 127.0.0.1\n            enabled: true\n    violation-escalation:\n      policy:\n        window-sec: 60\n        block-threshold: 25\n        temp-block-ttl-sec: 900\n        enabled: true', 'd6dd5549c50c093614e94574c0b92e1b', '2026-08-25 08:34:09', '2026-08-25 16:34:10', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (344, 910, 'in-service-gateway.yml', 'DEV_GROUP', '', 'spring:\n  cloud:\n    gateway:\n      server:\n        webflux:\n          routes:\n            - id: openapi\n              uri: lb://in-service-gateway\n              predicates:\n                - Path=/v3/api-docs/**\n              filters:\n                - RewritePath=/v3/api-docs/(?<path>.*), /$\\{path}/$\\{path}/v3/api-docs\n            - id: in-service-pms\n              uri: lb://in-service-pms\n              predicates:\n                - Path=/pms/**\n              filters:\n                - StripPrefix=1\n            - id: in-service-member\n              uri: lb://in-service-member\n              predicates:\n                - Path=/member/**\n              filters:\n                - StripPrefix=1\n            - id: in-service-security\n              uri: lb://in-service-security\n              predicates:\n                - Path=/security/**\n              filters:\n                - StripPrefix=1\n            - id: in-crypto-pubkey\n              uri: lb://in-service-bff\n              predicates:\n                - Path=/crypto/public-keys\n            - id: in-service-bff\n              uri: lb://in-service-bff\n              predicates:\n                - Path=/bff/**\n            - id: in-service-auth\n              uri: lb://in-service-auth\n              predicates:\n                - Path=/auth/client/**\n              filters:\n                - StripPrefix=1\n\ningot:\n  vc:\n    verifyUrls:\n      - image,/auth/oauth2/token,POST\n      - image,/auth/oauth2/pre_authorize,POST\n      - image,/bff/auth/login,POST\n    image:\n      opsLimitGetPerMinute: 20\n      opsLimitCheckPerMinute: 40\n  security:\n    account-lock-gateway:\n      # 是否启用账号锁定 AccountLockFilter，默认开启\n      enabled: true\n      # 不检查锁定状态的路径 Ant 模式。\n      excludePathPatterns:\n        - /actuator/**\n        - /bff/auth/**\n    policy:\n      # GatewayRuleClientProperties\n      client:\n        # 跨节点失效订阅开关\n        invalidation-enabled: true\n        # 是否启用 remote → LKG → Nacos 地板 弹性降级链\n        resilience-enabled: true\n        # remote 不可用且 LKG 为空时，是否回落到 Nacos 地板配置\n        local-floor-enabled: true\n        # 共享快照的分层缓存参数。\n        cache:\n          # 1级缓存存活时间\n          l1-ttl: 5m\n          # 2级缓存存活时间\n          l2-ttl: 30m\n    # 限流域：编译为 Sentinel GatewayFlowRule；未配置的路径默认不限流（白名单式）\n    ratelimit:\n      enabled: true\n      policy:\n        mode: local\n        groups:\n          - code: login-auth-floor\n            name: 登录授权层\n            enabled: true\n            pattern-list:\n              - path: /bff/auth/login  # 网关对外路径（Ant 风格）；非下游 /test/**\n                method: POST           # 当前 Sentinel 编译忽略 method，保留供扩展\n          - code: api-business-floor\n            name: 公共业务层\n            enabled: true\n            pattern-list:\n              - path: /pms/**\n                method: ANY\n              - path: /member/**\n                method: ANY\n              - path: /security/**\n                method: ANY\n        rules:\n          - code: login-ip-floor\n            group-code: login-auth-floor\n            # IP / DEVICE / USER\n            dimension: IP  \n            # 平均 QPS\n            qps: 8\n            # 突发容量\n            burst: 12\n            # 统计窗口（秒）\n            interval-sec: 60\n            # F=快速失败(429) Q=排队\n            control-behavior: F\n            enabled: true\n            priority: 0\n          - code: biz-ip-floor\n            group-code: api-business-floor\n            dimension: IP\n            qps: 150\n            burst: 225\n            interval-sec: 1\n            control-behavior: F\n            enabled: true\n            priority: 10\n    # 黑白名单：静态名单 + Redis 临时封禁（限流违规升级）\n    blacklist:\n      enabled: false\n      policy:\n        mode: local\n        items:\n          # BLACK / WHITE\n          - list-type: WHITE\n            # IP / DEVICE / USER / CIDR / USER_AGENT / REFERER\n            key-type: IP\n            key-value: 127.0.0.1\n            enabled: true\n    # 限流违规升级：滑动窗口计数\n    violation-escalation:\n      enabled: true\n      policy:\n        mode: local\n        window-sec: 60\n        block-threshold: 25\n        temp-block-ttl-sec: 900\n        enabled: true\n    # 事件配置\n    event:\n      # 总开关；Gateway 仅在上报 ACCESS 类事件时依赖此项。\n      enabled: true\n      # center：经 Feign 上报 ingot-security admission；不写网关本地 security_event 表。\n      target: center\n      # Gateway 稳定态不需要 shadow；留空 []。\n      shadow-targets: []\n      # 写入中心 security_event.source_module。\n      source-module: GATEWAY\n      # Gateway 通常只产生 ACCESS 类事件；其余类别关闭可减少无效配置。\n      categories:\n        auth: false\n        account: false\n        credential: false\n        access: true\n      # target=center 时 BEST_EFFORT 仍走 memory 缓冲后再 Feign 批量上报。\n      delivery:\n        memory:\n          queue-capacity: 2048\n          batch-size: 32\n          poll-timeout-ms: 100\n          shutdown-timeout-ms: 5000\n        # DURABLE 事件（如 BLACKLIST_BLOCK）仍需要 spool；未显式配置时使用下方 Java 默认值：\n        # spool.directory=./logs/security-recording/spool, max-bytes=1GB, ...\n      # Gateway 不写本地 canonical 表，通常不需要 retention；中心库由 in-service-security 清理。\n      retention:\n        enabled: false\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n\n# 开发环境日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}', '53fedc5a2f9f8506e05d9322b02affdb', '2026-08-25 08:37:37', '2026-08-25 16:37:37', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (350, 911, 'in-security-policy.yml', 'DEV_GROUP', '', 'ingot:\n  security:\n    ignoreTenantValidateRoleCodeList:\n      - role_admin\n    \n    # 重放配置\n    replay:\n      enabled: true\n      window: 5m\n      clock-skew: 5m\n      key-prefix: \"replay:\"\n      fail-open: false\n    \n    # 凭证配置\n    credential:\n      cache:\n        # 是否启用 L1 Caffeine\n        l1-enabled: true\n        # L1 TTL（默认 5 分钟）\n        l1-ttl: 5m\n        # L1 最大条目数（实际单 key，但保留容量）\n        l1-maximum-size: 16\n        # 是否启用 L2 Redis\n        l2-enabled: true\n        # L2 TTL（默认 30 分钟）\n        l2-ttl: 30m\n        # L2 Redis key 前缀\n        l2-key-prefix: \"in:credential:configs:\"\n        # 是否启用跨节点失效订阅\n        invalidation-enabled: true\n      policy:\n        # 策略加载模式：local（本地配置）或 remote（远程加载）\n        mode: ${CREDENTIAL_MODE:local}\n\n        # 本地策略配置\n        strength:\n          # 是否启用\n          enabled: true\n          # 最小长度\n          min-length: 8\n          # 最大长度\n          max-length: 32\n          # 是否要求大写字母\n          require-uppercase: false\n          # 是否要求小写字母\n          require-lowercase: false\n          # 是否要求数字\n          require-digit: false\n          # 是否要求特殊字符\n          requireSpecialChar: false\n          # 特殊字符集合\n          specialChars: \"!@#$%^&*()_+-=[]{}|;:,.<>?\"\n          # 禁止的模式\n          forbiddenPatterns:\n            - \"password\"\n            - \"123456\"\n            - \"admin\"\n            - \"qwerty\"\n          # 禁止包含用户属性\n          forbidUserAttributes: false\n\n        history:\n          # 是否启用\n          enabled: true\n          # 检查最近N次密码\n          check-count: 5\n\n        expiration:\n          # 是否启用 \n          enabled: false\n          # 最大有效天数\n          max-days: 90\n          # 提前警告天数\n          warningDaysBefore: 7\n          # 宽限登录次数\n          graceLoginCount: 3\n\n        initialPassword:\n          # 初始密码生成方式：RANDOM-随机生成；FIXED-统一默认密码\n          generation: RANDOM\n          # 随机初始密码长度（generation=RANDOM 时生效）\n          length: 10\n          # 统一默认密码（generation=FIXED 时生效）\n          fixedPassword: In@123456\n          # 初始密码有效小时数；0 表示不限制。超过后视为初始密码失效，需重新重置。\n          validHours: 72\n          # 用后失效：初始密码修改成功后即失效（依赖 mustChangePwd/force_change 清除，默认 true）\n          oneTime: true\n          # 首次登录是否强制修改密码\n          forceChangeOnFirstLogin: true\n', 'c79b65467e70f351c4b2b861c8f8dbc4', '2026-08-25 08:43:22', '2026-08-25 16:43:22', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\",\"c_desc\":\"密码策略，登录策略，会话策略，账号策略等\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (350, 912, 'in-security-policy.yml', 'DEV_GROUP', '', 'ingot:\n  security:\n    ignoreTenantValidateRoleCodeList:\n      - role_admin\n    \n    # 重放配置\n    replay:\n      enabled: true\n      window: 5m\n      clock-skew: 5m\n      key-prefix: \"replay:\"\n      fail-open: false\n    \n    # 凭证配置\n    credential:\n      cache:\n        # 是否启用 L1 Caffeine\n        l1-enabled: true\n        # L1 TTL（默认 5 分钟）\n        l1-ttl: 5m\n        # L1 最大条目数（实际单 key，但保留容量）\n        l1-maximum-size: 16\n        # 是否启用 L2 Redis\n        l2-enabled: true\n        # L2 TTL（默认 30 分钟）\n        l2-ttl: 30m\n        # L2 Redis key 前缀\n        l2-key-prefix: \"in:credential:configs:\"\n        # 是否启用跨节点失效订阅\n        invalidation-enabled: true\n      policy:\n        # 策略加载模式：local（本地配置）或 remote（远程加载）\n        mode: ${CREDENTIAL_MODE:local}\n\n        # 本地策略配置\n        strength:\n          # 是否启用\n          enabled: true\n          # 最小长度\n          min-length: 8\n          # 最大长度\n          max-length: 32\n          # 是否要求大写字母\n          require-uppercase: false\n          # 是否要求小写字母\n          require-lowercase: false\n          # 是否要求数字\n          require-digit: false\n          # 是否要求特殊字符\n          requireSpecialChar: false\n          # 特殊字符集合\n          specialChars: \"!@#$%^&*()_+-=[]{}|;:,.<>?\"\n          # 禁止的模式\n          forbiddenPatterns:\n            - \"password\"\n            - \"123456\"\n            - \"admin\"\n            - \"qwerty\"\n          # 禁止包含用户属性\n          forbidUserAttributes: false\n\n        history:\n          # 是否启用\n          enabled: true\n          # 检查最近N次密码\n          check-count: 5\n\n        expiration:\n          # 是否启用 \n          enabled: false\n          # 最大有效天数\n          max-days: 90\n          # 提前警告天数\n          warningDaysBefore: 7\n          # 宽限登录次数\n          graceLoginCount: 3\n\n        initialPassword:\n          # 初始密码生成方式：RANDOM-随机生成；FIXED-统一默认密码\n          generation: RANDOM\n          # 随机初始密码长度（generation=RANDOM 时生效）\n          length: 10\n          # 统一默认密码（generation=FIXED 时生效）\n          fixedPassword: In@123456\n          # 初始密码有效小时数；0 表示不限制。超过后视为初始密码失效，需重新重置。\n          validHours: 72\n          # 用后失效：初始密码修改成功后即失效（依赖 mustChangePwd/force_change 清除，默认 true）\n          oneTime: true\n          # 首次登录是否强制修改密码\n          forceChangeOnFirstLogin: true\n\n    # 永久锁 Redis TTL（PMS/Member 写、BFF 读）；必须全局同一份\n    account:\n      signal:\n        # 永久锁定时 uid/name key 的 TTL（天），默认 30。\n        permanent-lock-ttl-days: 30\n\n    # PMS/Member/Security 写本地 canonical / spool 时共用。\n    # Auth/Gateway 不 import 本文件；BFF import 但不启用 recording。\n    event:\n      # 投递层：BEST_EFFORT 走 memory，DURABLE 走 spool（两条独立管道，非溢出关系）。\n      delivery:\n        # BEST_EFFORT 有界内存队列参数；后台线程 security-recording-memory 攒批后投递。\n        memory:\n          # 内存队列容量；满时新 BEST_EFFORT 事件 DROPPED，不阻塞业务线程。\n          queue-capacity: 2048\n          # memory worker 单次 claim 条数上限。\n          batch-size: 32\n          # worker 攒批 poll 超时（毫秒）；队列空则等待该时长后再次 poll。\n          poll-timeout-ms: 100\n          # 进程关闭时等待 memory worker 排空队列的最长时间（毫秒）。\n          shutdown-timeout-ms: 5000\n        # DURABLE 本地 file spool；后台线程 security-recording-durable 持续 claim → 投递 → ack/nack 重试。\n        spool:\n          # spool 根目录（append-only segment 文件）。\n          directory: /ingot-data/security-recording/spool\n          # spool 目录总磁盘配额（如 1GB、512MB）。\n          max-bytes: 1GB\n          # 单个 segment 文件大小上限，达上限滚动新文件。\n          segment-bytes: 64MB\n          # 业务线程同步等待 spool 接纳 DURABLE 事件的最长时间（毫秒）；超时返回 FAILED（业务仍 fail-open）。\n          durable-ack-timeout-ms: 20\n          # durable worker 每次从 spool claim 的条数上限。\n          replay-batch-size: 32\n          # 投递失败 nack 后重试初始退避（毫秒）。\n          retry-initial-ms: 1000\n          # 重试退避上限（毫秒）。\n          retry-max-ms: 60000\n      # MySQL SecurityEventStore 写入侧参数（target=local 且 primary-store=mysql 时生效）。\n      mysql:\n        # 并发写入信号量许可数；默认 1，避免 canonical security_event 热点写冲突。\n        max-concurrent-writes: 1\n        # 单批 INSERT 事务超时（秒）。\n        transaction-timeout-seconds: 5\n', 'b12403c5dd8909e6e907d2d53964e0aa', '2026-08-25 08:46:28', '2026-08-25 16:46:29', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\",\"c_desc\":\"密码策略，登录策略，会话策略，账号策略等\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (348, 913, 'in-service-bff.yml', 'DEV_GROUP', '', 'ingot:\n  security:\n    oauth2:\n      resource:\n        public-urls:\n          - /crypto/public-keys,GET\n    # 账号锁定 BFF 登录短路：解密后查 Redis name key；默认拦截不调 Auth\n    account-lock-bff:\n      # 是否在登录解密后检查 Redis name key，默认开启。\n      enabled: true\n      # BFF 拦截时是否仍调 Auth 以产生 LOGIN_FAILURE；默认关闭。\n      emit-login-failure-on-bff-block: false\n    # 永久锁 Redis key TTL（天）；PMS/Auth/BFF 共用\n    account-lock-signal:\n      # 永久锁定时 uid/name key 的 TTL（天），默认 30。\n      permanent-lock-ttl-days: 30\n  bff:\n    client-id: ingot-bff\n    scope: system\n    # 管理用户:0, C端用户:1\n    user-type: \"0\"\n    session-ttl: 7200\n    redirect-uri: http://localhost:5400/bff/auth/callback\n    cookie:\n      # 开发环境不设置 domain（localhost 可用），生产环境设置顶级域名如 .ingotcloud.top\n      domain: ${BFF_COOKIE_DOMAIN:}\n      # 开发环境 false，生产必须 true\n      secure: ${BFF_COOKIE_SECURE:false}\n      same-site: ${BFF_COOKIE_SAME_SITE:Lax}\n    security:\n      # 客户端指纹校验，防止 Cookie 盗用\n      fingerprint-enabled: ${BFF_FINGERPRINT_ENABLED:true}\n      # 指纹模式: device（前端设备指纹，推荐）/ ip_ua（服务端 IP+UA，降级方案）\n      fingerprint-mode: ${BFF_FINGERPRINT_MODE:device}\n      # 信任的前端应用域名列表\n      allowed-frontends:\n        - http://localhost:1798\n        - http://localhost:5798\n      default-redirect-uri: http://localhost:5798\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n\n# 开发环境日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}', '2ebd13ac856e5d4f6cb051bbfb389c45', '2026-08-25 08:47:51', '2026-08-25 16:47:51', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (346, 914, 'in-service-member.yml', 'DEV_GROUP', '', 'spring:\n  datasource:\n    # 数据库连接URL配置\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_member}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\n# Ingot业务配置\ningot:\n  security:\n    account:\n      # local 或 remote\n      mode: local\n      lockout:\n        # 是否启用自动锁定账号\n        enabled: ${ACCOUNT_LOCKOUT_ENABLED:true}\n        # 失败次数阈值\n        maxAttempts: 5\n        # 锁定时长（分钟），0=永久锁定\n        lockDurationMinutes: 30\n        # 失败计数窗口期（分钟）\n        attemptWindowMinutes: 15\n        # 从第几次失败开始给出\"还剩几次将锁定\"的详细提示， 之前的失败一律返回通用\"账号或密码错误\"，避免暴露用户存在性。\n        # 例：maxAttempts=5，hintAfterAttempts=3 时：\n        # 第 1/2 次：通用提示\n        # 第 3 次：剩余 2 次\n        # 第 4 次：剩余 1 次\n        # 第 5 次：触发自动锁定，下次登录命中锁定分支\n        hintAfterAttempts: 3\n    event:\n      # 总开关。false：SecurityEventPublisher 不投递任何事件；true：由 target 决定落点。\n      enabled: true\n      # 主投递目标。\n      # local  = 写入本服务库 security_event（须 classpath 有 Store，通常配 primary-store: mysql）\n      # center = 经 Feign/Transport 上报 ingot-security 中心 admission\n      target: local\n      # target=local 且 classpath 存在多个 SecurityEventStore 时的主 Store id。\n      # 可选值：mysql（MySqlSecurityEventStore）、log（LogSecurityEventStore）。\n      # 仅有一个 Store Bean 时可省略，自动选中。\n      primary-store: mysql\n      # 次要投递目标（迁移 shadow 双写用）。稳定态留空 []。\n      # 元素取值：local | center；与主 target 去重后额外投递一份，shadow 失败不影响主链路 ack。\n      shadow-targets: []\n      # 上报方模块标识，写入 security_event.source_module。\n      # PMS 填 PMS，Member 填 MEMBER。\n      source-module: MEMBER\n      # 按事件大类过滤是否上报（enabled=true 时生效）；false 则该类别事件在 Publisher 层被丢弃。\n      categories:\n        # AUTH：登录成功/失败等认证类事件\n        auth: true\n        # ACCOUNT：锁定/解锁/创建/删除等账号类事件\n        account: true\n        # CREDENTIAL：改密/重置/强制改密等凭证类事件\n        credential: true\n        # ACCESS：网关封禁/限流违规等访问防护类；PMS/Member 通常不产生，可保持 true\n        access: true\n      # 投递层：BEST_EFFORT 走 memory，DURABLE 走 spool（两条独立管道，非溢出关系）。\n      delivery:\n        # BEST_EFFORT 有界内存队列参数；后台线程 security-recording-memory 攒批后投递。\n        memory:\n          # 内存队列容量；满时新 BEST_EFFORT 事件 DROPPED，不阻塞业务线程。\n          queue-capacity: 2048\n          # memory worker 单次 claim 条数上限。\n          batch-size: 32\n          # worker 攒批 poll 超时（毫秒）；队列空则等待该时长后再次 poll。\n          poll-timeout-ms: 100\n          # 进程关闭时等待 memory worker 排空队列的最长时间（毫秒）。\n          shutdown-timeout-ms: 5000\n        # DURABLE 本地 file spool；后台线程 security-recording-durable 持续 claim → 投递 → ack/nack 重试。\n        spool:\n          # spool 根目录（append-only segment 文件）。\n          directory: /ingot-data/security-recording/spool\n          # spool 目录总磁盘配额（如 1GB、512MB）。\n          max-bytes: 1GB\n          # 单个 segment 文件大小上限，达上限滚动新文件。\n          segment-bytes: 64MB\n          # 业务线程同步等待 spool 接纳 DURABLE 事件的最长时间（毫秒）；超时返回 FAILED（业务仍 fail-open）。\n          durable-ack-timeout-ms: 20\n          # durable worker 每次从 spool claim 的条数上限。\n          replay-batch-size: 32\n          # 投递失败 nack 后重试初始退避（毫秒）。\n          retry-initial-ms: 1000\n          # 重试退避上限（毫秒）。\n          retry-max-ms: 60000\n      # MySQL SecurityEventStore 写入侧参数（target=local 且 primary-store=mysql 时生效）。\n      mysql:\n        # 并发写入信号量许可数；默认 1，避免 canonical security_event 热点写冲突。\n        max-concurrent-writes: 1\n        # 单批 INSERT 事务超时（秒）。\n        transaction-timeout-seconds: 5\n      # canonical security_event 过期物理删除（PurgeCanonicalSecurityEventTask，cron 0 30 3 * * ?）。\n      retention:\n        # 是否启用定时清理；false 等同永久保留。\n        enabled: true\n        # 保留天数；早于 now-days 的记录被删除；0 表示永久保留。\n        days: 30\n        # 单批 DELETE LIMIT 条数，避免长事务与大锁。\n        batch-size: 500\n        # 单次定时任务最多连续执行的批次数。\n        max-rounds: 100\n        # 单次 retention 任务最大执行时长（秒），超时停止本轮。\n        max-duration-seconds: 30\n        # memory/spool 队列使用率超过该百分比时，retention 让步暂停删除。\n        yield-queue-usage-percent: 50\n      # 按 eventType 覆盖默认优先级（BEST_EFFORT | DURABLE），支持 Nacos 热刷新。\n      # 未配置时使用 DefaultPriorityClassifier 内置默认表；示例：\n      # LOGIN_FAILURE: DURABLE\n      priority-overrides: {}\n  oss:\n    minio:\n      url: ${MINIO_URL:http://ingot-cloud:9090}\n      accessKey: ${MINIO_ACCESS_KEY:2NPpKzxFQjyeMTQFEXA1}\n      secretKey: ${MINIO_SECRET_KEY:8SGAp7DhqZCQrYnU9Poyu888pQOB6w4SP2ILHbVU}\n  social:\n    wechat:\n      miniProgramAppId: wx18dc0ea8c6ca1d7d\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:true}  # 生产环境关闭\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.member.mapper\n\n# 开发环境日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}\n', 'be1a494a95eac47e3d7b4bfc9b7ee1ab', '2026-08-25 08:49:51', '2026-08-25 16:49:52', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (343, 915, 'in-service-pms.yml', 'DEV_GROUP', '', 'spring:\n  datasource:\n    # 数据库连接URL配置\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_core}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\n# Ingot业务配置\ningot:\n  security:\n    account:\n      # local 或 remote\n      mode: local\n      lockout:\n        # 是否启用自动锁定账号\n        enabled: ${ACCOUNT_LOCKOUT_ENABLED:true}\n        # 失败次数阈值\n        maxAttempts: 5\n        # 锁定时长（分钟），0=永久锁定\n        lockDurationMinutes: 30\n        # 失败计数窗口期（分钟）\n        attemptWindowMinutes: 15\n        # 从第几次失败开始给出\"还剩几次将锁定\"的详细提示， 之前的失败一律返回通用\"账号或密码错误\"，避免暴露用户存在性。\n        # 例：maxAttempts=5，hintAfterAttempts=3 时：\n        # 第 1/2 次：通用提示\n        # 第 3 次：剩余 2 次\n        # 第 4 次：剩余 1 次\n        # 第 5 次：触发自动锁定，下次登录命中锁定分支\n        hintAfterAttempts: 3\n    account-lock-signal:\n      # 永久锁定时 uid/name key 的 TTL（天），默认 30。\n      permanent-lock-ttl-days: 30\n    event:\n      # 总开关。false：SecurityEventPublisher 不投递任何事件；true：由 target 决定落点。\n      enabled: true\n      # 主投递目标。\n      # local  = 写入本服务库 security_event（须 classpath 有 Store，通常配 primary-store: mysql）\n      # center = 经 Feign/Transport 上报 ingot-security 中心 admission\n      target: local\n      # target=local 且 classpath 存在多个 SecurityEventStore 时的主 Store id。\n      # 可选值：mysql（MySqlSecurityEventStore）、log（LogSecurityEventStore）。\n      # 仅有一个 Store Bean 时可省略，自动选中。\n      primary-store: mysql\n      # 次要投递目标（迁移 shadow 双写用）。稳定态留空 []。\n      # 元素取值：local | center；与主 target 去重后额外投递一份，shadow 失败不影响主链路 ack。\n      shadow-targets: []\n      # 上报方模块标识，写入 security_event.source_module。\n      # PMS 填 PMS，Member 填 MEMBER。\n      source-module: PMS\n      # 按事件大类过滤是否上报（enabled=true 时生效）；false 则该类别事件在 Publisher 层被丢弃。\n      categories:\n        # AUTH：登录成功/失败等认证类事件\n        auth: true\n        # ACCOUNT：锁定/解锁/创建/删除等账号类事件\n        account: true\n        # CREDENTIAL：改密/重置/强制改密等凭证类事件\n        credential: true\n        # ACCESS：网关封禁/限流违规等访问防护类；PMS/Member 通常不产生，可保持 true\n        access: true\n      # 投递层：BEST_EFFORT 走 memory，DURABLE 走 spool（两条独立管道，非溢出关系）。\n      delivery:\n        # BEST_EFFORT 有界内存队列参数；后台线程 security-recording-memory 攒批后投递。\n        memory:\n          # 内存队列容量；满时新 BEST_EFFORT 事件 DROPPED，不阻塞业务线程。\n          queue-capacity: 2048\n          # memory worker 单次 claim 条数上限。\n          batch-size: 32\n          # worker 攒批 poll 超时（毫秒）；队列空则等待该时长后再次 poll。\n          poll-timeout-ms: 100\n          # 进程关闭时等待 memory worker 排空队列的最长时间（毫秒）。\n          shutdown-timeout-ms: 5000\n        # DURABLE 本地 file spool；后台线程 security-recording-durable 持续 claim → 投递 → ack/nack 重试。\n        spool:\n          # spool 根目录（append-only segment 文件）。\n          directory: /ingot-data/security-recording/spool\n          # spool 目录总磁盘配额（如 1GB、512MB）。\n          max-bytes: 1GB\n          # 单个 segment 文件大小上限，达上限滚动新文件。\n          segment-bytes: 64MB\n          # 业务线程同步等待 spool 接纳 DURABLE 事件的最长时间（毫秒）；超时返回 FAILED（业务仍 fail-open）。\n          durable-ack-timeout-ms: 20\n          # durable worker 每次从 spool claim 的条数上限。\n          replay-batch-size: 32\n          # 投递失败 nack 后重试初始退避（毫秒）。\n          retry-initial-ms: 1000\n          # 重试退避上限（毫秒）。\n          retry-max-ms: 60000\n      # MySQL SecurityEventStore 写入侧参数（target=local 且 primary-store=mysql 时生效）。\n      mysql:\n        # 并发写入信号量许可数；默认 1，避免 canonical security_event 热点写冲突。\n        max-concurrent-writes: 1\n        # 单批 INSERT 事务超时（秒）。\n        transaction-timeout-seconds: 5\n      # canonical security_event 过期物理删除（PurgeCanonicalSecurityEventTask，cron 0 30 3 * * ?）。\n      retention:\n        # 是否启用定时清理；false 等同永久保留。\n        enabled: true\n        # 保留天数；早于 now-days 的记录被删除；0 表示永久保留。\n        days: 30\n        # 单批 DELETE LIMIT 条数，避免长事务与大锁。\n        batch-size: 500\n        # 单次定时任务最多连续执行的批次数。\n        max-rounds: 100\n        # 单次 retention 任务最大执行时长（秒），超时停止本轮。\n        max-duration-seconds: 30\n        # memory/spool 队列使用率超过该百分比时，retention 让步暂停删除。\n        yield-queue-usage-percent: 50\n      # 按 eventType 覆盖默认优先级（BEST_EFFORT | DURABLE），支持 Nacos 热刷新。\n      # 未配置时使用 DefaultPriorityClassifier 内置默认表；示例：\n      # LOGIN_FAILURE: DURABLE\n      priority-overrides: {}\n  oss:\n    minio:\n      url: ${MINIO_URL:http://ingot-cloud:9090}\n      accessKey: ${MINIO_ACCESS_KEY:2NPpKzxFQjyeMTQFEXA1}\n      secretKey: ${MINIO_SECRET_KEY:8SGAp7DhqZCQrYnU9Poyu888pQOB6w4SP2ILHbVU}\n    rustfs:\n      url: ${RUSTFS_URL:http://ingot-cloud:19000}\n      accessKey: ${RUSTFS_ACCESS_KEY:7eYdiTxLbcpsfaNoKSQ0}\n      secretKey: ${RUSTFS_SECRET_KEY:PgXcoiT9bmYBrIUj6S7QHltf0w8KDzWaC5FMqLsx}\n  social:\n    wechat:\n      miniProgramAppId: wx18dc0ea8c6ca1d7d\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:true}  # 生产环境关闭\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.pms.mapper\n\n# 开发环境日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}\n', '5bfc4bc70cfe4add9515e62b5e600112', '2026-08-25 08:51:19', '2026-08-25 16:51:20', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (347, 916, 'in-service-security.yml', 'DEV_GROUP', '', 'spring:\n  datasource:\n    # 数据库连接URL配置\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_security}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\n# Ingot业务配置\ningot:\n  security:\n    event:\n      # 中心 admission 接收的事件异步入库；false 则 admission 入队被禁用。\n      enabled: true\n      # 中心将事件写入本库 ingot_security.security_event。\n      target: local\n      primary-store: mysql\n      shadow-targets: []\n      source-module: SECURITY\n      categories:\n        auth: true\n        account: true\n        credential: true\n        access: true\n      # 中心库数据量大，retention.days 可按合规要求拉长（如 90～180）。\n      retention:\n        enabled: true\n        days: 90\n        batch-size: 500\n        max-rounds: 100\n        max-duration-seconds: 30\n        yield-queue-usage-percent: 50\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:true}  # 生产环境关闭\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.security.mapper\n\n# 开发环境日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}\n', 'fb82476c1d8da1f85a50c1edba65f29f', '2026-08-25 08:52:17', '2026-08-25 16:52:17', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
