 retention；中心库由 in-service-security 清理。\n      retention:\n        enabled: false\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n\n# 开发环境日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}', '53dca32b32f79cfe9ac7aba55239c482', '2026-08-28 06:41:30', '2026-08-28 14:41:31', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (364, 942, 'in-service-gateway.yml', 'PROD_GROUP', '', 'spring:\n  cloud:\n    gateway:\n      server:\n        webflux:\n          routes:\n            - id: openapi\n              uri: lb://in-service-gateway\n              predicates:\n                - Path=/v3/api-docs/**\n              filters:\n                - RewritePath=/v3/api-docs/(?<path>.*), /$\\{path}/$\\{path}/v3/api-docs\n            - id: in-service-pms\n              uri: lb://in-service-pms\n              predicates:\n                - Path=/pms/**\n              filters:\n                - StripPrefix=1\n            - id: in-service-member\n              uri: lb://in-service-member\n              predicates:\n                - Path=/member/**\n              filters:\n                - StripPrefix=1\n            - id: in-service-security\n              uri: lb://in-service-security\n              predicates:\n                - Path=/security/**\n              filters:\n                - StripPrefix=1\n            - id: in-crypto-pubkey\n              uri: lb://in-service-bff\n              predicates:\n                - Path=/crypto/public-keys\n            - id: in-service-bff\n              uri: lb://in-service-bff\n              predicates:\n                - Path=/bff/**\n            - id: in-service-auth\n              uri: lb://in-service-auth\n              predicates:\n                - Path=/auth/client/**,/auth/token/**\n              filters:\n                - StripPrefix=1\n\ningot:\n  vc:\n    verifyUrls:\n      - image,/auth/oauth2/token,POST\n      - image,/auth/oauth2/pre_authorize,POST\n      - image,/bff/auth/login,POST\n    image:\n      opsLimitGetPerMinute: 20\n      opsLimitCheckPerMinute: 40\n  security:\n    account:\n      gateway:\n        # 是否启用账号锁定 AccountLockFilter，默认开启\n        enabled: true\n        # 不检查锁定状态的路径 Ant 模式。\n        excludePathPatterns:\n          - /actuator/**\n          - /bff/auth/**\n    policy:\n      # GatewayRuleClientProperties\n      client:\n        # 跨节点失效订阅开关\n        invalidation-enabled: true\n        # 是否启用 remote → LKG → Nacos 地板 弹性降级链\n        resilience-enabled: true\n        # remote 不可用且 LKG 为空时，是否回落到 Nacos 地板配置\n        local-floor-enabled: true\n        # 共享快照的分层缓存参数。\n        cache:\n          # 1级缓存存活时间\n          l1-ttl: 5m\n          # 2级缓存存活时间\n          l2-ttl: 30m\n    # 限流域开关与来源；groups/rules 地板在 in-security-gateway.yml\n    ratelimit:\n      enabled: true\n      policy:\n        mode: local\n    # 黑白名单开关与来源；items 地板在 in-security-gateway.yml\n    blacklist:\n      enabled: false\n      policy:\n        mode: local\n    # 限流违规升级开关与来源；阈值地板在 in-security-gateway.yml\n    violation-escalation:\n      enabled: true\n      policy:\n        mode: local\n    # 事件配置\n    event:\n      # 总开关；Gateway 仅在上报 ACCESS 类事件时依赖此项。\n      enabled: true\n      # center：经 Feign 上报 ingot-security admission；不写网关本地 security_event 表。\n      target: center\n      # Gateway 稳定态不需要 shadow；留空 []。\n      shadow-targets: []\n      # 写入中心 security_event.source_module。\n      source-module: GATEWAY\n      # Gateway 通常只产生 ACCESS 类事件；其余类别关闭可减少无效配置。\n      categories:\n        auth: false\n        account: false\n        credential: false\n        access: true\n      # target=center 时 BEST_EFFORT 仍走 memory 缓冲后再 Feign 批量上报。\n      delivery:\n        memory:\n          queue-capacity: 2048\n          batch-size: 32\n          poll-timeout-ms: 100\n          shutdown-timeout-ms: 5000\n        # DURABLE 事件（如 BLACKLIST_BLOCK）仍需要 spool；未显式配置时使用下方 Java 默认值：\n        # spool.directory 为父目录，运行时再拼 spring.application.name。\n      # Gateway 不写本地 canonical 表，通常不需要 retention；中心库由 in-service-security 清理。\n      retention:\n        enabled: false\n\n# SpringDoc/Swagger配置（生产环境关闭）\nspringdoc:\n  api-docs:\n    enabled: false\n  swagger-ui:\n    enabled: false\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n\n# 生产环境日志级别配置\nlogging:\n  level:\n    root: ${LOG_LEVEL_ROOT:WARN}\n    org.springframework.web: ${LOG_LEVEL_WEB:WARN}\n    org.springframework.security: ${LOG_LEVEL_SECURITY:WARN}\n    org.springframework.cloud: ${LOG_LEVEL_CLOUD:WARN}\n    com.alibaba.nacos.client: ${LOG_LEVEL_NACOS:ERROR}\n    com.alibaba.cloud: ${LOG_LEVEL_ALIBABA_CLOUD:WARN}\n    com.ingot: ${LOG_LEVEL_APP:INFO}\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}', '27e441965fb7da24ee5ff4eb232fa60c', '2026-08-28 06:41:50', '2026-08-28 14:41:51', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (372, 943, 'in-security-gateway.yml', 'TEST_GROUP', '', '# 网关安全策略地板（仅 Gateway import）。\n# 只放各域 policy 数值（groups / rules / items），不要写 enabled / policy.mode，\n# 以免与 in-service-gateway.yml 同前缀覆盖。\n# 开关与 mode 仍在 in-service-gateway.yml。\ningot:\n  security:\n    # 限流域：编译为 Sentinel GatewayFlowRule；未配置的路径默认不限流（白名单式）\n    ratelimit:\n      policy:\n        groups:\n          - code: login-auth-floor\n            name: 登录授权层\n            enabled: true\n            pattern-list:\n              - path: /bff/auth/login  # 网关对外路径（Ant 风格）；非下游 /test/**\n                method: POST           # 当前 Sentinel 编译忽略 method，保留供扩展\n          - code: api-business-floor\n            name: 公共业务层\n            enabled: true\n            pattern-list:\n              - path: /pms/**\n                method: ANY\n              - path: /member/**\n                method: ANY\n              - path: /security/**\n                method: ANY\n        rules:\n          - code: login-ip-floor\n            group-code: login-auth-floor\n            # IP / DEVICE / USER\n            dimension: IP\n            # 平均 QPS\n            qps: 8\n            # 突发容量\n            burst: 12\n            # 统计窗口（秒）\n            interval-sec: 60\n            # F=快速失败(429) Q=排队\n            control-behavior: F\n            enabled: true\n            priority: 0\n          - code: biz-ip-floor\n            group-code: api-business-floor\n            dimension: IP\n            qps: 150\n            burst: 225\n            interval-sec: 1\n            control-behavior: F\n            enabled: true\n            priority: 10\n    # 黑白名单：静态名单 + Redis 临时封禁（限流违规升级）\n    blacklist:\n      policy:\n        items:\n          # BLACK / WHITE\n          - list-type: WHITE\n            # IP / DEVICE / USER / CIDR / USER_AGENT / REFERER\n            key-type: IP\n            key-value: 127.0.0.1\n            enabled: true\n    # 限流违规升级：滑动窗口计数\n    violation-escalation:\n      policy:\n        window-sec: 60\n        block-threshold: 25\n        temp-block-ttl-sec: 900\n        enabled: true\n', '35d48621a9ec38c33e7f5bf6332f629f', '2026-08-28 06:42:19', '2026-08-28 14:42:20', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (373, 944, 'in-security-gateway.yml', 'PROD_GROUP', '', '# 网关安全策略地板（仅 Gateway import）。\n# 只放各域 policy 数值（groups / rules / items），不要写 enabled / policy.mode，\n# 以免与 in-service-gateway.yml 同前缀覆盖。\n# 开关与 mode 仍在 in-service-gateway.yml。\ningot:\n  security:\n    # 限流域：编译为 Sentinel GatewayFlowRule；未配置的路径默认不限流（白名单式）\n    ratelimit:\n      policy:\n        groups:\n          - code: login-auth-floor\n            name: 登录授权层\n            enabled: true\n            pattern-list:\n              - path: /bff/auth/login  # 网关对外路径（Ant 风格）；非下游 /test/**\n                method: POST           # 当前 Sentinel 编译忽略 method，保留供扩展\n          - code: api-business-floor\n            name: 公共业务层\n            enabled: true\n            pattern-list:\n              - path: /pms/**\n                method: ANY\n              - path: /member/**\n                method: ANY\n              - path: /security/**\n                method: ANY\n        rules:\n          - code: login-ip-floor\n            group-code: login-auth-floor\n            # IP / DEVICE / USER\n            dimension: IP\n            # 平均 QPS\n            qps: 8\n            # 突发容量\n            burst: 12\n            # 统计窗口（秒）\n            interval-sec: 60\n            # F=快速失败(429) Q=排队\n            control-behavior: F\n            enabled: true\n            priority: 0\n          - code: biz-ip-floor\n            group-code: api-business-floor\n            dimension: IP\n            qps: 150\n            burst: 225\n            interval-sec: 1\n            control-behavior: F\n            enabled: true\n            priority: 10\n    # 黑白名单：静态名单 + Redis 临时封禁（限流违规升级）\n    blacklist:\n      policy:\n        items:\n          # BLACK / WHITE\n          - list-type: WHITE\n            # IP / DEVICE / USER / CIDR / USER_AGENT / REFERER\n            key-type: IP\n            key-value: 127.0.0.1\n            enabled: true\n    # 限流违规升级：滑动窗口计数\n    violation-escalation:\n      policy:\n        window-sec: 60\n        block-threshold: 25\n        temp-block-ttl-sec: 900\n        enabled: true\n', '35d48621a9ec38c33e7f5bf6332f629f', '2026-08-28 06:42:29', '2026-08-28 14:42:30', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (348, 945, 'in-service-bff.yml', 'DEV_GROUP', '', 'ingot:\n  security:\n    oauth2:\n      resource:\n        public-urls:\n          - /crypto/public-keys,GET\n    # 账号锁定 BFF 登录短路：解密后查 Redis name key；默认拦截不调 Auth\n    account:\n      bff:\n        # 是否在登录解密后检查 Redis name key，默认开启。\n        enabled: true\n        # BFF 拦截时是否仍调 Auth 以产生 LOGIN_FAILURE；默认关闭。\n        emit-login-failure-on-bff-block: false\n  bff:\n    client-id: ingot-bff\n    scope: system\n    # 管理用户:0, C端用户:1\n    user-type: \"0\"\n    session-ttl: 7200\n    redirect-uri: http://localhost:5400/bff/auth/callback\n    cookie:\n      # 开发环境不设置 domain（localhost 可用），生产环境设置顶级域名如 .ingotcloud.top\n      domain: ${BFF_COOKIE_DOMAIN:}\n      # 开发环境 false，生产必须 true\n      secure: ${BFF_COOKIE_SECURE:false}\n      same-site: ${BFF_COOKIE_SAME_SITE:Lax}\n    security:\n      # 客户端指纹校验，防止 Cookie 盗用\n      fingerprint-enabled: ${BFF_FINGERPRINT_ENABLED:true}\n      # 指纹模式: device（前端设备指纹，推荐）/ ip_ua（服务端 IP+UA，降级方案）\n      fingerprint-mode: ${BFF_FINGERPRINT_MODE:device}\n      # 信任的前端应用域名列表\n      allowed-frontends:\n        - http://localhost:1798\n        - http://localhost:5798\n      default-redirect-uri: http://localhost:5798\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n\n# 开发环境日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}', '8bf5c3f2172941cace8d5dbb674306ae', '2026-08-29 05:00:24', '2026-08-29 13:00:24', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (348, 946, 'in-service-bff.yml', 'DEV_GROUP', '', 'ingot:\n  security:\n    oauth2:\n      resource:\n        public-urls:\n          - /crypto/public-keys,GET\n    # 账号锁定 BFF 登录短路：解密后查 Redis name key；默认拦截不调 Auth\n    account:\n      bff:\n        # 是否在登录解密后检查 Redis name key，默认开启。\n        enabled: true\n        # BFF 拦截时是否仍调 Auth 以产生 LOGIN_FAILURE；默认关闭。\n        emit-login-failure-on-bff-block: false\n  bff:\n    client-id: ingot-bff\n    scope: system\n    # 管理用户:0, C端用户:1\n    user-type: \"0\"\n    session-ttl: 7200\n    redirect-uri: http://localhost:5400/bff/auth/callback\n    cookie:\n      # 开发环境不设置 domain（localhost 可用），生产环境设置顶级域名如 .ingotcloud.top\n      domain: ${BFF_COOKIE_DOMAIN:}\n      # 开发环境 false，生产必须 true\n      secure: ${BFF_COOKIE_SECURE:false}\n      same-site: ${BFF_COOKIE_SAME_SITE:Lax}\n    security:\n      # 客户端指纹校验，防止 Cookie 盗用\n      fingerprint-enabled: ${BFF_FINGERPRINT_ENABLED:true}\n      # 指纹模式: device（前端设备指纹，推荐）/ ip_ua（服务端 IP+UA，降级方案）\n      fingerprint-mode: ${BFF_FINGERPRINT_MODE:device}\n      # 信任的前端应用域名列表\n      allowed-frontends:\n        - http://localhost:1798\n        - http://localhost:5798\n        - http://192.168.1.190:1798\n        - http://192.168.1.190:5798\n      default-redirect-uri: http://localhost:5798\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n\n# 开发环境日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}', '45c66548638f7e3c483f171118fc60e2', '2026-09-01 00:33:44', '2026-09-01 08:33:45', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (345, 947, 'in-service-auth.yml', 'DEV_GROUP', '', 'spring:\n  mvc:\n    static-path-pattern: /static/**\n  thymeleaf:\n    cache: false\n    prefix: classpath:/templates/\n    suffix: .html\n    encoding: UTF-8\n    servlet:\n      content-type: text/html\n  datasource:\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_auth}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\ningot:\n  security:\n    oauth2:\n      auth:\n        loginFormUrl: https://login.ingotcloud.top/oauth2/challenge\n        issuer: http://${SERVICE_AUTH_HOST:localhost:5100}\n      resource:\n        publicUrls:\n          - /favicon.ico,GET\n          - /static/**,GET\n          - /logout,*\n          - /error,*\n    jwk:\n      key-lifetime: 90d\n      key-grace-period: 2h\n      max-active-keys: 3\n      cache-refresh-interval: 5m\n      master-key: ${AUTH_JWK_MASTER_KEY:a7A7FJ9KdQutfjbQh8sZSt2kcNtl/JUkmEI73aCR080=}\n      enable-encryption: true\n    access:\n      mode: local\n      loginFailure:\n        ip:\n          enabled: true\n          # 50次命中\n          maxAttempts: 50\n          # 时间窗口\n          windowMinutes: 1\n          # 锁定时间，秒\n          blockTtlSec: 3600\n          blockKeyType: \"IP\"\n        device:\n          enabled: false\n        client:\n          enabled: false\n        accountIp:\n          enabled: false\n    session:\n      # 会话存储不可用宽限期；超期一律拒绝，会话键不存在不在宽限范围内\n      store-unavailable-grace: 30s\n      # local：并发策略只读下面的 concurrency 段，不依赖安全中心（A9 场景）\n      mode: local\n      concurrency:\n        # 关闭后登录路径退回「只认 Client 的 UNIQUE / STANDARD」，紧急回退开关\n        enabled: true\n        # 0 = 不限并发；此时 Client 配置为 UNIQUE 仍按单会话处理\n        max-sessions: 0\n        # 会话数统计维度\n        dimension: USER_CLIENT\n        # 超限处置方式\n        overflow: KICK_OLDEST\n        # 管理用户（UserTypeEnum.ADMIN）是否强制单会话\n        admin-forbid-concurrent: false\n    event:\n      # 安全事件总开关；false 时不做任何上报\n      enabled: true\n      # center：会话撤销等 AUTH 事件 Feign 上报安全中心，Auth 本库不落 security_event\n      target: center\n      shadow-targets: []\n      # 写入 security_event.source_module\n      sourceModule: AUTH\n      # 安全事件大类上报开关\n      categories:\n        auth: true\n        account: false\n        credential: false\n        access: false\n      retention:\n        enabled: false\n\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:true}  # 生产环境关闭\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.auth.mapper\n\n# 日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}', '77a584c164aa7bbdf8b47f52c08b5b6c', '2026-09-01 07:16:41', '2026-09-01 15:16:42', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (345, 948, 'in-service-auth.yml', 'DEV_GROUP', '', 'spring:\n  mvc:\n    static-path-pattern: /static/**\n  thymeleaf:\n    cache: false\n    prefix: classpath:/templates/\n    suffix: .html\n    encoding: UTF-8\n    servlet:\n      content-type: text/html\n  datasource:\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_auth}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\ningot:\n  security:\n    oauth2:\n      auth:\n        loginFormUrl: https://login.ingotcloud.top/oauth2/challenge\n        issuer: http://${SERVICE_AUTH_HOST:localhost:5100}\n      resource:\n        publicUrls:\n          - /favicon.ico,GET\n          - /static/**,GET\n          - /logout,*\n          - /error,*\n    jwk:\n      key-lifetime: 90d\n      key-grace-period: 2h\n      max-active-keys: 3\n      cache-refresh-interval: 5m\n      master-key: ${AUTH_JWK_MASTER_KEY:a7A7FJ9KdQutfjbQh8sZSt2kcNtl/JUkmEI73aCR080=}\n      enable-encryption: true\n    access:\n      mode: local\n      loginFailure:\n        ip:\n          enabled: true\n          # 50次命中\n          maxAttempts: 50\n          # 时间窗口\n          windowMinutes: 1\n          # 锁定时间，秒\n          blockTtlSec: 3600\n          blockKeyType: \"IP\"\n        device:\n          enabled: false\n        client:\n          enabled: false\n        accountIp:\n          enabled: false\n    session:\n      # 会话存储不可用宽限期；超期一律拒绝，会话键不存在不在宽限范围内\n      store-unavailable-grace: 30s\n      # local：并发策略只读下面的 concurrency 段，不依赖安全中心（A9 场景）\n      mode: local\n      concurrency:\n        # 关闭后登录路径退回「只认 Client 的 UNIQUE / STANDARD」，紧急回退开关\n        enabled: true\n        # 0 = 不限并发；此时 Client 配置为 UNIQUE 仍按单会话处理\n        max-sessions: 0\n        # 会话数统计维度\n        dimension: USER_CLIENT\n        # 超限处置方式\n        overflow: KICK_OLDEST\n        # 管理用户（UserTypeEnum.ADMIN）是否强制单会话\n        admin-forbid-concurrent: false\n    event:\n      # 安全事件总开关；false 时不做任何上报\n      enabled: false\n      # center：会话撤销等 AUTH 事件 Feign 上报安全中心，Auth 本库不落 security_event\n      target: center\n      shadow-targets: []\n      # 写入 security_event.source_module\n      sourceModule: AUTH\n      # 安全事件大类上报开关\n      categories:\n        auth: true\n        account: false\n        credential: false\n        access: false\n      retention:\n        enabled: false\n\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:true}  # 生产环境关闭\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.auth.mapper\n\n# 日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}', '5f9a12225cb98aecb5d619e6823bb9d8', '2026-09-01 07:18:36', '2026-09-01 15:18:37', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (344, 949, 'in-service-gateway.yml', 'DEV_GROUP', '', 'spring:\n  cloud:\n    gateway:\n      server:\n        webflux:\n          routes:\n            - id: openapi\n              uri: lb://in-service-gateway\n              predicates:\n                - Path=/v3/api-docs/**\n              filters:\n                - RewritePath=/v3/api-docs/(?<path>.*), /$\\{path}/$\\{path}/v3/api-docs\n            - id: in-service-pms\n              uri: lb://in-service-pms\n              predicates:\n                - Path=/pms/**\n              filters:\n                - StripPrefix=1\n            - id: in-service-member\n              uri: lb://in-service-member\n              predicates:\n                - Path=/member/**\n              filters:\n                - StripPrefix=1\n            - id: in-service-security\n              uri: lb://in-service-security\n              predicates:\n                - Path=/security/**\n              filters:\n                - StripPrefix=1\n            - id: in-crypto-pubkey\n              uri: lb://in-service-bff\n              predicates:\n                - Path=/crypto/public-keys\n            - id: in-service-bff\n              uri: lb://in-service-bff\n              predicates:\n                - Path=/bff/**\n            - id: in-service-auth\n              uri: lb://in-service-auth\n              predicates:\n                - Path=/auth/client/**\n              filters:\n                - StripPrefix=1\n\ningot:\n  vc:\n    verifyUrls: []\n    image:\n      opsLimitGetPerMinute: 20\n      opsLimitCheckPerMinute: 40\n  security:\n    account:\n      gateway:\n        # 是否启用账号锁定 AccountLockFilter，默认开启\n        enabled: true\n        # 不检查锁定状态的路径 Ant 模式。\n        excludePathPatterns:\n          - /actuator/**\n          - /bff/auth/**\n    policy:\n      # GatewayRuleClientProperties\n      client:\n        # 跨节点失效订阅开关\n        invalidation-enabled: true\n        # 是否启用 remote → LKG → Nacos 地板 弹性降级链\n        resilience-enabled: true\n        # remote 不可用且 LKG 为空时，是否回落到 Nacos 地板配置\n        local-floor-enabled: true\n        # 共享快照的分层缓存参数。\n        cache:\n          # 1级缓存存活时间\n          l1-ttl: 5m\n          # 2级缓存存活时间\n          l2-ttl: 30m\n    # 限流域：编译为 Sentinel GatewayFlowRule；未配置的路径默认不限流（白名单式）\n    ratelimit:\n      enabled: true\n      policy:\n        mode: local\n    # 黑白名单：静态名单 + Redis 临时封禁（限流违规升级）\n    blacklist:\n      enabled: false\n      policy:\n        mode: local\n    # 限流违规升级：滑动窗口计数\n    violation-escalation:\n      enabled: true\n      policy:\n        mode: local\n    # 挑战验证开关与来源；groups/policies 地板在 in-security-gateway.yml\n    challenge:\n      enabled: true\n      policy:\n        mode: local\n    # 事件配置\n    event:\n      # 总开关；Gateway 仅在上报 ACCESS 类事件时依赖此项。\n      enabled: true\n      # center：经 Feign 上报 ingot-security admission；不写网关本地 security_event 表。\n      target: center\n      # Gateway 稳定态不需要 shadow；留空 []。\n      shadow-targets: []\n      # 写入中心 security_event.source_module。\n      source-module: GATEWAY\n      # Gateway 通常只产生 ACCESS 类事件；其余类别关闭可减少无效配置。\n      categories:\n        auth: false\n        account: false\n        credential: false\n        access: true\n      # target=center 时 BEST_EFFORT 仍走 memory 缓冲后再 Feign 批量上报。\n      delivery:\n        memory:\n          queue-capacity: 2048\n          batch-size: 32\n          poll-timeout-ms: 100\n          shutdown-timeout-ms: 5000\n        # DURABLE 事件（如 BLACKLIST_BLOCK）仍需要 spool；未显式配置时使用下方 Java 默认值：\n        # spool.directory=./logs/security-recording/spool, max-bytes=1GB, ...\n      # Gateway 不写本地 canonical 表，通常不需要 retention；中心库由 in-service-security 清理。\n      retention:\n        enabled: false\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n\n# 开发环境日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}', 'e829f21bcdb4215900949b44c443c595', '2026-09-14 06:07:07', '2026-09-14 14:07:08', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (0, 950, 'in-service-iam', 'DEFAULT_GROUP', '', 'spring:\n  datasource:\n    # 数据库连接URL配置\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_iam}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&connectionTimeZone=UTC&forceConnectionTimeZoneToSession=true&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\n# Ingot业务配置\ningot:\n  security:\n    account:\n      # local 或 remote；remote 时下方 lockout 仅作 Nacos 地板\n      mode: local\n      policy:\n        fallback:\n          local-floor-enabled: true\n        cache:\n          l1-enabled: true\n          l1-ttl: 5m\n          l2-enabled: true\n          l2-ttl: 30m\n      lockout:\n        # 是否启用自动锁定账号\n        enabled: ${ACCOUNT_LOCKOUT_ENABLED:true}\n        # 失败次数阈值\n        maxAttempts: 5\n        # 锁定时长（分钟），0=永久锁定\n        lockDurationMinutes: 30\n        # 失败计数窗口期（分钟）\n        attemptWindowMinutes: 15\n        # 从第几次失败开始给出\"还剩几次将锁定\"的详细提示， 之前的失败一律返回通用\"账号或密码错误\"，避免暴露用户存在性。\n        # 例：maxAttempts=5，hintAfterAttempts=3 时：\n        # 第 1/2 次：通用提示\n        # 第 3 次：剩余 2 次\n        # 第 4 次：剩余 1 次\n        # 第 5 次：触发自动锁定，下次登录命中锁定分支\n        hintAfterAttempts: 3\n    event:\n      # 总开关。false：SecurityEventPublisher 不投递任何事件；true：由 target 决定落点。\n      enabled: true\n      # 主投递目标。\n      # local  = 写入本服务库 security_event（须 classpath 有 Store，通常配 primary-store: mysql）\n      # center = 经 Feign/Transport 上报 ingot-security 中心 admission\n      target: local\n      # target=local 且 classpath 存在多个 SecurityEventStore 时的主 Store id。\n      # 可选值：mysql（MySqlSecurityEventStore）、log（LogSecurityEventStore）。\n      # 仅有一个 Store Bean 时可省略，自动选中。\n      primary-store: mysql\n      # 次要投递目标（迁移 shadow 双写用）。稳定态留空 []。\n      # 元素取值：local | center；与主 target 去重后额外投递一份，shadow 失败不影响主链路 ack。\n      shadow-targets: []\n      # 上报方模块标识，写入 security_event.source_module。\n      # IAM 填 IAM，Member 填 MEMBER。\n      source-module: IAM\n      # 按事件大类过滤是否上报（enabled=true 时生效）；false 则该类别事件在 Publisher 层被丢弃。\n      categories:\n        # AUTH：登录成功/失败等认证类事件\n        auth: true\n        # ACCOUNT：锁定/解锁/创建/删除等账号类事件\n        account: true\n        # CREDENTIAL：改密/重置/强制改密等凭证类事件\n        credential: true\n        # ACCESS：网关封禁/限流违规等访问防护类；IAM/Member 通常不产生，可保持 true\n        access: true\n      # canonical security_event 过期物理删除（PurgeCanonicalSecurityEventTask，cron 0 30 3 * * ?）。\n      # delivery / mysql 在 in-security-policy.yml（本服务已 import）。\n      retention:\n        # 是否启用定时清理；false 等同永久保留。\n        enabled: true\n        # 保留天数；早于 now-days 的记录被删除；0 表示永久保留。\n        days: 30\n        # 单批 DELETE LIMIT 条数，避免长事务与大锁。\n        batch-size: 500\n        # 单次定时任务最多连续执行的批次数。\n        max-rounds: 100\n        # 单次 retention 任务最大执行时长（秒），超时停止本轮。\n        max-duration-seconds: 30\n        # memory/spool 队列使用率超过该百分比时，retention 让步暂停删除。\n        yield-queue-usage-percent: 50\n      # 按 eventType 覆盖默认优先级（BEST_EFFORT | DURABLE），支持 Nacos 热刷新。\n      # 未配置时使用 DefaultPriorityClassifier 内置默认表；示例：\n      # LOGIN_FAILURE: DURABLE\n      priority-overrides: {}\n  oss:\n    minio:\n      url: ${MINIO_URL:http://ingot-cloud:9090}\n      accessKey: ${MINIO_ACCESS_KEY:2NPpKzxFQjyeMTQFEXA1}\n      secretKey: ${MINIO_SECRET_KEY:8SGAp7DhqZCQrYnU9Poyu888pQOB6w4SP2ILHbVU}\n    rustfs:\n      url: ${RUSTFS_URL:http://ingot-cloud:19000}\n      accessKey: ${RUSTFS_ACCESS_KEY:7eYdiTxLbcpsfaNoKSQ0}\n      secretKey: ${RUSTFS_SECRET_KEY:PgXcoiT9bmYBrIUj6S7QHltf0w8KDzWaC5FMqLsx}\n  social:\n    wechat:\n      miniProgramAppId: wx18dc0ea8c6ca1d7d\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:true}  # 生产环境关闭\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.iam.mapper\n\n# 开发环境日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}\n', 'ee90a9a4a4dfe8a1f105ca150b2839fb', '2026-09-14 06:08:47', '2026-09-14 14:08:48', 'nacos', '172.88.0.1', 'I', 'ingot', '', 'formal', '', '{\"src_user\":\"nacos\",\"type\":\"yaml\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (0, 951, 'in-service-iam.yml', 'DEFAULT_GROUP', '', 'spring:\n  datasource:\n    # 数据库连接URL配置\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ingot_iam}?useUnicode=true&characterEncoding=UTF8&useSSL=${MYSQL_SSL:false}&connectionTimeZone=UTC&forceConnectionTimeZoneToSession=true&allowPublicKeyRetrieval=true&rewriteBatchedStatements=true&cachePrepStmts=true&prepStmtCacheSize=${MYSQL_PREP_STMT_CACHE_SIZE:250}&prepStmtCacheSqlLimit=${MYSQL_PREP_STMT_SQL_LIMIT:2048}&cacheResultSetMetadata=true&cacheServerConfiguration=true&maintainTimeStats=false&useLocalSessionState=true&elideSetAutoCommits=true&socketTimeout=${MYSQL_SOCKET_TIMEOUT:30000}&connectTimeout=${MYSQL_CONNECT_TIMEOUT:10000}\n\n# Ingot业务配置\ningot:\n  security:\n    account:\n      # local 或 remote；remote 时下方 lockout 仅作 Nacos 地板\n      mode: local\n      policy:\n        fallback:\n          local-floor-enabled: true\n        cache:\n          l1-enabled: true\n          l1-ttl: 5m\n          l2-enabled: true\n          l2-ttl: 30m\n      lockout:\n        # 是否启用自动锁定账号\n        enabled: ${ACCOUNT_LOCKOUT_ENABLED:true}\n        # 失败次数阈值\n        maxAttempts: 5\n        # 锁定时长（分钟），0=永久锁定\n        lockDurationMinutes: 30\n        # 失败计数窗口期（分钟）\n        attemptWindowMinutes: 15\n        # 从第几次失败开始给出\"还剩几次将锁定\"的详细提示， 之前的失败一律返回通用\"账号或密码错误\"，避免暴露用户存在性。\n        # 例：maxAttempts=5，hintAfterAttempts=3 时：\n        # 第 1/2 次：通用提示\n        # 第 3 次：剩余 2 次\n        # 第 4 次：剩余 1 次\n        # 第 5 次：触发自动锁定，下次登录命中锁定分支\n        hintAfterAttempts: 3\n    event:\n      # 总开关。false：SecurityEventPublisher 不投递任何事件；true：由 target 决定落点。\n      enabled: true\n      # 主投递目标。\n      # local  = 写入本服务库 security_event（须 classpath 有 Store，通常配 primary-store: mysql）\n      # center = 经 Feign/Transport 上报 ingot-security 中心 admission\n      target: local\n      # target=local 且 classpath 存在多个 SecurityEventStore 时的主 Store id。\n      # 可选值：mysql（MySqlSecurityEventStore）、log（LogSecurityEventStore）。\n      # 仅有一个 Store Bean 时可省略，自动选中。\n      primary-store: mysql\n      # 次要投递目标（迁移 shadow 双写用）。稳定态留空 []。\n      # 元素取值：local | center；与主 target 去重后额外投递一份，shadow 失败不影响主链路 ack。\n      shadow-targets: []\n      # 上报方模块标识，写入 security_event.source_module。\n      # IAM 填 IAM，Member 填 MEMBER。\n      source-module: IAM\n      # 按事件大类过滤是否上报（enabled=true 时生效）；false 则该类别事件在 Publisher 层被丢弃。\n      categories:\n        # AUTH：登录成功/失败等认证类事件\n        auth: true\n        # ACCOUNT：锁定/解锁/创建/删除等账号类事件\n        account: true\n        # CREDENTIAL：改密/重置/强制改密等凭证类事件\n        credential: true\n        # ACCESS：网关封禁/限流违规等访问防护类；IAM/Member 通常不产生，可保持 true\n        access: true\n      # canonical security_event 过期物理删除（PurgeCanonicalSecurityEventTask，cron 0 30 3 * * ?）。\n      # delivery / mysql 在 in-security-policy.yml（本服务已 import）。\n      retention:\n        # 是否启用定时清理；false 等同永久保留。\n        enabled: true\n        # 保留天数；早于 now-days 的记录被删除；0 表示永久保留。\n        days: 30\n        # 单批 DELETE LIMIT 条数，避免长事务与大锁。\n        batch-size: 500\n        # 单次定时任务最多连续执行的批次数。\n        max-rounds: 100\n        # 单次 retention 任务最大执行时长（秒），超时停止本轮。\n        max-duration-seconds: 30\n        # memory/spool 队列使用率超过该百分比时，retention 让步暂停删除。\n        yield-queue-usage-percent: 50\n      # 按 eventType 覆盖默认优先级（BEST_EFFORT | DURABLE），支持 Nacos 热刷新。\n      # 未配置时使用 DefaultPriorityClassifier 内置默认表；示例：\n      # LOGIN_FAILURE: DURABLE\n      priority-overrides: {}\n  oss:\n    minio:\n      url: ${MINIO_URL:http://ingot-cloud:9090}\n      accessKey: ${MINIO_ACCESS_KEY:2NPpKzxFQjyeMTQFEXA1}\n      secretKey: ${MINIO_SECRET_KEY:8SGAp7DhqZCQrYnU9Poyu888pQOB6w4SP2ILHbVU}\n    rustfs:\n      url: ${RUSTFS_URL:http://ingot-cloud:19000}\n      accessKey: ${RUSTFS_ACCESS_KEY:7eYdiTxLbcpsfaNoKSQ0}\n      secretKey: ${RUSTFS_SECRET_KEY:PgXcoiT9bmYBrIUj6S7QHltf0w8KDzWaC5FMqLsx}\n  social:\n    wechat:\n      miniProgramAppId: wx18dc0ea8c6ca1d7d\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:true}  # 生产环境关闭\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.iam.mapper\n\n# 开发环境日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}\n', 'ee90a9a4a4dfe8a1f105ca150b2839fb', '2026-09-14 06:09:30', '2026-09-14 14:09:31', 'nacos', '172.88.0.1', 'I', 'ingot', '', 'formal', '', '{\"src_user\":\"nacos\",\"type\":\"yaml\"}');
