er = 经 Feign/Transport 上报 ingot-security 中心 admission\n      target: local\n      # target=local 且 classpath 存在多个 SecurityEventStore 时的主 Store id。\n      # 可选值：mysql（MySqlSecurityEventStore）、log（LogSecurityEventStore）。\n      # 仅有一个 Store Bean 时可省略，自动选中。\n      primary-store: mysql\n      # 次要投递目标（迁移 shadow 双写用）。稳定态留空 []。\n      # 元素取值：local | center；与主 target 去重后额外投递一份，shadow 失败不影响主链路 ack。\n      shadow-targets: []\n      # 上报方模块标识，写入 security_event.source_module。\n      # IAM 填 IAM，Member 填 MEMBER。\n      source-module: IAM\n      # 按事件大类过滤是否上报（enabled=true 时生效）；false 则该类别事件在 Publisher 层被丢弃。\n      categories:\n        # AUTH：登录成功/失败等认证类事件\n        auth: true\n        # ACCOUNT：锁定/解锁/创建/删除等账号类事件\n        account: true\n        # CREDENTIAL：改密/重置/强制改密等凭证类事件\n        credential: true\n        # ACCESS：网关封禁/限流违规等访问防护类；IAM/Member 通常不产生，可保持 true\n        access: true\n      # canonical security_event 过期物理删除（PurgeCanonicalSecurityEventTask，cron 0 30 3 * * ?）。\n      # delivery / mysql 在 in-security-policy.yml（本服务已 import）。\n      retention:\n        # 是否启用定时清理；false 等同永久保留。\n        enabled: true\n        # 保留天数；早于 now-days 的记录被删除；0 表示永久保留。\n        days: 30\n        # 单批 DELETE LIMIT 条数，避免长事务与大锁。\n        batch-size: 500\n        # 单次定时任务最多连续执行的批次数。\n        max-rounds: 100\n        # 单次 retention 任务最大执行时长（秒），超时停止本轮。\n        max-duration-seconds: 30\n        # memory/spool 队列使用率超过该百分比时，retention 让步暂停删除。\n        yield-queue-usage-percent: 50\n      # 按 eventType 覆盖默认优先级（BEST_EFFORT | DURABLE），支持 Nacos 热刷新。\n      # 未配置时使用 DefaultPriorityClassifier 内置默认表；示例：\n      # LOGIN_FAILURE: DURABLE\n      priority-overrides: {}\n  oss:\n    minio:\n      url: ${MINIO_URL:http://ingot-cloud:9090}\n      accessKey: ${MINIO_ACCESS_KEY:2NPpKzxFQjyeMTQFEXA1}\n      secretKey: ${MINIO_SECRET_KEY:8SGAp7DhqZCQrYnU9Poyu888pQOB6w4SP2ILHbVU}\n    rustfs:\n      url: ${RUSTFS_URL:http://ingot-cloud:19000}\n      accessKey: ${RUSTFS_ACCESS_KEY:7eYdiTxLbcpsfaNoKSQ0}\n      secretKey: ${RUSTFS_SECRET_KEY:PgXcoiT9bmYBrIUj6S7QHltf0w8KDzWaC5FMqLsx}\n  social:\n    wechat:\n      miniProgramAppId: wx18dc0ea8c6ca1d7d\n  # MyBatis SQL日志配置\n  mybatis:\n    show-sql-log: ${MYBATIS_SHOW_SQL:true}  # 生产环境关闭\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n  mybatisMapper: com.ingot.cloud.iam.mapper\n\n# 开发环境日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}\n', 'ee90a9a4a4dfe8a1f105ca150b2839fb', '2026-09-14 06:10:28', '2026-09-14 14:10:28', 'nacos', '172.88.0.1', 'I', 'ingot', '', 'formal', '', '{\"src_user\":\"nacos\",\"type\":\"yaml\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (371, 955, 'in-security-gateway.yml', 'DEV_GROUP', '', 'ingot:\n  security:\n    # 限流域：编译为 Sentinel GatewayFlowRule；未配置的路径默认不限流（白名单式）\n    ratelimit:\n      policy:\n        groups:\n          - code: login-auth-floor\n            name: 登录授权层\n            enabled: true\n            pattern-list:\n              - path: /bff/auth/login  # 网关对外路径（Ant 风格）；非下游 /test/**\n                method: POST           # 当前 Sentinel 编译忽略 method，保留供扩展\n          - code: api-business-floor\n            name: 公共业务层\n            enabled: true\n            pattern-list:\n              - path: /pms/**\n                method: ANY\n              - path: /member/**\n                method: ANY\n              - path: /security/**\n                method: ANY\n        rules:\n          - code: login-ip-floor\n            group-code: login-auth-floor\n            # IP / DEVICE / USER\n            dimension: IP  \n            # 平均 QPS\n            qps: 8\n            # 突发容量\n            burst: 12\n            # 统计窗口（秒）\n            interval-sec: 60\n            # F=快速失败(429) Q=排队\n            control-behavior: F\n            enabled: true\n            priority: 0\n          - code: biz-ip-floor\n            group-code: api-business-floor\n            dimension: IP\n            qps: 150\n            burst: 225\n            interval-sec: 1\n            control-behavior: F\n            enabled: true\n            priority: 10\n    # 黑白名单：静态名单 + Redis 临时封禁（限流违规升级）\n    blacklist:\n      policy:\n        items:\n          # BLACK / WHITE\n          - list-type: WHITE\n            # IP / DEVICE / USER / CIDR / USER_AGENT / REFERER\n            key-type: IP\n            key-value: 127.0.0.1\n            enabled: true\n    # 限流违规升级：滑动窗口计数\n    violation-escalation:\n      policy:\n        window-sec: 60\n        block-threshold: 25\n        temp-block-ttl-sec: 900\n        enabled: true\n    # 挑战验证地板：登录强制滑块。不要写 challenge.enabled / policy.mode\n    challenge:\n      policy:\n        groups:\n          - code: login-auth-floor\n            name: 登录认证入口\n            enabled: true\n            pattern-list:\n              - path: /bff/auth/login\n                method: POST\n        policies:\n          - code: login-always-floor\n            group-code: login-auth-floor\n            trigger: ALWAYS\n            challenge-type: SLIDER\n            scope: login\n            pass-token-ttl-sec: 300\n            pass-token-remaining: 1\n            enabled: true\n            priority: 0', 'a3710c1e1c97c58085bad92710e3de5f', '2026-09-14 06:11:23', '2026-09-14 14:11:23', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (344, 956, 'in-service-gateway.yml', 'DEV_GROUP', '', 'spring:\n  cloud:\n    gateway:\n      server:\n        webflux:\n          routes:\n            - id: openapi\n              uri: lb://in-service-gateway\n              predicates:\n                - Path=/v3/api-docs/**\n              filters:\n                - RewritePath=/v3/api-docs/(?<path>.*), /$\\{path}/$\\{path}/v3/api-docs\n            - id: in-service-iam\n              uri: lb://in-service-iam\n              predicates:\n                - Path=/iam/**\n              filters:\n                - StripPrefix=1\n            - id: in-service-member\n              uri: lb://in-service-member\n              predicates:\n                - Path=/member/**\n              filters:\n                - StripPrefix=1\n            - id: in-service-security\n              uri: lb://in-service-security\n              predicates:\n                - Path=/security/**\n              filters:\n                - StripPrefix=1\n            - id: in-crypto-pubkey\n              uri: lb://in-service-bff\n              predicates:\n                - Path=/crypto/public-keys\n            - id: in-service-bff\n              uri: lb://in-service-bff\n              predicates:\n                - Path=/bff/**\n            - id: in-service-auth\n              uri: lb://in-service-auth\n              predicates:\n                - Path=/auth/client/**\n              filters:\n                - StripPrefix=1\n\ningot:\n  vc:\n    verifyUrls: []\n    image:\n      opsLimitGetPerMinute: 20\n      opsLimitCheckPerMinute: 40\n  security:\n    account:\n      gateway:\n        # 是否启用账号锁定 AccountLockFilter，默认开启\n        enabled: true\n        # 不检查锁定状态的路径 Ant 模式。\n        excludePathPatterns:\n          - /actuator/**\n          - /bff/auth/**\n    policy:\n      # GatewayRuleClientProperties\n      client:\n        # 跨节点失效订阅开关\n        invalidation-enabled: true\n        # 是否启用 remote → LKG → Nacos 地板 弹性降级链\n        resilience-enabled: true\n        # remote 不可用且 LKG 为空时，是否回落到 Nacos 地板配置\n        local-floor-enabled: true\n        # 共享快照的分层缓存参数。\n        cache:\n          # 1级缓存存活时间\n          l1-ttl: 5m\n          # 2级缓存存活时间\n          l2-ttl: 30m\n    # 限流域：编译为 Sentinel GatewayFlowRule；未配置的路径默认不限流（白名单式）\n    ratelimit:\n      enabled: true\n      policy:\n        mode: local\n    # 黑白名单：静态名单 + Redis 临时封禁（限流违规升级）\n    blacklist:\n      enabled: false\n      policy:\n        mode: local\n    # 限流违规升级：滑动窗口计数\n    violation-escalation:\n      enabled: true\n      policy:\n        mode: local\n    # 挑战验证开关与来源；groups/policies 地板在 in-security-gateway.yml\n    challenge:\n      enabled: true\n      policy:\n        mode: local\n    # 事件配置\n    event:\n      # 总开关；Gateway 仅在上报 ACCESS 类事件时依赖此项。\n      enabled: true\n      # center：经 Feign 上报 ingot-security admission；不写网关本地 security_event 表。\n      target: center\n      # Gateway 稳定态不需要 shadow；留空 []。\n      shadow-targets: []\n      # 写入中心 security_event.source_module。\n      source-module: GATEWAY\n      # Gateway 通常只产生 ACCESS 类事件；其余类别关闭可减少无效配置。\n      categories:\n        auth: false\n        account: false\n        credential: false\n        access: true\n      # target=center 时 BEST_EFFORT 仍走 memory 缓冲后再 Feign 批量上报。\n      delivery:\n        memory:\n          queue-capacity: 2048\n          batch-size: 32\n          poll-timeout-ms: 100\n          shutdown-timeout-ms: 5000\n        # DURABLE 事件（如 BLACKLIST_BLOCK）仍需要 spool；未显式配置时使用下方 Java 默认值：\n        # spool.directory=./logs/security-recording/spool, max-bytes=1GB, ...\n      # Gateway 不写本地 canonical 表，通常不需要 retention；中心库由 in-service-security 清理。\n      retention:\n        enabled: false\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n\n# 开发环境日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}', '9f2ab6c7eeae4bb1505cfcb640c9dcdf', '2026-09-16 02:54:42', '2026-09-16 10:54:42', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
