      excludePathPatterns:\n          - /actuator/**\n          - /bff/auth/**\n    policy:\n      # GatewayRuleClientProperties\n      client:\n        # 跨节点失效订阅开关\n        invalidation-enabled: true\n        # 是否启用 remote → LKG → Nacos 地板 弹性降级链\n        resilience-enabled: true\n        # remote 不可用且 LKG 为空时，是否回落到 Nacos 地板配置\n        local-floor-enabled: true\n        # 共享快照的分层缓存参数。\n        cache:\n          # 1级缓存存活时间\n          l1-ttl: 5m\n          # 2级缓存存活时间\n          l2-ttl: 30m\n    # 限流域：编译为 Sentinel GatewayFlowRule；未配置的路径默认不限流（白名单式）\n    ratelimit:\n      enabled: true\n      policy:\n        mode: local\n    # 黑白名单：静态名单 + Redis 临时封禁（限流违规升级）\n    blacklist:\n      enabled: false\n      policy:\n        mode: local\n    # 限流违规升级：滑动窗口计数\n    violation-escalation:\n      enabled: true\n      policy:\n        mode: local\n    # 挑战验证开关与来源；groups/policies 地板在 in-security-gateway.yml\n    challenge:\n      enabled: true\n      policy:\n        mode: local\n    # 事件配置\n    event:\n      # 总开关；Gateway 仅在上报 ACCESS 类事件时依赖此项。\n      enabled: true\n      # center：经 Feign 上报 ingot-security admission；不写网关本地 security_event 表。\n      target: center\n      # Gateway 稳定态不需要 shadow；留空 []。\n      shadow-targets: []\n      # 写入中心 security_event.source_module。\n      source-module: GATEWAY\n      # Gateway 通常只产生 ACCESS 类事件；其余类别关闭可减少无效配置。\n      categories:\n        auth: false\n        account: false\n        credential: false\n        access: true\n      # target=center 时 BEST_EFFORT 仍走 memory 缓冲后再 Feign 批量上报。\n      delivery:\n        memory:\n          queue-capacity: 2048\n          batch-size: 32\n          poll-timeout-ms: 100\n          shutdown-timeout-ms: 5000\n        # DURABLE 事件（如 BLACKLIST_BLOCK）仍需要 spool；未显式配置时使用下方 Java 默认值：\n        # spool.directory=./logs/security-recording/spool, max-bytes=1GB, ...\n      # Gateway 不写本地 canonical 表，通常不需要 retention；中心库由 in-service-security 清理。\n      retention:\n        enabled: false\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n\n# 开发环境日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}', '8e274c55006057d64db3bc97e8559460', '2026-09-16 03:11:52', '2026-09-16 11:11:53', 'nacos', '172.88.0.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (0, 958, 'in-bff-apps.yml', 'DEV_GROUP', '', '# 仅 Gateway 与 BFF 加载\ningot:\n  bff:\n    require-https: false\n    apps:\n      - app-id: platform-admin\n        domain: PLATFORM\n        admin-origin: http://localhost:5799\n        login-origin: http://localhost:1799\n        oauth-client-id: in-bff-platform\n        oauth-scope: system\n        oauth-redirect-uri: http://localhost:5400/bff/auth/platform/callback\n        default-return-to: /\n      - app-id: tenant-admin\n        domain: TENANT\n        admin-origin: http://localhost:5798\n        login-origin: http://localhost:1798\n        oauth-client-id: in-bff-tenant\n        oauth-scope: system\n        oauth-redirect-uri: http://localhost:5400/bff/auth/tenant/callback\n        default-return-to: /\n', 'bbf0561c7e1673a4c606e497f9980051', '2026-09-17 02:57:56', '2026-09-17 10:57:57', 'nacos', '192.168.65.1', 'I', 'ingot', '', 'formal', '', '{\"src_user\":\"nacos\",\"type\":\"yaml\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (371, 959, 'in-security-gateway.yml', 'DEV_GROUP', '', 'ingot:\n  security:\n    # 限流域：编译为 Sentinel GatewayFlowRule；未配置的路径默认不限流（白名单式）\n    ratelimit:\n      policy:\n        groups:\n          - code: login-auth-floor\n            name: 登录授权层\n            enabled: true\n            pattern-list:\n              - path: /bff/auth/login  # 网关对外路径（Ant 风格）；非下游 /test/**\n                method: POST           # 当前 Sentinel 编译忽略 method，保留供扩展\n          - code: api-business-floor\n            name: 公共业务层\n            enabled: true\n            pattern-list:\n              - path: /iam/**\n                method: ANY\n              - path: /member/**\n                method: ANY\n              - path: /security/**\n                method: ANY\n        rules:\n          - code: login-ip-floor\n            group-code: login-auth-floor\n            # IP / DEVICE / USER\n            dimension: IP  \n            # 平均 QPS\n            qps: 8\n            # 突发容量\n            burst: 12\n            # 统计窗口（秒）\n            interval-sec: 60\n            # F=快速失败(429) Q=排队\n            control-behavior: F\n            enabled: true\n            priority: 0\n          - code: biz-ip-floor\n            group-code: api-business-floor\n            dimension: IP\n            qps: 150\n            burst: 225\n            interval-sec: 1\n            control-behavior: F\n            enabled: true\n            priority: 10\n    # 黑白名单：静态名单 + Redis 临时封禁（限流违规升级）\n    blacklist:\n      policy:\n        items:\n          # BLACK / WHITE\n          - list-type: WHITE\n            # IP / DEVICE / USER / CIDR / USER_AGENT / REFERER\n            key-type: IP\n            key-value: 127.0.0.1\n            enabled: true\n    # 限流违规升级：滑动窗口计数\n    violation-escalation:\n      policy:\n        window-sec: 60\n        block-threshold: 25\n        temp-block-ttl-sec: 900\n        enabled: true\n    # 挑战验证地板：登录强制滑块。不要写 challenge.enabled / policy.mode\n    challenge:\n      policy:\n        groups:\n          - code: login-auth-floor\n            name: 登录认证入口\n            enabled: true\n            pattern-list:\n              - path: /bff/auth/login\n                method: POST\n        policies:\n          - code: login-always-floor\n            group-code: login-auth-floor\n            trigger: ALWAYS\n            challenge-type: SLIDER\n            scope: login\n            pass-token-ttl-sec: 300\n            pass-token-remaining: 1\n            enabled: true\n            priority: 0', '4c4bd3e3d0baa64bb496567628cb6189', '2026-09-17 02:58:45', '2026-09-17 10:58:45', 'nacos', '192.168.65.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (371, 960, 'in-security-gateway.yml', 'DEV_GROUP', '', 'ingot:\n  security:\n    # 限流域：编译为 Sentinel GatewayFlowRule；未配置的路径默认不限流（白名单式）\n    ratelimit:\n      policy:\n        groups:\n          - code: login-auth-floor\n            name: 登录授权层\n            enabled: true\n            pattern-list:\n              - path: /bff/auth/platform/login\n                method: POST\n              - path: /bff/auth/tenant/login\n                method: POST\n          - code: api-business-floor\n            name: 公共业务层\n            enabled: true\n            pattern-list:\n              - path: /iam/**\n                method: ANY\n              - path: /member/**\n                method: ANY\n              - path: /security/**\n                method: ANY\n        rules:\n          - code: login-ip-floor\n            group-code: login-auth-floor\n            # IP / DEVICE / USER\n            dimension: IP  \n            # 平均 QPS\n            qps: 8\n            # 突发容量\n            burst: 12\n            # 统计窗口（秒）\n            interval-sec: 60\n            # F=快速失败(429) Q=排队\n            control-behavior: F\n            enabled: true\n            priority: 0\n          - code: biz-ip-floor\n            group-code: api-business-floor\n            dimension: IP\n            qps: 150\n            burst: 225\n            interval-sec: 1\n            control-behavior: F\n            enabled: true\n            priority: 10\n    # 黑白名单：静态名单 + Redis 临时封禁（限流违规升级）\n    blacklist:\n      policy:\n        items:\n          # BLACK / WHITE\n          - list-type: WHITE\n            # IP / DEVICE / USER / CIDR / USER_AGENT / REFERER\n            key-type: IP\n            key-value: 127.0.0.1\n            enabled: true\n    # 限流违规升级：滑动窗口计数\n    violation-escalation:\n      policy:\n        window-sec: 60\n        block-threshold: 25\n        temp-block-ttl-sec: 900\n        enabled: true\n    # 挑战验证地板：登录强制滑块。不要写 challenge.enabled / policy.mode\n    challenge:\n      policy:\n        groups:\n          - code: login-auth-floor\n            name: 登录认证入口\n            enabled: true\n            pattern-list:\n              - path: /bff/auth/login\n                method: POST\n        policies:\n          - code: login-always-floor\n            group-code: login-auth-floor\n            trigger: ALWAYS\n            challenge-type: SLIDER\n            scope: login\n            pass-token-ttl-sec: 300\n            pass-token-remaining: 1\n            enabled: true\n            priority: 0', '965d46c071bb03611f6e26fb0ecc44e7', '2026-09-17 02:59:02', '2026-09-17 10:59:03', 'nacos', '192.168.65.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (348, 961, 'in-service-bff.yml', 'DEV_GROUP', '', 'ingot:\n  security:\n    oauth2:\n      resource:\n        public-urls:\n          - /crypto/public-keys,GET\n    # 账号锁定 BFF 登录短路：解密后查 Redis name key；默认拦截不调 Auth\n    account:\n      bff:\n        # 是否在登录解密后检查 Redis name key，默认开启。\n        enabled: true\n        # BFF 拦截时是否仍调 Auth 以产生 LOGIN_FAILURE；默认关闭。\n        emit-login-failure-on-bff-block: false\n  bff:\n    client-id: ingot-bff\n    scope: system\n    # 管理用户:0, C端用户:1\n    user-type: \"0\"\n    session-ttl: 7200\n    redirect-uri: http://localhost:5400/bff/auth/callback\n    cookie:\n      # 开发环境不设置 domain（localhost 可用），生产环境设置顶级域名如 .ingotcloud.top\n      domain: ${BFF_COOKIE_DOMAIN:}\n      # 开发环境 false，生产必须 true\n      secure: ${BFF_COOKIE_SECURE:false}\n      same-site: ${BFF_COOKIE_SAME_SITE:Lax}\n    security:\n      # 客户端指纹校验，防止 Cookie 盗用\n      fingerprint-enabled: ${BFF_FINGERPRINT_ENABLED:true}\n      # 指纹模式: device（前端设备指纹，推荐）/ ip_ua（服务端 IP+UA，降级方案）\n      fingerprint-mode: ${BFF_FINGERPRINT_MODE:device}\n      # 信任的前端应用域名列表\n      allowed-frontends:\n        - http://localhost:1798\n        - http://localhost:5798\n        - http://localhost:1799\n        - http://localhost:5799\n        - http://192.168.1.190:1798\n        - http://192.168.1.190:5798\n      default-redirect-uri: http://localhost:5798\n\n# SpringDoc/Swagger配置（开发环境开启）\nspringdoc:\n  api-docs:\n    enabled: true\n    path: /v3/api-docs\n  swagger-ui:\n    enabled: true\n    path: /swagger-ui.html\n    display-request-duration: true\n    operations-sorter: alpha\n    tags-sorter: alpha\n\n# ==================== 日志配置 ====================\nlogs:\n  path: ${LOG_PATH:/ingot-data/logs}\n\n# 开发环境日志级别配置\nlogging:\n  level:\n    root: INFO\n    org.springframework.web: DEBUG\n    org.springframework.security: DEBUG\n    org.springframework.security.oauth2: DEBUG\n    org.springframework.cloud: DEBUG\n    com.alibaba.nacos.client: INFO\n    com.alibaba.cloud: INFO\n    com.ingot: DEBUG\n  logback:\n    rollingpolicy:\n      max-file-size: ${LOG_FILE_MAX_SIZE:100MB}\n      max-history: ${LOG_FILE_MAX_HISTORY:30}\n      total-size-cap: ${LOG_FILE_TOTAL_SIZE:20GB}', 'bf1c6a1576f4e8b29c6f69c5443b7ca8', '2026-09-17 03:00:01', '2026-09-17 11:00:01', 'nacos', '192.168.65.1', 'U', 'ingot', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
COMMIT;

-- ----------------------------
-- Table structure for permissions
-- ----------------------------
DROP TABLE IF EXISTS `permissions`;
CREATE TABLE `permissions` (
  `role` varchar(50) NOT NULL,
  `resource` varchar(255) NOT NULL,
  `action` varchar(8) NOT NULL,
  UNIQUE KEY `uk_role_permission` (`role`,`resource`,`action`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ----------------------------
-- Records of permissions
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for roles
